def _complete_visible_commands(ctx: Context, incomplete: str) -> cabc.Iterator[tuple[str, Command]]:
    multi = t.cast(Group, ctx.command)
    for name in multi.list_commands(ctx):
        if name.startswith(incomplete):
            command = multi.get_command(ctx, name)
            if command is not None and (not command.hidden):
                yield (name, command)

def _format_deprecated_label(deprecated: bool | str) -> str:
    label = _('deprecated').upper()
    if isinstance(deprecated, str):
        return f'({label}: {deprecated})'
    return f'({label})'

def _format_deprecated_suffix(deprecated: bool | str) -> str:
    if isinstance(deprecated, str):
        return f' {deprecated}'
    return ''

@contextmanager
def augment_usage_errors(ctx: Context, param: Parameter | None=None) -> cabc.Generator[None]:
    try:
        yield
    except BadParameter as e:
        if e.ctx is None:
            e.ctx = ctx
        if param is not None and e.param is None:
            e.param = param
        raise
    except UsageError as e:
        if e.ctx is None:
            e.ctx = ctx
        raise

def iter_params_for_processing(invocation_order: cabc.Sequence[Parameter], declaration_order: cabc.Sequence[Parameter]) -> list[Parameter]:

    def sort_key(item: Parameter) -> tuple[bool, float]:
        try:
            idx: float = invocation_order.index(item)
        except ValueError:
            idx = float('inf')
        return (not item.is_eager, idx)
    return sorted(declaration_order, key=sort_key)

def _check_iter(value: cabc.Iterable[V]) -> cabc.Iterator[V]:
    if isinstance(value, str):
        raise TypeError
    return iter(value)

@contextmanager
def scope(self, cleanup: bool=True) -> cabc.Generator[Context]:
    if not cleanup:
        self._depth += 1
    try:
        with self as rv:
            yield rv
    finally:
        if not cleanup:
            self._depth -= 1

@property
def meta(self) -> dict[str, t.Any]:
    return self._meta

@property
def command_path(self) -> str:
    rv = ''
    if self.info_name is not None:
        rv = self.info_name
    if self.parent is not None:
        parent_command_path = [self.parent.command_path]
        if isinstance(self.parent.command, Command):
            for param in self.parent.command.get_params(self):
                parent_command_path.extend(param.get_usage_pieces(self))
        rv = f"{' '.join(parent_command_path)} {rv}"
    return rv.lstrip()

def find_root(self) -> Context:
    node = self
    while node.parent is not None:
        node = node.parent
    return node

def find_object(self, object_type: type[V]) -> V | None:
    node: Context | None = self
    while node is not None:
        if isinstance(node.obj, object_type):
            return node.obj
        node = node.parent
    return None

def ensure_object(self, object_type: type[V]) -> V:
    rv = self.find_object(object_type)
    if rv is None:
        self.obj = rv = object_type()
    return rv

def lookup_default(self, name: str, call: bool=True) -> t.Any | None:
    if not self._default_map_has(name):
        return None
    assert self.default_map is not None
    value = self.default_map[name]
    if call and callable(value):
        return value()
    return value

def exit(self, code: int=0) -> t.NoReturn:
    self.close()
    raise Exit(code)

def invoke(self, callback: Command | t.Callable[..., V], /, *args: t.Any, **kwargs: t.Any) -> t.Any | V:
    if isinstance(callback, Command):
        other_cmd = callback
        if other_cmd.callback is None:
            raise TypeError('The given command does not have a callback that can be invoked.')
        else:
            callback = t.cast('t.Callable[..., V]', other_cmd.callback)
        ctx = self._make_sub_context(other_cmd)
        for param in other_cmd.params:
            if param.name not in kwargs and param.expose_value:
                default_value = param.get_default(ctx)
                if default_value is UNSET:
                    default_value = None
                kwargs[param.name] = param.type_cast_value(ctx, default_value)
        ctx.params.update(kwargs)
    else:
        ctx = self
    with augment_usage_errors(self), ctx:
        return callback(*args, **kwargs)

def forward(self, cmd: Command, /, *args: t.Any, **kwargs: t.Any) -> t.Any:
    if not isinstance(cmd, Command):
        raise TypeError('Callback is not a command.')
    for param in self.params:
        if param not in kwargs:
            kwargs[param] = self.params[param]
    return self.invoke(cmd, *args, **kwargs)

def get_usage(self, ctx: Context) -> str:
    formatter = ctx.make_formatter()
    self.format_usage(ctx, formatter)
    return formatter.getvalue().rstrip('\n')

def format_usage(self, ctx: Context, formatter: HelpFormatter) -> None:
    pieces = self.collect_usage_pieces(ctx)
    formatter.write_usage(ctx.command_path, ' '.join(pieces))

def collect_usage_pieces(self, ctx: Context) -> list[str]:
    rv = [self.options_metavar] if self.options_metavar else []
    for param in self.get_params(ctx):
        rv.extend(param.get_usage_pieces(ctx))
    return rv

def get_help_option_names(self, ctx: Context) -> list[str]:
    all_names = set(ctx.help_option_names)
    for param in self.params:
        all_names.difference_update(param.opts)
        all_names.difference_update(param.secondary_opts)
    return list(all_names)

def get_help_option(self, ctx: Context) -> Option | None:
    help_option_names = self.get_help_option_names(ctx)
    if not help_option_names or not self.add_help_option:
        return None
    if self._help_option is None:
        from .decorators import help_option
        help_option(*help_option_names, _HELP_OPTION_STORAGE_NAME)(self)
        self._help_option = self.params.pop()
    return self._help_option

def make_parser(self, ctx: Context) -> _OptionParser:
    parser = _OptionParser(ctx)
    for param in self.get_params(ctx):
        param.add_to_parser(parser, ctx)
    return parser

def get_help(self, ctx: Context) -> str:
    formatter = ctx.make_formatter()
    self.format_help(ctx, formatter)
    return formatter.getvalue().rstrip('\n')

def get_short_help_str(self, limit: int=45) -> str:
    if self.short_help:
        text = inspect.cleandoc(self.short_help)
    elif self.help:
        text = _make_default_short_help(self.help, limit)
    else:
        text = ''
    if self.deprecated:
        text = f'{_(text)} {_format_deprecated_label(self.deprecated)}'
    return text.strip()

def format_help_text(self, ctx: Context, formatter: HelpFormatter) -> None:
    if self.help is not None:
        text = inspect.cleandoc(self.help).partition('\x0c')[0]
    else:
        text = ''
    if self.deprecated:
        label = _format_deprecated_label(self.deprecated)
        text = f'{_(text)} {label}' if text else label
    if text:
        formatter.write_paragraph()
        with formatter.indentation():
            formatter.write_text(text)

def format_options(self, ctx: Context, formatter: HelpFormatter) -> None:
    opts = []
    for param in self.get_params(ctx):
        rv = param.get_help_record(ctx)
        if rv is not None and (not isinstance(param, Argument)):
            opts.append(rv)
    if opts:
        with formatter.section(_('Options')):
            formatter.write_dl(opts)

def format_arguments(self, ctx: Context, formatter: HelpFormatter) -> None:
    args = []
    for param in self.get_params(ctx):
        rv = param.get_help_record(ctx)
        if rv is not None and isinstance(param, Argument):
            args.append(rv)
    if args:
        with formatter.section(_('Positional arguments')):
            formatter.write_dl(args)

def format_epilog(self, ctx: Context, formatter: HelpFormatter) -> None:
    if self.epilog:
        epilog = inspect.cleandoc(self.epilog)
        formatter.write_paragraph()
        with formatter.indentation():
            formatter.write_text(epilog)

def make_context(self, info_name: str | None, args: list[str], parent: Context | None=None, **extra: t.Any) -> Context:
    for key, value in self.context_settings.items():
        if key not in extra:
            extra[key] = value
    ctx = self.context_class(self, info_name=info_name, parent=parent, **extra)
    with ctx.scope(cleanup=False):
        self.parse_args(ctx, args)
    return ctx

def invoke(self, ctx: Context) -> t.Any:
    if self.deprecated:
        message = _('DeprecationWarning: The command {name!r} is deprecated.{extra_message}').format(name=self.name, extra_message=_format_deprecated_suffix(self.deprecated))
        echo(style(message, fg='red'), err=True)
    if self.callback is not None:
        return ctx.invoke(self.callback, **ctx.params)

def shell_complete(self, ctx: Context, incomplete: str) -> list[CompletionItem]:
    from click.shell_completion import CompletionItem
    results: list[CompletionItem] = []
    if incomplete and (not incomplete[0].isalnum()):
        for param in self.get_params(ctx):
            if not isinstance(param, Option) or param.hidden or (not param.multiple and ctx.get_parameter_source(param.name) is ParameterSource.COMMANDLINE):
                continue
            results.extend((CompletionItem(name, help=param.help) for name in [*param.opts, *param.secondary_opts] if name.startswith(incomplete)))
    while ctx.parent is not None:
        ctx = ctx.parent
        if isinstance(ctx.command, Group) and ctx.command.chain:
            results.extend((CompletionItem(name, help=command.get_short_help_str()) for name, command in _complete_visible_commands(ctx, incomplete) if name not in ctx._protected_args))
    return results

def main(self, args: cabc.Sequence[str] | None=None, prog_name: str | None=None, complete_var: str | None=None, standalone_mode: bool=True, windows_expand_args: bool=True, **extra: t.Any) -> t.Any:
    if args is None:
        args = sys.argv[1:]
        if os.name == 'nt' and windows_expand_args:
            args = _expand_args(args)
    else:
        args = list(args)
    if prog_name is None:
        prog_name = _detect_program_name()
    self._main_shell_completion(extra, prog_name, complete_var)
    try:
        try:
            with self.make_context(prog_name, args, **extra) as ctx:
                rv = self.invoke(ctx)
                if not standalone_mode:
                    return rv
                ctx.exit()
        except (EOFError, KeyboardInterrupt) as e:
            echo(file=sys.stderr)
            raise Abort() from e
        except ClickException as e:
            if not standalone_mode:
                raise
            e.show()
            sys.exit(e.exit_code)
        except OSError as e:
            if e.errno == errno.EPIPE:
                sys.stdout = t.cast(t.TextIO, _PacifyFlushWrapper(sys.stdout))
                sys.stderr = t.cast(t.TextIO, _PacifyFlushWrapper(sys.stderr))
                sys.exit(1)
            else:
                raise
    except Exit as e:
        if standalone_mode:
            sys.exit(e.exit_code)
        else:
            return e.exit_code
    except Abort:
        if not standalone_mode:
            raise
        echo(_('Aborted!'), file=sys.stderr)
        sys.exit(1)

def _main_shell_completion(self, ctx_args: cabc.MutableMapping[str, t.Any], prog_name: str, complete_var: str | None=None) -> None:
    if complete_var is None:
        complete_name = prog_name.replace('-', '_').replace('.', '_')
        complete_var = f'_{complete_name}_COMPLETE'.upper()
    instruction = os.environ.get(complete_var)
    if not instruction:
        return
    from .shell_completion import shell_complete
    rv = shell_complete(self, ctx_args, prog_name, complete_var, instruction)
    sys.exit(rv)

def add_command(self, cmd: Command, name: str | None=None) -> None:
    name = name or cmd.name
    if name is None:
        raise TypeError('Command has no name.')
    _check_nested_chain(self, name, cmd, register=True)
    self.commands[name] = cmd

def command(self, *args: t.Any, **kwargs: t.Any) -> t.Callable[[t.Callable[..., t.Any]], Command] | Command:
    from .decorators import command
    func: t.Callable[..., t.Any] | None = None
    if args and callable(args[0]):
        assert len(args) == 1 and (not kwargs), "Use 'command(**kwargs)(callable)' to provide arguments."
        func, = args
        args = ()
    if self.command_class and kwargs.get('cls') is None:
        kwargs['cls'] = self.command_class

    def decorator(f: t.Callable[..., t.Any]) -> Command:
        cmd: Command = command(*args, **kwargs)(f)
        self.add_command(cmd)
        return cmd
    if func is not None:
        return decorator(func)
    return decorator

def group(self, *args: t.Any, **kwargs: t.Any) -> t.Callable[[t.Callable[..., t.Any]], Group] | Group:
    from .decorators import group
    func: t.Callable[..., t.Any] | None = None
    if args and callable(args[0]):
        assert len(args) == 1 and (not kwargs), "Use 'group(**kwargs)(callable)' to provide arguments."
        func, = args
        args = ()
    if self.group_class is not None and kwargs.get('cls') is None:
        if self.group_class is type:
            kwargs['cls'] = type(self)
        else:
            kwargs['cls'] = self.group_class

    def decorator(f: t.Callable[..., t.Any]) -> Group:
        cmd: Group = group(*args, **kwargs)(f)
        self.add_command(cmd)
        return cmd
    if func is not None:
        return decorator(func)
    return decorator

def result_callback(self, replace: bool=False) -> t.Callable[[F], F]:

    def decorator(f: F) -> F:
        old_callback = self._result_callback
        if old_callback is None or replace:
            self._result_callback = f
            return f

        def function(value: t.Any, /, *args: t.Any, **kwargs: t.Any) -> t.Any:
            inner = old_callback(value, *args, **kwargs)
            return f(inner, *args, **kwargs)
        self._result_callback = rv = update_wrapper(t.cast(F, function), f)
        return rv
    return decorator

def format_commands(self, ctx: Context, formatter: HelpFormatter) -> None:
    commands = []
    for subcommand in self.list_commands(ctx):
        cmd = self.get_command(ctx, subcommand)
        if cmd is None:
            continue
        if cmd.hidden:
            continue
        commands.append((subcommand, cmd))
    if len(commands):
        limit = formatter.width - 6 - max((len(cmd[0]) for cmd in commands))
        rows = []
        for subcommand, cmd in commands:
            help = cmd.get_short_help_str(limit)
            rows.append((subcommand, help))
        if rows:
            with formatter.section(_('Commands')):
                formatter.write_dl(rows)

@staticmethod
def _hide_unset(value: t.Any) -> t.Any:
    return None if value is UNSET else value

@property
def human_readable_name(self) -> str:
    return self.name

def get_default(self, ctx: Context, call: bool=True) -> t.Any | t.Callable[[], t.Any] | None:
    value = ctx.lookup_default(self.name, call=False)
    if value is None and (not ctx._default_map_has(self.name)):
        value = self.default
    if call and callable(value):
        value = value()
    return value

def consume_value(self, ctx: Context, opts: cabc.Mapping[str, t.Any]) -> tuple[t.Any, ParameterSource]:
    value = opts.get(self.name, UNSET)
    source = ParameterSource.COMMANDLINE if value is not UNSET else ParameterSource.DEFAULT
    if value is UNSET:
        envvar_value = self.value_from_envvar(ctx)
        if envvar_value is not None:
            value = envvar_value
            source = ParameterSource.ENVIRONMENT
    if value is UNSET:
        default_map_value = ctx.lookup_default(self.name)
        if default_map_value is not None or ctx._default_map_has(self.name):
            value = default_map_value
            source = ParameterSource.DEFAULT_MAP
            if isinstance(value, str) and self.nargs != 1:
                value = self.type.split_envvar_value(value)
    if value is UNSET:
        default_value = self.get_default(ctx)
        if default_value is not UNSET:
            value = default_value
            source = ParameterSource.DEFAULT
    return (value, source)

def type_cast_value(self, ctx: Context, value: t.Any) -> t.Any:
    if value is None:
        if self.multiple or self.nargs == -1:
            return ()
        else:
            return value

    def check_iter(value: t.Any) -> cabc.Iterator[t.Any]:
        try:
            return _check_iter(value)
        except TypeError:
            raise BadParameter(_('Value must be an iterable.'), ctx=ctx, param=self) from None
    if self.nargs == 1 or self.type.is_composite:

        def convert(value: t.Any) -> t.Any:
            return self.type(value, param=self, ctx=ctx)
    elif self.nargs == -1:

        def convert(value: t.Any) -> t.Any:
            return tuple((self.type(x, self, ctx) for x in check_iter(value)))
    else:

        def convert(value: t.Any) -> t.Any:
            value = tuple(check_iter(value))
            if len(value) != self.nargs:
                raise BadParameter(ngettext('Takes {nargs} values but 1 was given.', 'Takes {nargs} values but {len} were given.', len(value)).format(nargs=self.nargs, len=len(value)), ctx=ctx, param=self)
            return tuple((self.type(x, self, ctx) for x in value))
    if self.multiple:
        return tuple((convert(x) for x in check_iter(value)))
    return convert(value)

def value_is_missing(self, value: t.Any) -> bool:
    if value is UNSET:
        return True
    if (self.nargs != 1 or self.multiple) and value == ():
        return True
    return False

def process_value(self, ctx: Context, value: t.Any) -> t.Any:
    if value is UNSET:
        if self.multiple or self.nargs == -1:
            value = ()
    else:
        value = self.type_cast_value(ctx, value)
    if self.required and self.value_is_missing(value):
        raise MissingParameter(ctx=ctx, param=self)
    if self.callback is not None:
        if value is UNSET:
            value = None
        unset_keys = {k: None for k, v in ctx.params.items() if v is UNSET}
        if not unset_keys:
            value = self.callback(ctx, self, value)
        else:
            with ctx:
                ctx.params.update(unset_keys)
                value = self.callback(ctx, self, value)
                ctx.params.update({k: UNSET for k in unset_keys if k in ctx.params and ctx.params[k] is None})
    return value

def resolve_envvar_value(self, ctx: Context) -> str | None:
    if not self.envvar:
        return None
    if isinstance(self.envvar, str):
        rv = os.environ.get(self.envvar)
        if rv:
            return rv
    else:
        for envvar in self.envvar:
            rv = os.environ.get(envvar)
            if rv:
                return rv
    return None

def value_from_envvar(self, ctx: Context) -> str | cabc.Sequence[str] | None:
    rv = self.resolve_envvar_value(ctx)
    if rv is not None and self.nargs != 1:
        return self.type.split_envvar_value(rv)
    return rv

def handle_parse_result(self, ctx: Context, opts: cabc.Mapping[str, t.Any], args: list[str]) -> tuple[t.Any, list[str]]:
    existing_value = ctx.params.get(self.name, UNSET)
    existing_source = ctx.get_parameter_source(self.name)
    existing_default_explicit = ctx._param_default_explicit.get(self.name, False)
    with augment_usage_errors(ctx, param=self):
        value, source = self.consume_value(ctx, opts)
        ctx.set_parameter_source(self.name, source)
        if self.deprecated and value is not UNSET and (source < ParameterSource.DEFAULT_MAP):
            message = _('DeprecationWarning: The {param_type} {name!r} is deprecated.{extra_message}').format(param_type=self.param_type_name, name=self.human_readable_name, extra_message=_format_deprecated_suffix(self.deprecated))
            echo(style(message, fg='red'), err=True)
        try:
            value = self.process_value(ctx, value)
        except Exception:
            if not ctx.resilient_parsing:
                raise
            value = UNSET
    slot_empty = existing_value is UNSET
    more_explicit = existing_source is not None and source < existing_source
    same_source = existing_source is not None and source == existing_source
    auto_would_downgrade_explicit = same_source and source == ParameterSource.DEFAULT and existing_default_explicit and (not self._default_explicit)
    is_winner = slot_empty or more_explicit or (same_source and (not auto_would_downgrade_explicit))
    if is_winner:
        if self.expose_value:
            ctx.params[self.name] = value
            ctx._param_default_explicit[self.name] = self._default_explicit
    elif existing_source is not None:
        ctx.set_parameter_source(self.name, existing_source)
    return (value, args)

def get_error_hint(self, ctx: Context | None) -> str:
    hint_list = self.opts or [self.human_readable_name]
    return ' / '.join((f"'{x}'" for x in hint_list))

def shell_complete(self, ctx: Context, incomplete: str) -> list[CompletionItem]:
    if self._custom_shell_complete is not None:
        results = self._custom_shell_complete(ctx, self, incomplete)
        if results and isinstance(results[0], str):
            from click.shell_completion import CompletionItem
            results = [CompletionItem(c) for c in results]
        return t.cast('list[CompletionItem]', results)
    return self.type.shell_complete(ctx, self, incomplete)

@property
def is_bool_flag(self) -> bool:
    return self.is_flag and isinstance(self.type, types.BoolParamType)

@property
def flag_activation_value(self) -> t.Any:
    if self.flag_value is UNSET:
        return True if self.is_flag else None
    return self.flag_value

def _infer_flag_kind(self, is_flag: bool | None, flag_value: t.Any) -> tuple[bool, bool]:
    needs_value = self.prompt is not None and (not self.prompt_required)
    if is_flag is None:
        if flag_value is not UNSET:
            return (True, needs_value)
        if needs_value:
            return (False, needs_value)
        if self.secondary_opts:
            return (True, needs_value)
        return (False, needs_value)
    if is_flag is False and (not needs_value):
        needs_value = flag_value is not UNSET or self.default is UNSET
    return (bool(is_flag), needs_value)

def _pick_type(self, type_arg: t.Any, flag_value: t.Any, count: bool, is_flag: bool) -> types.ParamType[t.Any]:
    if type_arg is not None:
        return self.type
    if count:
        return types.IntRange(min=0)
    if not is_flag:
        return self.type
    if flag_value is UNSET or isinstance(flag_value, bool):
        return types.BoolParamType()
    guessed: types.ParamType[t.Any] = types.convert_type(None, flag_value)
    if isinstance(guessed, types.StringParamType) and (not isinstance(flag_value, str)) and (flag_value is not None):
        return types.UNPROCESSED
    return guessed

def _resolve_lazy_default(self, value: t.Any) -> t.Any:
    if value is UNSET and self.is_flag:
        if self.multiple and (not self.required) and (not self.prompt):
            return ()
        if self.is_bool_flag and (not self.required):
            return False
    if value is True and self.is_flag and (not self.is_bool_flag):
        return self.flag_activation_value
    return value

def _validate(self, prompt: bool | str, deprecated: bool | str) -> None:
    if not __debug__:
        return
    if deprecated and prompt:
        raise ValueError('`deprecated` options cannot use `prompt`.')
    if self.nargs == -1:
        raise TypeError('nargs=-1 is not supported for options.')
    if not self.is_bool_flag and self.secondary_opts:
        raise TypeError('Secondary flag is not valid for non-boolean flag.')
    if self.is_bool_flag and self.hide_input and (self.prompt is not None):
        raise TypeError("'prompt' with 'hide_input' is not valid for boolean flag.")
    if self.count:
        if self.multiple:
            raise TypeError("'count' is not valid with 'multiple'.")
        if self.is_flag:
            raise TypeError("'count' is not valid with 'is_flag'.")

def get_default(self, ctx: Context, call: bool=True) -> t.Any | t.Callable[[], t.Any] | None:
    raw = super().get_default(ctx, call=False)
    value = self._resolve_lazy_default(raw)
    if value is raw and call and callable(value):
        value = value()
    return value

def prompt_for_value(self, ctx: Context) -> t.Any:
    assert self.prompt is not None
    default = self.get_default(ctx)
    if self.is_bool_flag:
        if default in (UNSET, None):
            default = None
        else:
            default = bool(default)
        return confirm(self.prompt, default)
    prompt_kwargs: t.Any = {}
    if self.show_default is not None:
        prompt_kwargs['show_default'] = self.show_default
    return prompt(self.prompt, default=self._hide_unset(default), type=self.type, hide_input=self.hide_input, show_choices=self.show_choices, confirmation_prompt=self.confirmation_prompt, value_proc=lambda x: self.process_value(ctx, x), **prompt_kwargs)

def resolve_envvar_value(self, ctx: Context) -> str | None:
    rv = super().resolve_envvar_value(ctx)
    if rv is not None:
        return rv
    if self.allow_from_autoenv and ctx.auto_envvar_prefix is not None and self.name:
        envvar = f'{ctx.auto_envvar_prefix}_{self.name.upper()}'
        rv = os.environ.get(envvar)
        if rv:
            return rv
    return None

def value_from_envvar(self, ctx: Context) -> t.Any:
    rv = self.resolve_envvar_value(ctx)
    if rv is None:
        return None
    if self.is_flag and (not self.is_bool_flag):
        if rv == self.flag_value:
            return self.flag_value
        parsed = types.BoolParamType.str_to_bool(rv)
        if parsed is None:
            return None
        return self.flag_value if parsed else False
    value_depth = (self.nargs != 1) + bool(self.multiple)
    if value_depth > 0:
        multi_rv = self.type.split_envvar_value(rv)
        if self.multiple and self.nargs != 1:
            multi_rv = batch(multi_rv, self.nargs)
        return multi_rv
    return rv

def consume_value(self, ctx: Context, opts: cabc.Mapping[str, Parameter]) -> tuple[t.Any, ParameterSource]:
    value, source = super().consume_value(ctx, opts)
    if value is FLAG_NEEDS_VALUE:
        if self.prompt is not None and (not ctx.resilient_parsing):
            value = self.prompt_for_value(ctx)
            source = ParameterSource.PROMPT
        else:
            value = self.flag_activation_value
            source = ParameterSource.COMMANDLINE
    elif self.multiple and value is not UNSET and isinstance(value, cabc.Iterable) and (source < ParameterSource.DEFAULT_MAP) and any((v is FLAG_NEEDS_VALUE for v in value)):
        value = [self.flag_activation_value if v is FLAG_NEEDS_VALUE else v for v in value]
        source = ParameterSource.COMMANDLINE
    elif (value is UNSET or source >= ParameterSource.DEFAULT_MAP) and self.prompt is not None and (self.required or self.prompt_required) and (not ctx.resilient_parsing):
        value = self.prompt_for_value(ctx)
        source = ParameterSource.PROMPT
    return (value, source)

def pass_context(f: t.Callable[te.Concatenate[Context, P], R]) -> t.Callable[P, R]:

    def new_func(*args: P.args, **kwargs: P.kwargs) -> R:
        return f(get_current_context(), *args, **kwargs)
    return update_wrapper(new_func, f)

def pass_obj(f: t.Callable[te.Concatenate[T, P], R]) -> t.Callable[P, R]:

    def new_func(*args: P.args, **kwargs: P.kwargs) -> R:
        return f(get_current_context().obj, *args, **kwargs)
    return update_wrapper(new_func, f)

def make_pass_decorator(object_type: type[T], ensure: bool=False) -> t.Callable[[t.Callable[te.Concatenate[T, P], R]], t.Callable[P, R]]:

    def decorator(f: t.Callable[te.Concatenate[T, P], R]) -> t.Callable[P, R]:

        def new_func(*args: P.args, **kwargs: P.kwargs) -> R:
            ctx = get_current_context()
            obj: T | None
            if ensure:
                obj = ctx.ensure_object(object_type)
            else:
                obj = ctx.find_object(object_type)
            if obj is None:
                raise RuntimeError(f'Managed to invoke callback without a context object of type {object_type.__name__!r} existing.')
            return ctx.invoke(f, obj, *args, **kwargs)
        return update_wrapper(new_func, f)
    return decorator

docstring:
Given an object type this creates a decorator that will work
similar to :func:`pass_obj` but instead of passing the object of the
current context, it will find the innermost context of type
:func:`object_type`.

This generates a decorator that works roughly like this::

    from functools import update_wrapper

    def decorator(f):
        @pass_context
        def new_func(ctx, *args, **kwargs):
            obj = ctx.find_object(object_type)
            return ctx.invoke(f, obj, *args, **kwargs)
        return update_wrapper(new_func, f)
    return decorator

:param object_type: the type of the object to pass.
:param ensure: if set to `True`, a new object will be created and
               remembered on the context if it's not there yet.

