def wrap_text(text: str, width: int=78, initial_indent: str='', subsequent_indent: str='', preserve_paragraphs: bool=False) -> str:
    from ._textwrap import TextWrapper
    text = text.expandtabs()
    wrapper = TextWrapper(width, initial_indent=initial_indent, subsequent_indent=subsequent_indent, replace_whitespace=False)
    if not preserve_paragraphs:
        return wrapper.fill(text)
    p: list[tuple[int, bool, str]] = []
    buf: list[str] = []
    indent = None

    def _flush_par() -> None:
        if not buf:
            return
        if buf[0].strip() == '\x08':
            p.append((indent or 0, True, '\n'.join(buf[1:])))
        else:
            p.append((indent or 0, False, ' '.join(buf)))
        del buf[:]
    for line in text.splitlines():
        if not line:
            _flush_par()
            indent = None
        else:
            if indent is None:
                orig_len = term_len(line)
                line = line.lstrip()
                indent = orig_len - term_len(line)
            buf.append(line)
    _flush_par()
    rv = []
    for indent, raw, text in p:
        with wrapper.extra_indent(' ' * indent):
            if raw:
                rv.append(wrapper.indent_only(text))
            else:
                rv.append(wrapper.fill(text))
    return '\n\n'.join(rv)

def join_options(options: cabc.Iterable[str]) -> tuple[str, bool]:
    rv = []
    any_prefix_is_slash = False
    for opt in options:
        prefix = _split_opt(opt)[0]
        if prefix == '/':
            any_prefix_is_slash = True
        rv.append((len(prefix), opt))
    rv.sort(key=lambda x: x[0])
    return (', '.join((x[1] for x in rv)), any_prefix_is_slash)

def write_paragraph(self) -> None:
    if self.buffer:
        self.write('\n')

def write_dl(self, rows: cabc.Iterable[tuple[str, str]], col_max: int=30, col_spacing: int=2) -> None:
    rows = list(rows)
    widths = measure_table(rows)
    if len(widths) != 2:
        raise TypeError('Expected two columns for definition list')
    first_col = min(widths[0], col_max) + col_spacing
    for first, second in iter_rows(rows, len(widths)):
        self.write(f"{'':>{self.current_indent}}{first}")
        if not second:
            self.write('\n')
            continue
        if term_len(first) <= first_col - col_spacing:
            self.write(' ' * (first_col - term_len(first)))
        else:
            self.write('\n')
            self.write(' ' * (first_col + self.current_indent))
        text_width = max(self.width - first_col - 2, 10)
        wrapped_text = wrap_text(second, text_width, preserve_paragraphs=True)
        lines = wrapped_text.splitlines()
        if lines:
            self.write(f'{lines[0]}\n')
            for line in lines[1:]:
                self.write(f"{'':>{first_col + self.current_indent}}{line}\n")
        else:
            self.write('\n')

