def get_current_context(silent: bool=False) -> Context | None:
    try:
        return t.cast('Context', _local.stack[-1])
    except (AttributeError, IndexError) as e:
        if not silent:
            raise RuntimeError('There is no active click context.') from e
    return None

def resolve_color_default(color: bool | None=None) -> bool | None:
    if color is not None:
        return color
    ctx = get_current_context(silent=True)
    if ctx is not None:
        return ctx.color
    return None

def _unpack_args(args: cabc.Sequence[str], nargs_spec: cabc.Sequence[int]) -> tuple[cabc.Sequence[str | cabc.Sequence[str | T_UNSET] | T_UNSET], list[str]]:
    args = deque(args)
    nargs_spec = deque(nargs_spec)
    rv: list[str | tuple[str | T_UNSET, ...] | T_UNSET] = []
    spos: int | None = None

    def _fetch(c: deque[str]) -> str | T_UNSET:
        try:
            if spos is None:
                return c.popleft()
            else:
                return c.pop()
        except IndexError:
            return UNSET
    while nargs_spec:
        if spos is None:
            nargs = nargs_spec.popleft()
        else:
            nargs = nargs_spec.pop()
        if nargs == 1:
            rv.append(_fetch(args))
        elif nargs > 1:
            x: list[str | T_UNSET] = [_fetch(args) for _ in range(nargs)]
            if spos is not None:
                x.reverse()
            rv.append(tuple(x))
        elif nargs < 0:
            if spos is not None:
                raise TypeError('Cannot have two nargs < 0')
            spos = len(rv)
            rv.append(UNSET)
    if spos is not None:
        rv[spos] = tuple(args)
        args = []
        rv[spos + 1:] = reversed(rv[spos + 1:])
    return (tuple(rv), list(args))

def add_option(self, obj: CoreOption, opts: cabc.Sequence[str], dest: str | None, action: str | None=None, nargs: int=1, const: t.Any | None=None) -> None:
    opts = [_normalize_opt(opt, self.ctx) for opt in opts]
    option = _Option(obj, opts, dest, action=action, nargs=nargs, const=const)
    self._opt_prefixes.update(option.prefixes)
    for opt in option._short_opts:
        self._short_opt[opt] = option
    for opt in option._long_opts:
        self._long_opt[opt] = option

def parse_args(self, args: list[str]) -> tuple[dict[str, t.Any], list[str], list[CoreParameter]]:
    state = _ParsingState(args)
    try:
        self._process_args_for_options(state)
        self._process_args_for_args(state)
    except UsageError:
        if self.ctx is None or not self.ctx.resilient_parsing:
            raise
    return (state.opts, state.largs, state.order)

def shell_complete(cli: Command, ctx_args: cabc.MutableMapping[str, t.Any], prog_name: str, complete_var: str, instruction: str) -> t.Literal[0, 1]:
    shell, _, instruction = instruction.partition('_')
    comp_cls = get_completion_class(shell)
    if comp_cls is None:
        return 1
    comp = comp_cls(cli, ctx_args, prog_name, complete_var)
    if instruction == 'source':
        echo(comp.source().encode(), nl=False)
        return 0
    if instruction == 'complete':
        echo(comp.complete().encode())
        return 0
    return 1

def add_completion_class(cls: type[_ShellCompleteT], name: str | None=None) -> type[_ShellCompleteT]:
    if name is None:
        name = cls.name
    _available_shells[name] = cls
    return cls

def _is_incomplete_argument(ctx: Context, param: Parameter) -> bool:
    if not isinstance(param, Argument):
        return False
    value = ctx.params.get(param.name)
    return param.nargs == -1 or ctx.get_parameter_source(param.name) is not ParameterSource.COMMANDLINE or (param.nargs > 1 and isinstance(value, (tuple, list)) and (len(value) < param.nargs))

def _start_of_option(ctx: Context, value: str) -> bool:
    if not value:
        return False
    c = value[0]
    return c in ctx._opt_prefixes

def _is_incomplete_option(ctx: Context, args: list[str], param: Parameter) -> bool:
    if not isinstance(param, Option):
        return False
    if param.is_flag or param.count:
        return False
    last_option = None
    for index, arg in enumerate(reversed(args)):
        if index + 1 > param.nargs:
            break
        if _start_of_option(ctx, arg):
            last_option = arg
            break
    return last_option is not None and last_option in param.opts

def _resolve_context(cli: Command, ctx_args: cabc.MutableMapping[str, t.Any], prog_name: str, args: list[str]) -> Context:
    ctx_args['resilient_parsing'] = True
    with cli.make_context(prog_name, args.copy(), **ctx_args) as ctx:
        args = ctx._protected_args + ctx.args
        while args:
            command = ctx.command
            if isinstance(command, Group):
                if not command.chain:
                    name, cmd, args = command.resolve_command(ctx, args)
                    if cmd is None:
                        return ctx
                    with cmd.make_context(name, args, parent=ctx, resilient_parsing=True) as sub_ctx:
                        ctx = sub_ctx
                        args = ctx._protected_args + ctx.args
                else:
                    sub_ctx = ctx
                    while args:
                        name, cmd, args = command.resolve_command(ctx, args)
                        if cmd is None:
                            return ctx
                        with cmd.make_context(name, args, parent=ctx, allow_extra_args=True, allow_interspersed_args=False, resilient_parsing=True) as sub_sub_ctx:
                            sub_ctx = sub_sub_ctx
                            args = sub_ctx.args
                    ctx = sub_ctx
                    args = [*sub_ctx._protected_args, *sub_ctx.args]
            else:
                break
    return ctx

def _resolve_incomplete(ctx: Context, args: list[str], incomplete: str) -> tuple[Command | Parameter, str]:
    if incomplete == '=':
        incomplete = ''
    elif '=' in incomplete and _start_of_option(ctx, incomplete):
        name, _, incomplete = incomplete.partition('=')
        args.append(name)
    if '--' not in args and _start_of_option(ctx, incomplete):
        return (ctx.command, incomplete)
    params = ctx.command.get_params(ctx)
    for param in params:
        if _is_incomplete_option(ctx, args, param):
            return (param, incomplete)
    for param in params:
        if _is_incomplete_argument(ctx, param):
            return (param, incomplete)
    return (ctx.command, incomplete)

@property
def func_name(self) -> str:
    safe_name = re.sub('\\W*', '', self.prog_name.replace('-', '_'), flags=re.ASCII)
    return f'_{safe_name}_completion'

def get_completions(self, args: list[str], incomplete: str) -> list[CompletionItem[str]]:
    ctx = _resolve_context(self.cli, self.ctx_args, self.prog_name, args)
    obj, incomplete = _resolve_incomplete(ctx, args, incomplete)
    return obj.shell_complete(ctx, incomplete)

def complete(self) -> str:
    args, incomplete = self.get_completion_args()
    completions = self.get_completions(args, incomplete)
    out = [self.format_completion(item) for item in completions]
    return '\n'.join(out)

def format_completion(self, item: CompletionItem[str]) -> str:
    if item.help:
        help_ = item.help.replace('\n', '\\n').replace('\t', ' ')
        return f'{item.type},{item.value}\t{help_}'
    return f'{item.type},{item.value}'

def _mask_hidden_input(message: str, value: str) -> str:
    message = message.replace(repr(value), _HIDDEN_INPUT_MASK)
    if value:
        message = re.sub(f'(?<!\\w){re.escape(value)}(?!\\w)', _HIDDEN_INPUT_MASK, message)
    return message

def _readline_prompt(func: t.Callable[[str], str], text: str, err: bool) -> str:
    stream = sys.stderr if err else sys.stdout
    if _compat.should_strip_ansi(stream, resolve_color_default()):
        text = strip_ansi(text)
    if err:
        with redirect_stdout(sys.stderr):
            return func(text)
    return func(text)

def prompt(text: str, default: t.Any | None=None, hide_input: bool=False, confirmation_prompt: bool | str=False, type: ParamType[t.Any] | t.Any | None=None, value_proc: t.Callable[[str], t.Any] | None=None, prompt_suffix: str=': ', show_default: bool | str=True, err: bool=False, show_choices: bool=True) -> t.Any:

    def prompt_func(text: str) -> str:
        f = hidden_prompt_func if hide_input else visible_prompt_func
        try:
            return _readline_prompt(f, text, err)
        except (KeyboardInterrupt, EOFError):
            if hide_input:
                echo(None, err=err)
            raise Abort() from None
    if value_proc is None:
        value_proc = convert_type(type, default)
    prompt = _build_prompt(text, prompt_suffix, show_default, default, show_choices, type)
    if confirmation_prompt:
        if confirmation_prompt is True:
            confirmation_prompt = _('Repeat for confirmation')
        confirmation_prompt = _build_prompt(confirmation_prompt, prompt_suffix)
    while True:
        while True:
            value = prompt_func(prompt)
            if value:
                break
            elif default is not None:
                value = default
                break
        try:
            result = value_proc(value)
        except UsageError as e:
            message = _mask_hidden_input(e.message, value) if hide_input else e.message
            echo(_('Error: {message}').format(message=message), err=err)
            continue
        if not confirmation_prompt:
            return result
        while True:
            value2 = prompt_func(confirmation_prompt)
            is_empty = not value and (not value2)
            if value2 or is_empty:
                break
        if value == value2:
            return result
        echo(_('Error: The two entered values do not match.'), err=err)

def confirm(text: str, default: bool | None=False, abort: bool=False, prompt_suffix: str=': ', show_default: bool=True, err: bool=False) -> bool:
    prompt = _build_prompt(text, prompt_suffix, show_default, 'y/n' if default is None else 'Y/n' if default else 'y/N')
    while True:
        try:
            value = _readline_prompt(visible_prompt_func, prompt, err).lower().strip()
        except (KeyboardInterrupt, EOFError):
            raise Abort() from None
        if value in ('y', 'yes'):
            rv = True
        elif value in ('n', 'no'):
            rv = False
        elif default is not None and value == '':
            rv = default
        else:
            echo(_('Error: invalid input'), err=err)
            continue
        break
    if abort and (not rv):
        raise Abort()
    return rv

