def _make_default_short_help(help: str, max_length: int=45) -> str:
    paragraph_end = help.find('\n\n')
    if paragraph_end != -1:
        help = help[:paragraph_end]
    words = help.split()
    if not words:
        return ''
    if words[0] == '\x08':
        words = words[1:]
    total_length = 0
    last_index = len(words) - 1
    for i, word in enumerate(words):
        total_length += len(word) + (i > 0)
        if total_length > max_length:
            break
        if word[-1] == '.':
            return ' '.join(words[:i + 1])
        if total_length == max_length and i != last_index:
            break
    else:
        return ' '.join(words)
    total_length += len('...')
    while i > 0:
        total_length -= len(words[i]) + (i > 0)
        if total_length <= max_length:
            break
        i -= 1
    return ' '.join(words[:i]) + '...'

def echo(message: object=None, file: t.IO[t.Any] | None=None, nl: bool=True, err: bool=False, color: bool | None=None) -> None:
    if file is None:
        if err:
            file = _default_text_stderr()
        else:
            file = _default_text_stdout()
        if file is None:
            return
    match message:
        case str() | bytes() | bytearray():
            out = message
        case None:
            out = ''
        case _:
            out = str(message)
    if nl:
        if isinstance(out, str):
            out += '\n'
        else:
            out += b'\n'
    if not out:
        file.flush()
        return
    if isinstance(out, (bytes, bytearray)):
        binary_file = _find_binary_writer(file)
        if binary_file is not None:
            file.flush()
            binary_file.write(out)
            binary_file.flush()
            return
    elif should_strip_ansi(file, resolve_color_default(color)):
        out = strip_ansi(out)
    file.write(out)
    file.flush()

def _get_binary_stream(name: t.Literal['stdin', 'stdout', 'stderr']) -> t.BinaryIO:
    opener = binary_streams.get(name)
    if opener is None:
        raise TypeError(_("Unknown standard stream '{name}'").format(name=name))
    return opener()

def _get_text_stream(name: t.Literal['stdin', 'stdout', 'stderr'], encoding: str | None=None, errors: str | None='strict') -> t.TextIO:
    opener = text_streams.get(name)
    if opener is None:
        raise TypeError(_("Unknown standard stream '{name}'").format(name=name))
    return opener(encoding, errors)

def open_file(filename: str | os.PathLike[str], mode: str='r', encoding: str | None=None, errors: str | None='strict', lazy: bool=False, atomic: bool=False) -> t.IO[t.Any]:
    if lazy:
        return t.cast('t.IO[t.Any]', _LazyFile(filename, mode, encoding, errors, atomic=atomic))
    f, should_close = open_stream(filename, mode, encoding, errors, atomic=atomic)
    if not should_close:
        f = t.cast('t.IO[t.Any]', _KeepOpenFile(f))
    return f

def format_filename(filename: str | bytes | os.PathLike[str] | os.PathLike[bytes], shorten: bool=False) -> str:
    if shorten:
        filename = os.path.basename(filename)
    else:
        filename = os.fspath(filename)
    if isinstance(filename, bytes):
        filename = filename.decode(sys.getfilesystemencoding(), 'replace')
    else:
        filename = filename.encode('utf-8', 'surrogateescape').decode('utf-8', 'replace')
    return filename

def get_app_dir(app_name: str, roaming: bool=True, force_posix: bool=False) -> str:
    if WIN:
        key = 'APPDATA' if roaming else 'LOCALAPPDATA'
        folder = os.environ.get(key)
        if folder is None:
            folder = os.path.expanduser('~')
        return os.path.join(folder, app_name)
    if force_posix:
        return os.path.join(os.path.expanduser(f'~/.{_posixify(app_name)}'))
    if sys.platform == 'darwin':
        return os.path.join(os.path.expanduser('~/Library/Application Support'), app_name)
    return os.path.join(os.environ.get('XDG_CONFIG_HOME', os.path.expanduser('~/.config')), _posixify(app_name))

def _detect_program_name(path: str | None=None, _main: ModuleType | None=None) -> str:
    if _main is None:
        _main = sys.modules['__main__']
    if not path:
        path = sys.argv[0]
    if getattr(_main, '__package__', None) in {None, ''} or (os.name == 'nt' and _main.__package__ == '' and (not os.path.exists(path)) and os.path.exists(f'{path}.exe')):
        return os.path.basename(path)
    py_module = t.cast(str, _main.__package__)
    name = os.path.splitext(os.path.basename(path))[0]
    if name != '__main__':
        py_module = f'{py_module}.{name}'
    return f"python -m {py_module.lstrip('.')}"

def _expand_args(args: cabc.Iterable[str], *, user: bool=True, env: bool=True, glob_recursive: bool=True) -> list[str]:
    from glob import glob
    out = []
    for arg in args:
        if user:
            arg = os.path.expanduser(arg)
        if env:
            arg = os.path.expandvars(arg)
        try:
            matches = glob(arg, recursive=glob_recursive)
        except re.error:
            matches = []
        if not matches:
            out.append(arg)
        else:
            out.extend(matches)
    return out

def open(self) -> t.IO[t.Any]:
    if self._f is not None:
        return self._f
    try:
        rv, self.should_close = open_stream(self.name, self.mode, self.encoding, self.errors, atomic=self.atomic)
    except OSError as e:
        from .exceptions import FileError
        raise FileError(self.name, hint=e.strerror) from e
    self._f = rv
    return rv

def close(self) -> None:
    if self._f is not None:
        self._f.close()

def close_intelligently(self) -> None:
    if self.should_close:
        self.close()

def is_ascii_encoding(encoding: str) -> bool:
    try:
        return codecs.lookup(encoding).name == 'ascii'
    except LookupError:
        return False

def get_best_encoding(stream: t.IO[t.Any]) -> str:
    rv = getattr(stream, 'encoding', None) or sys.getdefaultencoding()
    if is_ascii_encoding(rv):
        return 'utf-8'
    return rv

def _is_compat_stream_attr(stream: t.TextIO, attr: str, value: str | None) -> bool:
    stream_value = getattr(stream, attr, None)
    return stream_value == value or (value is None and stream_value is not None)

def _wrap_io_open(file: str | os.PathLike[str] | int, mode: str, encoding: str | None, errors: str | None) -> t.IO[t.Any]:
    if 'b' in mode:
        return open(file, mode)
    return open(file, mode, encoding=encoding, errors=errors)

def _pager_contextmanager(color: bool | None=None) -> t.ContextManager[tuple[t.BinaryIO | t.TextIO, str, bool]]:
    stdout = _default_text_stdout()
    if stdout is None:
        stdout = StringIO()
    if not isatty(sys.stdin) or not isatty(stdout):
        return _nullpager(stdout, color)
    pager_cmd_parts = shlex.split(os.environ.get('PAGER', ''))
    if pager_cmd_parts:
        if WIN:
            return _tempfilepager(pager_cmd_parts, color)
        return _pipepager(pager_cmd_parts, color)
    if os.environ.get('TERM') in ('dumb', 'emacs'):
        return _nullpager(stdout, color)
    if WIN or sys.platform.startswith('os2'):
        return _tempfilepager(['more'], color)
    return _pipepager(['less'], color)

@contextlib.contextmanager
def get_pager_file(color: bool | None=None) -> t.Generator[t.TextIO, None, None]:
    with _pager_contextmanager(color=color) as (stream, encoding, color):
        wrapper: MaybeStripAnsi | None = None
        if _has_binary_buffer(stream):
            wrapper = MaybeStripAnsi(stream.buffer, color=color, encoding=encoding)
            stream = wrapper
        try:
            yield t.cast(t.TextIO, stream)
        finally:
            try:
                stream.flush()
            finally:
                if wrapper is not None:
                    wrapper.detach()

@contextlib.contextmanager
def _pipepager(cmd_parts: list[str], color: bool | None=None) -> t.Iterator[tuple[t.BinaryIO | t.TextIO, str, bool]]:
    if not cmd_parts:
        stdout = _default_text_stdout() or StringIO()
        with _nullpager(stdout, color) as rv:
            yield rv
        return
    import shutil
    cmd = cmd_parts[0]
    cmd_params = cmd_parts[1:]
    cmd_filepath = shutil.which(cmd)
    if not cmd_filepath:
        stdout = _default_text_stdout() or StringIO()
        with _nullpager(stdout, color) as rv:
            yield rv
        return
    cmd_path = Path(cmd_filepath).absolute()
    cmd_name = cmd_path.name
    import subprocess
    env = dict(os.environ)
    if color is None and cmd_name == 'less':
        less_flags = f"{os.environ.get('LESS', '')}{' '.join(cmd_params)}"
        if not less_flags:
            env['LESS'] = '-R'
            color = True
        elif 'r' in less_flags or 'R' in less_flags:
            color = True
    if color is None:
        color = False
    c = subprocess.Popen([str(cmd_path)] + cmd_params, shell=False, stdin=subprocess.PIPE, env=env, errors='replace', text=True)
    stdin = t.cast(t.BinaryIO, c.stdin)
    encoding = get_best_encoding(stdin)
    try:
        yield (stdin, encoding, color)
    except BrokenPipeError:
        pass
    except Exception as e:
        c.terminate()
        raise e
    finally:
        try:
            stdin.close()
        except BrokenPipeError:
            pass
        while True:
            try:
                c.wait()
            except KeyboardInterrupt:
                pass
            else:
                break

@contextlib.contextmanager
def _nullpager(stream: t.TextIO, color: bool | None=None) -> t.Iterator[tuple[t.TextIO, str, bool]]:
    encoding = get_best_encoding(stream)
    if color is None:
        color = False
    yield (_KeepOpenFile(stream), encoding, color)

def update(self, n_steps: int, current_item: V | None=None) -> None:
    if current_item is not None:
        self.current_item = current_item
    self._completed_intervals += n_steps
    if self._completed_intervals >= self.update_min_steps:
        self.make_step(self._completed_intervals)
        self.render_progress()
        self._completed_intervals = 0

def generator(self) -> cabc.Iterator[V]:
    if not self.entered:
        raise RuntimeError('You need to use progress bars in a with block.')
    if not self._is_atty:
        yield from self.iter
    else:
        for rv in self.iter:
            self.current_item = rv
            if self._completed_intervals == 0:
                self.render_progress()
            yield rv
            self.update(1)
        self.finish()
        self.render_progress()

def edit_files(self, filenames: cabc.Iterable[str]) -> None:
    import shlex
    import subprocess
    editor = self.get_editor()
    environ: dict[str, str] | None = None
    if self.env:
        environ = os.environ.copy()
        environ.update(self.env)
    try:
        c = subprocess.Popen(args=shlex.split(editor) + list(filenames), env=environ)
        exit_code = c.wait()
        if exit_code != 0:
            raise ClickException(_('{editor}: Editing failed').format(editor=editor))
    except OSError as e:
        raise ClickException(_('{editor}: Editing failed: {e}').format(editor=editor, e=e)) from e

def _truncate_visible(text: str, n: int) -> str:
    if n <= 0:
        return ''
    visible = 0
    i = 0
    cut = 0
    end = len(text)
    while i < end:
        m = _ansi_re.match(text, i)
        if m is not None:
            i = m.end()
            continue
        visible += 1
        i += 1
        cut = i
        if visible >= n:
            break
    return text[:cut]

def _wrap_chunks(self, chunks: list[str]) -> list[str]:
    lines: list[str] = []
    if self.width <= 0:
        raise ValueError(f'invalid width {self.width!r} (must be > 0)')
    if self.max_lines is not None:
        if self.max_lines > 1:
            indent = self.subsequent_indent
        else:
            indent = self.initial_indent
        if term_len(indent) + term_len(self.placeholder.lstrip()) > self.width:
            raise ValueError('placeholder too large for max width')
    chunks.reverse()
    while chunks:
        cur_line: list[str] = []
        cur_len = 0
        if lines:
            indent = self.subsequent_indent
        else:
            indent = self.initial_indent
        width = self.width - term_len(indent)
        if self.drop_whitespace and chunks[-1].strip() == '' and lines:
            del chunks[-1]
        while chunks:
            n = term_len(chunks[-1])
            if cur_len + n <= width:
                cur_line.append(chunks.pop())
                cur_len += n
            else:
                break
        if chunks and term_len(chunks[-1]) > width:
            self._handle_long_word(chunks, cur_line, cur_len, width)
            cur_len = sum(map(term_len, cur_line))
        if self.drop_whitespace and cur_line and (cur_line[-1].strip() == ''):
            cur_len -= term_len(cur_line[-1])
            del cur_line[-1]
        if cur_line:
            if self.max_lines is None or len(lines) + 1 < self.max_lines or ((not chunks or (self.drop_whitespace and len(chunks) == 1 and (not chunks[0].strip()))) and cur_len <= width):
                lines.append(indent + ''.join(cur_line))
            else:
                while cur_line:
                    if cur_line[-1].strip() and cur_len + term_len(self.placeholder) <= width:
                        cur_line.append(self.placeholder)
                        lines.append(indent + ''.join(cur_line))
                        break
                    cur_len -= term_len(cur_line[-1])
                    del cur_line[-1]
                else:
                    if lines:
                        prev_line = lines[-1].rstrip()
                        if term_len(prev_line) + term_len(self.placeholder) <= self.width:
                            lines[-1] = prev_line + self.placeholder
                            break
                    lines.append(indent + self.placeholder.lstrip())
                break
    return lines

def render(request, template_name, context=None, content_type=None, status=None, using=None):
    content = loader.render_to_string(template_name, context, request, using=using)
    return HttpResponse(content, content_type, status)

def redirect(to, *args, permanent=False, preserve_request=False, max_length=MAX_URL_REDIRECT_LENGTH, **kwargs):
    redirect_class = HttpResponsePermanentRedirect if permanent else HttpResponseRedirect
    return redirect_class(resolve_url(to, *args, **kwargs), preserve_request=preserve_request, max_length=max_length)

def _get_queryset(klass):
    if hasattr(klass, '_default_manager'):
        return klass._default_manager.all()
    return klass

def get_object_or_404(klass, *args, **kwargs):
    queryset = _get_queryset(klass)
    if not hasattr(queryset, 'get'):
        klass__name = klass.__name__ if isinstance(klass, type) else klass.__class__.__name__
        raise ValueError("First argument to get_object_or_404() must be a Model, Manager, or QuerySet, not '%s'." % klass__name)
    try:
        return queryset.get(*args, **kwargs)
    except queryset.model.DoesNotExist:
        raise Http404(_('No %s matches the given query.') % queryset.model._meta.object_name)

async def aget_object_or_404(klass, *args, **kwargs):
    queryset = _get_queryset(klass)
    if not hasattr(queryset, 'aget'):
        klass__name = klass.__name__ if isinstance(klass, type) else klass.__class__.__name__
        raise ValueError(f"First argument to aget_object_or_404() must be a Model, Manager, or QuerySet, not '{klass__name}'.")
    try:
        return await queryset.aget(*args, **kwargs)
    except queryset.model.DoesNotExist:
        raise Http404(_('No %s matches the given query.') % queryset.model._meta.object_name)

def get_list_or_404(klass, *args, **kwargs):
    queryset = _get_queryset(klass)
    if not hasattr(queryset, 'filter'):
        klass__name = klass.__name__ if isinstance(klass, type) else klass.__class__.__name__
        raise ValueError("First argument to get_list_or_404() must be a Model, Manager, or QuerySet, not '%s'." % klass__name)
    obj_list = list(queryset.filter(*args, **kwargs))
    if not obj_list:
        raise Http404(_('No %s matches the given query.') % queryset.model._meta.object_name)
    return obj_list

def resolve_url(to, *args, **kwargs):
    if hasattr(to, 'get_absolute_url'):
        return to.get_absolute_url()
    if isinstance(to, Promise):
        to = str(to)
    if isinstance(to, str) and to.startswith(('./', '../')):
        return to
    try:
        return reverse(to, args=args, kwargs=kwargs)
    except NoReverseMatch:
        if callable(to):
            raise
        if '/' not in to and '.' not in to:
            raise
    return to

def _path_from_module(self, module):
    paths = list(getattr(module, '__path__', []))
    if len(paths) != 1:
        filename = getattr(module, '__file__', None)
        if filename is not None:
            paths = [os.path.dirname(filename)]
        else:
            paths = list(set(paths))
    if len(paths) > 1:
        raise ImproperlyConfigured("The app module %r has multiple filesystem locations (%r); you must configure this app with an AppConfig subclass with a 'path' class attribute." % (module, paths))
    elif not paths:
        raise ImproperlyConfigured("The app module %r has no filesystem location, you must configure this app with an AppConfig subclass with a 'path' class attribute." % module)
    return paths[0]

@classmethod
def create(cls, entry):
    app_config_class = None
    app_name = None
    app_module = None
    try:
        app_module = import_module(entry)
    except Exception:
        pass
    else:
        if module_has_submodule(app_module, APPS_MODULE_NAME):
            mod_path = '%s.%s' % (entry, APPS_MODULE_NAME)
            mod = import_module(mod_path)
            app_configs = [(name, candidate) for name, candidate in inspect.getmembers(mod, inspect.isclass) if issubclass(candidate, cls) and candidate is not cls and getattr(candidate, 'default', True)]
            if len(app_configs) == 1:
                app_config_class = app_configs[0][1]
            else:
                app_configs = [(name, candidate) for name, candidate in app_configs if getattr(candidate, 'default', False)]
                if len(app_configs) > 1:
                    candidates = [repr(name) for name, _ in app_configs]
                    raise RuntimeError('%r declares more than one default AppConfig: %s.' % (mod_path, ', '.join(candidates)))
                elif len(app_configs) == 1:
                    app_config_class = app_configs[0][1]
        if app_config_class is None:
            app_config_class = cls
            app_name = entry
    if app_config_class is None:
        try:
            app_config_class = import_string(entry)
        except Exception:
            pass
    if app_module is None and app_config_class is None:
        mod_path, _, cls_name = entry.rpartition('.')
        if mod_path and cls_name[0].isupper():
            mod = import_module(mod_path)
            candidates = [repr(name) for name, candidate in inspect.getmembers(mod, inspect.isclass) if issubclass(candidate, cls) and candidate is not cls]
            msg = "Module '%s' does not contain a '%s' class." % (mod_path, cls_name)
            if candidates:
                msg += ' Choices are: %s.' % ', '.join(candidates)
            raise ImportError(msg)
        else:
            import_module(entry)
    if not issubclass(app_config_class, AppConfig):
        raise ImproperlyConfigured("'%s' isn't a subclass of AppConfig." % entry)
    if app_name is None:
        try:
            app_name = app_config_class.name
        except AttributeError:
            raise ImproperlyConfigured("'%s' must supply a name attribute." % entry)
    try:
        app_module = import_module(app_name)
    except ImportError:
        raise ImproperlyConfigured("Cannot import '%s'. Check that '%s.%s.name' is correct." % (app_name, app_config_class.__module__, app_config_class.__qualname__))
    return app_config_class(app_name, app_module)

def get_model(self, model_name, require_ready=True):
    if require_ready:
        self.apps.check_models_ready()
    else:
        self.apps.check_apps_ready()
    try:
        return self.models[model_name.lower()]
    except KeyError:
        raise LookupError("App '%s' doesn't have a '%s' model." % (self.label, model_name))

def get_models(self, include_auto_created=False, include_swapped=False):
    self.apps.check_models_ready()
    for model in self.models.values():
        if model._meta.auto_created and (not include_auto_created):
            continue
        if model._meta.swapped and (not include_swapped):
            continue
        yield model

def populate(self, installed_apps=None):
    if self.ready:
        return
    with self._lock:
        if self.ready:
            return
        if self.loading:
            raise RuntimeError("populate() isn't reentrant")
        self.loading = True
        for entry in installed_apps:
            if isinstance(entry, AppConfig):
                app_config = entry
            else:
                app_config = AppConfig.create(entry)
            if app_config.label in self.app_configs:
                raise ImproperlyConfigured("Application labels aren't unique, duplicates: %s" % app_config.label)
            self.app_configs[app_config.label] = app_config
            app_config.apps = self
        counts = Counter((app_config.name for app_config in self.app_configs.values()))
        duplicates = [name for name, count in counts.most_common() if count > 1]
        if duplicates:
            raise ImproperlyConfigured("Application names aren't unique, duplicates: %s" % ', '.join(duplicates))
        self.apps_ready = True
        for app_config in self.app_configs.values():
            app_config.import_models()
        self.clear_cache()
        self.models_ready = True
        for app_config in self.get_app_configs():
            app_config.ready()
        self.ready = True
        self.ready_event.set()

def check_apps_ready(self):
    if not self.apps_ready:
        from django.conf import settings
        settings.INSTALLED_APPS
        raise AppRegistryNotReady("Apps aren't loaded yet.")

def check_models_ready(self):
    if not self.models_ready:
        raise AppRegistryNotReady("Models aren't loaded yet.")

def get_app_configs(self):
    self.check_apps_ready()
    return self.app_configs.values()

def get_app_config(self, app_label):
    self.check_apps_ready()
    try:
        return self.app_configs[app_label]
    except KeyError:
        message = "No installed app with label '%s'." % app_label
        for app_config in self.get_app_configs():
            if app_config.name == app_label:
                message += " Did you mean '%s'?" % app_config.label
                break
        raise LookupError(message)

@functools.cache
def get_models(self, include_auto_created=False, include_swapped=False):
    self.check_models_ready()
    result = []
    for app_config in self.app_configs.values():
        result.extend(app_config.get_models(include_auto_created, include_swapped))
    return result

def get_model(self, app_label, model_name=None, require_ready=True):
    if require_ready:
        self.check_models_ready()
    else:
        self.check_apps_ready()
    if model_name is None:
        app_label, model_name = app_label.split('.')
    app_config = self.get_app_config(app_label)
    if not require_ready and app_config.models is None:
        app_config.import_models()
    return app_config.get_model(model_name, require_ready=require_ready)

def is_installed(self, app_name):
    self.check_apps_ready()
    return any((ac.name == app_name for ac in self.app_configs.values()))

def get_containing_app_config(self, object_name):
    self.check_apps_ready()
    candidates = []
    for app_config in self.app_configs.values():
        if object_name.startswith(app_config.name):
            subpath = object_name.removeprefix(app_config.name)
            if subpath == '' or subpath[0] == '.':
                candidates.append(app_config)
    if candidates:
        return sorted(candidates, key=lambda ac: -len(ac.name))[0]

def get_registered_model(self, app_label, model_name):
    model = self.all_models[app_label].get(model_name.lower())
    if model is None:
        raise LookupError("Model '%s.%s' not registered." % (app_label, model_name))
    return model

@functools.cache
def get_swappable_settings_name(self, to_string):
    to_string = to_string.lower()
    for model in self.get_models(include_swapped=True):
        swapped = model._meta.swapped
        if swapped and swapped.lower() == to_string:
            return model._meta.swappable
        if model._meta.swappable and model._meta.label_lower == to_string:
            return model._meta.swappable
    return None

def set_available_apps(self, available):
    available = set(available)
    installed = {app_config.name for app_config in self.get_app_configs()}
    if not available.issubset(installed):
        raise ValueError("Available apps isn't a subset of installed apps, extra apps: %s" % ', '.join(available - installed))
    self.stored_app_configs.append(self.app_configs)
    self.app_configs = {label: app_config for label, app_config in self.app_configs.items() if app_config.name in available}
    self.clear_cache()

def unset_available_apps(self):
    self.app_configs = self.stored_app_configs.pop()
    self.clear_cache()

def set_installed_apps(self, installed):
    if not self.ready:
        raise AppRegistryNotReady("App registry isn't ready yet.")
    self.stored_app_configs.append(self.app_configs)
    self.app_configs = {}
    self.apps_ready = self.models_ready = self.loading = self.ready = False
    self.clear_cache()
    self.populate(installed)

def clear_cache(self):
    self.get_swappable_settings_name.cache_clear()
    self.get_models.cache_clear()
    if self.ready:
        for app_config in self.app_configs.values():
            for model in app_config.get_models(include_auto_created=True):
                model._meta._expire_cache()

def lazy_model_operation(self, function, *model_keys):
    if not model_keys:
        function()
    else:
        next_model, *more_models = model_keys

        def apply_next_model(model):
            next_function = partial(apply_next_model.func, model)
            self.lazy_model_operation(next_function, *more_models)
        apply_next_model.func = function
        try:
            model_class = self.get_registered_model(*next_model)
        except LookupError:
            self._pending_operations[next_model].append(apply_next_model)
        else:
            apply_next_model(model_class)

def do_pending_operations(self, model):
    key = (model._meta.app_label, model._meta.model_name)
    for function in self._pending_operations.pop(key, []):
        function(model)

def _setup(self, name=None):
    settings_module = os.environ.get(ENVIRONMENT_VARIABLE)
    if not settings_module:
        desc = 'setting %s' % name if name else 'settings'
        raise ImproperlyConfigured('Requested %s, but settings are not configured. You must either define the environment variable %s or call settings.configure() before accessing settings.' % (desc, ENVIRONMENT_VARIABLE))
    self._wrapped = Settings(settings_module)

def __getattr__(self, name):
    if (_wrapped := self._wrapped) is empty:
        self._setup(name)
        _wrapped = self._wrapped
    val = getattr(_wrapped, name)
    if name in DEPRECATED_EMAIL_SETTINGS:
        if hasattr(_wrapped, 'MAILERS'):
            raise AttributeError(f'The {name} setting is not available when MAILERS is defined.')
        _show_settings_deprecation_warning(EMAIL_SETTING_DEPRECATED_MSG.format(name=name), RemovedInDjango70Warning)
    if name in {'MEDIA_URL', 'STATIC_URL'} and val is not None:
        val = self._add_script_prefix(val)
    elif name == 'SECRET_KEY' and (not val):
        raise ImproperlyConfigured('The SECRET_KEY setting must not be empty.')
    self.__dict__[name] = val
    return val

def __setattr__(self, name, value):
    if name == '_wrapped':
        self.__dict__.clear()
    else:
        self.__dict__.pop(name, None)
    if name == 'SIGNED_COOKIE_LEGACY_SALT_FALLBACK':
        _show_settings_deprecation_warning(SIGNED_COOKIE_LEGACY_SALT_DEPRECATED_MSG, RemovedInDjango70Warning)
    if name == 'USE_BLANK_CHOICE_DASH':
        _show_settings_deprecation_warning(USE_BLANK_CHOICE_DASH_DEPRECATED_MSG, RemovedInDjango70Warning)
    if name == 'MAILERS':
        for setting in DEPRECATED_EMAIL_SETTINGS:
            self.__dict__.pop(setting, None)
    if name in DEPRECATED_EMAIL_SETTINGS:
        _show_settings_deprecation_warning(EMAIL_SETTING_DEPRECATED_MSG.format(name=name), RemovedInDjango70Warning)
    super().__setattr__(name, value)

def __delattr__(self, name):
    super().__delattr__(name)
    self.__dict__.pop(name, None)

def configure(self, default_settings=global_settings, **options):
    if self._wrapped is not empty:
        raise RuntimeError('Settings already configured.')
    _check_email_settings_conflicts(options.keys())
    holder = UserSettingsHolder(default_settings)
    for name, value in options.items():
        if not name.isupper():
            raise TypeError('Setting %r must be uppercase.' % name)
        setattr(holder, name, value)
    self._wrapped = holder

@staticmethod
def _add_script_prefix(value):
    if value.startswith(('http://', 'https://', '/')):
        return value
    from django.urls import get_script_prefix
    return '%s%s' % (get_script_prefix(), value)

@property
def configured(self):
    return self._wrapped is not empty

def __init__(self, default_settings):
    self.__dict__['_deleted'] = set()
    self.default_settings = default_settings

def i18n_patterns(*urls, prefix_default_language=True):
    if not settings.USE_I18N:
        return list(urls)
    return [URLResolver(LocalePrefixPattern(prefix_default_language=prefix_default_language), list(urls))]

@functools.cache
def is_language_prefix_patterns_used(urlconf):
    for url_pattern in get_resolver(urlconf).url_patterns:
        if isinstance(url_pattern.pattern, LocalePrefixPattern):
            return (True, url_pattern.pattern.prefix_default_language)
    return (False, False)

def static(prefix, view=serve, **kwargs):
    if not prefix:
        raise ImproperlyConfigured('Empty static prefix not permitted')
    elif not settings.DEBUG or urlsplit(prefix).netloc:
        return []
    return [re_path('^%s(?P<path>.*)$' % re.escape(prefix.lstrip('/')), view, kwargs=kwargs)]

@action(permissions=['delete'], description=gettext_lazy('Delete selected %(verbose_name_plural)s'))
def delete_selected(modeladmin, request, queryset):
    opts = modeladmin.model._meta
    app_label = opts.app_label
    deletable_objects, model_count, perms_needed, protected = modeladmin.get_deleted_objects(queryset, request)
    if request.POST.get('post') and (not protected):
        if perms_needed:
            raise PermissionDenied
        n = len(queryset)
        if n:
            modeladmin.log_deletions(request, queryset)
            modeladmin.delete_queryset(request, queryset)
            modeladmin.message_user(request, _('Successfully deleted %(count)d %(items)s.') % {'count': n, 'items': model_ngettext(modeladmin.opts, n)}, messages.SUCCESS)
        return None
    objects_name = model_ngettext(queryset)
    if perms_needed or protected:
        title = _('Cannot delete %(name)s') % {'name': objects_name}
    else:
        title = _('Delete multiple objects')
    context = {**modeladmin.admin_site.each_context(request), 'title': title, 'subtitle': None, 'objects_name': str(objects_name), 'deletable_objects': [deletable_objects], 'delete_confirmation_max_display': modeladmin.delete_confirmation_max_display, 'model_count': dict(model_count).items(), 'queryset': queryset, 'perms_lacking': perms_needed, 'protected': protected, 'opts': opts, 'action_checkbox_name': helpers.ACTION_CHECKBOX_NAME, 'media': modeladmin.media}
    request.current_app = modeladmin.admin_site.name
    return TemplateResponse(request, modeladmin.delete_selected_confirmation_template or ['admin/%s/%s/delete_selected_confirmation.html' % (app_label, opts.model_name), 'admin/%s/delete_selected_confirmation.html' % app_label, 'admin/delete_selected_confirmation.html'], context)

def _issubclass(cls, classinfo):
    try:
        return issubclass(cls, classinfo)
    except TypeError:
        return False

def _contains_subclass(class_path, candidate_paths):
    cls = import_string(class_path)
    for path in candidate_paths:
        try:
            candidate_cls = import_string(path)
        except ImportError:
            continue
        if _issubclass(candidate_cls, cls):
            return True
    return False

def check_dependencies(**kwargs):
    from django.contrib.admin.sites import all_sites
    if not apps.is_installed('django.contrib.admin'):
        return []
    errors = []
    app_dependencies = (('django.contrib.contenttypes', 401), ('django.contrib.auth', 405), ('django.contrib.messages', 406))
    for app_name, error_code in app_dependencies:
        if not apps.is_installed(app_name):
            errors.append(checks.Error("'%s' must be in INSTALLED_APPS in order to use the admin application." % app_name, id='admin.E%d' % error_code))
    for engine in engines.all():
        if isinstance(engine, DjangoTemplates):
            django_templates_instance = engine.engine
            break
    else:
        django_templates_instance = None
    if not django_templates_instance:
        errors.append(checks.Error("A 'django.template.backends.django.DjangoTemplates' instance must be configured in TEMPLATES in order to use the admin application.", id='admin.E403'))
    else:
        if 'django.contrib.auth.context_processors.auth' not in django_templates_instance.context_processors and _contains_subclass('django.contrib.auth.backends.ModelBackend', settings.AUTHENTICATION_BACKENDS):
            errors.append(checks.Error("'django.contrib.auth.context_processors.auth' must be enabled in DjangoTemplates (TEMPLATES) if using the default auth backend in order to use the admin application.", id='admin.E402'))
