            warn_about_implementation('Returning True from ModelAdmin.get_list_select_related() is deprecated. Return False or a list or tuple of fields to fetch instead.', RemovedInDjango70Warning, self.get_list_select_related)
    return ChangeList(request, self.model, list_display, list_display_links, self.get_list_filter(request), self.date_hierarchy, self.get_search_fields(request), list_select_related, self.list_per_page, self.list_max_show_all, self.list_editable, self, sortable_by, self.search_help_text)

def get_object(self, request, object_id, from_field=None):
