def _get_base_actions(self, action_location=ActionLocation.CHANGE_LIST):
    actions = []
    base_actions = (self.get_action(action, action_location) for action in self.actions or [])
    base_actions = [action for action in base_actions if action]
    base_action_names = {action.name for action in base_actions}
    for name, func in self.admin_site.actions:
        if name in base_action_names:
            continue
        locations = getattr(func, 'locations', [ActionLocation.CHANGE_LIST])
        if action_location not in locations:
            continue
        description = self._get_action_description(func, name)
        action = Action(func=func, name=name, description=description, plural_description=getattr(func, 'plural_description', description), locations=locations)
        actions.append(action)
    actions.extend(base_actions)
    return actions

def _filter_actions_by_permissions(self, request, actions):
    filtered_actions = []
    for action in actions:
        callable = action.func
        if not hasattr(callable, 'allowed_permissions'):
            filtered_actions.append(action)
            continue
        permission_checks = (getattr(self, 'has_%s_permission' % permission) for permission in callable.allowed_permissions)
        if any((has_permission(request) for has_permission in permission_checks)):
            filtered_actions.append(action)
    return filtered_actions

def get_actions(self, request, action_location=ActionLocation.CHANGE_LIST):
    if self.actions is None or IS_POPUP_VAR in request.GET:
        return {}
    base_actions = self._get_base_actions(action_location=action_location)
    actions = self._filter_actions_by_permissions(request, base_actions)
    return {action.name: action for action in actions}

def get_action_choices(self, request, default_choices=None, action_location=ActionLocation.CHANGE_LIST):
    if default_choices is None:
        default_choices = [('', get_blank_choice_label())]
    choices = [*default_choices]
    actions = self._get_actions_with_action_location(request, action_location=action_location)
    for action in actions.values():
        if isinstance(action, tuple):
            choice = (action[1], action[2] % model_format_dict(self.opts))
        else:
            choice = (action.name, self._get_choice_description(action, action_location))
        choices.append(choice)
    return choices

def get_action(self, action, action_location=ActionLocation.CHANGE_LIST):
    if callable(action):
        func = action
        action = action.__name__
    elif hasattr(self.__class__, action):
        func = getattr(self.__class__, action)
    else:
        try:
            func = self.admin_site.get_action(action)
        except KeyError:
            return None
    locations = getattr(func, 'locations', [ActionLocation.CHANGE_LIST])
    if action_location not in locations:
        return None
    description = self._get_action_description(func, action)
    return Action(func=func, name=action, description=description, plural_description=getattr(func, 'plural_description', description), locations=locations)

def get_list_display_links(self, request, list_display):
    if self.list_display_links or self.list_display_links is None or (not list_display):
        return self.list_display_links
    else:
        return list(list_display)[:1]

def get_search_results(self, request, queryset, search_term):

    def construct_search(field_name):
        """
            Return a tuple of (lookup, field_to_validate).

            field_to_validate is set for non-text exact lookups so that
            invalid search terms can be skipped (preserving index usage).
            """
        if field_name.startswith('^'):
            return ('%s__istartswith' % field_name.removeprefix('^'), None)
        elif field_name.startswith('='):
            return ('%s__iexact' % field_name.removeprefix('='), None)
        elif field_name.startswith('@'):
            return ('%s__search' % field_name.removeprefix('@'), None)
        opts = queryset.model._meta
        lookup_fields = field_name.split(LOOKUP_SEP)
        prev_field = None
        for path_part in lookup_fields:
            if path_part == 'pk':
                path_part = opts.pk.name
            try:
                field = opts.get_field(path_part)
            except FieldDoesNotExist:
                if prev_field and prev_field.get_lookup(path_part):
                    if path_part == 'exact' and (not isinstance(prev_field, (models.CharField, models.TextField))):
                        return (field_name, prev_field)
                    return (field_name, None)
            else:
                prev_field = field
                if hasattr(field, 'path_infos'):
                    opts = field.path_infos[-1].to_opts
        return ('%s__icontains' % field_name, None)
    may_have_duplicates = False
    search_fields = self.get_search_fields(request)
    if search_fields and search_term:
        orm_lookups = []
        for field in search_fields:
            orm_lookups.append(construct_search(str(field)))
        term_queries = []
        for bit in smart_split(search_term):
            if bit.startswith(('"', "'")) and bit[0] == bit[-1]:
                bit = unescape_string_literal(bit)
            bit_lookups = []
            for orm_lookup, validate_field in orm_lookups:
                if validate_field is not None:
                    formfield = validate_field.formfield()
                    try:
                        if formfield is not None:
                            value = formfield.to_python(bit)
                        else:
                            value = validate_field.to_python(bit)
                    except ValidationError:
                        continue
                else:
                    value = bit
                bit_lookups.append((orm_lookup, value))
            if bit_lookups:
                or_queries = models.Q.create(bit_lookups, connector=models.Q.OR)
                term_queries.append(or_queries)
            else:
                term_queries.append(models.Q(pk__in=[]))
        if term_queries:
            queryset = queryset.filter(models.Q.create(term_queries))
        may_have_duplicates |= any((lookup_spawns_duplicates(self.opts, search_spec) for search_spec, _ in orm_lookups))
    return (queryset, may_have_duplicates)

def get_preserved_filters(self, request):
    match = request.resolver_match
    if self.preserve_filters and match:
        current_url = '%s:%s' % (match.app_name, match.url_name)
        changelist_url = 'admin:%s_%s_changelist' % (self.opts.app_label, self.opts.model_name)
        if current_url == changelist_url:
            preserved_filters = request.GET.urlencode()
        else:
            preserved_filters = request.GET.get('_changelist_filters')
        if preserved_filters:
            return urlencode({'_changelist_filters': preserved_filters})
    return ''

def message_user(self, request, message, level=messages.INFO, extra_tags='', fail_silently=False):
    if not isinstance(level, int):
        try:
            level = getattr(messages.constants, level.upper())
        except AttributeError:
            levels = messages.constants.DEFAULT_TAGS.values()
            levels_repr = ', '.join(('`%s`' % level for level in levels))
            raise ValueError('Bad message level string: `%s`. Possible values are: %s' % (level, levels_repr))
    messages.add_message(request, level, message, extra_tags=extra_tags, fail_silently=fail_silently)

def save_related(self, request, form, formsets, change):
    form.save_m2m()
    for formset in formsets:
        self.save_formset(request, form, formset, change=change)

def response_add(self, request, obj, post_url_continue=None):
    opts = obj._meta
    preserved_filters = self.get_preserved_filters(request)
    preserved_qsl = self._get_preserved_qsl(request, preserved_filters)
    obj_url = reverse('admin:%s_%s_change' % (opts.app_label, opts.model_name), args=(quote(obj.pk),), current_app=self.admin_site.name)
    obj_display = display_for_value(str(obj), EMPTY_VALUE_STRING)
    if self.has_change_permission(request, obj):
        obj_repr = format_html('<a href="{}">{}</a>', urlquote(obj_url), obj_display)
    else:
        obj_repr = obj_display
    msg_dict = {'name': opts.verbose_name, 'obj': obj_repr}
    if IS_POPUP_VAR in request.POST:
        to_field = request.POST.get(TO_FIELD_VAR)
        if to_field:
            attr = str(to_field)
        else:
            attr = obj._meta.pk.attname
        value = obj.serializable_value(attr)
        popup_response = {'value': str(value), 'obj': str(obj)}
        source_model_name = request.POST.get(SOURCE_MODEL_VAR)
        source_admin = None
        if source_model_name:
            app_label, model_name = source_model_name.split('.', 1)
            try:
                source_model = apps.get_model(app_label, model_name)
            except LookupError:
                msg = _('The app "%s" could not be found.') % source_model_name
                self.message_user(request, msg, messages.ERROR)
            else:
                source_admin = self.admin_site._registry.get(source_model)
        if source_admin:
            form = source_admin.get_form(request)()
            if self.opts.verbose_name_plural in form.fields:
                field = form.fields[self.opts.verbose_name_plural]
                for option_value, option_label in field.choices:
                    if isinstance(option_label, (list, tuple)):
                        optgroup_label = option_value
                        for choice_value, choice_display in option_label:
                            if choice_display == str(obj):
                                popup_response['optgroup'] = str(optgroup_label)
                                break
        popup_response_data = json.dumps(popup_response)
        return TemplateResponse(request, self.popup_response_template or ['admin/%s/%s/popup_response.html' % (opts.app_label, opts.model_name), 'admin/%s/popup_response.html' % opts.app_label, 'admin/popup_response.html'], {'popup_response_data': popup_response_data})
    elif '_continue' in request.POST or ('_saveasnew' in request.POST and self.save_as_continue and self.has_change_permission(request, obj)):
        msg = _('The {name} “{obj}” was added successfully.')
        if self.has_change_permission(request, obj):
            msg += ' ' + _('You may edit it again below.')
        self.message_user(request, format_html(msg, **msg_dict), messages.SUCCESS)
        if post_url_continue is None:
            post_url_continue = obj_url
        post_url_continue = add_preserved_filters({'preserved_filters': preserved_filters, 'preserved_qsl': preserved_qsl, 'opts': opts}, post_url_continue)
        return HttpResponseRedirect(post_url_continue)
    elif '_addanother' in request.POST:
        msg = format_html(_('The {name} “{obj}” was added successfully. You may add another {name} below.'), **msg_dict)
        self.message_user(request, msg, messages.SUCCESS)
        redirect_url = request.path
        redirect_url = add_preserved_filters({'preserved_filters': preserved_filters, 'preserved_qsl': preserved_qsl, 'opts': opts}, redirect_url)
        return HttpResponseRedirect(redirect_url)
    else:
        msg = format_html(_('The {name} “{obj}” was added successfully.'), **msg_dict)
        self.message_user(request, msg, messages.SUCCESS)
        return self.response_post_save_add(request, obj)

def response_change(self, request, obj):
    if IS_POPUP_VAR in request.POST:
        opts = obj._meta
        to_field = request.POST.get(TO_FIELD_VAR)
        attr = str(to_field) if to_field else opts.pk.attname
        value = request.resolver_match.kwargs['object_id']
        new_value = obj.serializable_value(attr)
        popup_response_data = json.dumps({'action': 'change', 'value': str(value), 'obj': str(obj), 'new_value': str(new_value)})
        return TemplateResponse(request, self.popup_response_template or ['admin/%s/%s/popup_response.html' % (opts.app_label, opts.model_name), 'admin/%s/popup_response.html' % opts.app_label, 'admin/popup_response.html'], {'popup_response_data': popup_response_data})
    opts = self.opts
