def response_action(self, request, queryset, action_location=ActionLocation.CHANGE_LIST):
    try:
        action_index = int(request.POST.get('index', 0))
    except ValueError:
        action_index = 0
    data = request.POST.copy()
    data.pop(helpers.ACTION_CHECKBOX_NAME, None)
    data.pop('index', None)
    try:
        data.update({'action': data.getlist('action')[action_index]})
    except IndexError:
        pass
    prefix = action_location.value if action_location != ActionLocation.CHANGE_LIST else ''
    action_form = self.action_form(data, auto_id=None, prefix=prefix)
    action_form.fields['action'].choices = self._get_action_choices_with_action_location(request, action_location=action_location)
    if action_form.is_valid():
        action = action_form.cleaned_data['action']
        select_across = action_form.cleaned_data['select_across']
        if action_location == ActionLocation.CHANGE_FORM:
            select_across = False
        actions = self._get_actions_with_action_location(request, action_location=action_location)
        if isinstance(actions[action], tuple):
            func = actions[action][0]
        else:
            func = actions[action].func
        selected = request.POST.getlist(helpers.ACTION_CHECKBOX_NAME)
        if not selected and (not select_across):
            msg = _('Items must be selected in order to perform actions on them. No items have been changed.')
            self.message_user(request, msg, messages.WARNING)
            return None
        if not select_across:
            queryset = queryset.filter(pk__in=selected)
        response = func(self, request, queryset)
        if isinstance(response, HttpResponseBase):
            return response
        else:
            return HttpResponseRedirect(request.get_full_path())
    else:
        msg = _('No action selected.')
        self.message_user(request, msg, messages.WARNING)
        return None

