def _create_formsets(self, request, obj, change):
    formsets = []
    inline_instances = []
    prefixes = {}
    get_formsets_args = [request]
    if change:
        get_formsets_args.append(obj)
    for FormSet, inline in self.get_formsets_with_inlines(*get_formsets_args):
        prefix = FormSet.get_default_prefix()
        prefixes[prefix] = prefixes.get(prefix, 0) + 1
        if prefixes[prefix] != 1 or not prefix:
            prefix = '%s-%s' % (prefix, prefixes[prefix])
        formset_params = self.get_formset_kwargs(request, obj, inline, prefix)
        formset = FormSet(**formset_params)

        def user_deleted_form(request, obj, formset, index, inline):
            """Return whether or not the user deleted the form."""
            return inline.has_delete_permission(request, obj) and '{}-{}-DELETE'.format(formset.prefix, index) in request.POST
        if not inline.has_change_permission(request, obj if change else None):
            for index, form in enumerate(formset.initial_forms):
                if user_deleted_form(request, obj, formset, index, inline):
                    continue
                form._errors = {}
                form.cleaned_data = form.initial
        formsets.append(formset)
        inline_instances.append(inline)
    return (formsets, inline_instances)

def get_formset(self, request, obj=None, **kwargs):
    if 'fields' in kwargs:
        fields = kwargs.pop('fields')
    else:
        fields = flatten_fieldsets(self.get_fieldsets(request, obj))
    excluded = self.get_exclude(request, obj)
    exclude = [] if excluded is None else list(excluded)
    exclude.extend(self.get_readonly_fields(request, obj))
    if excluded is None and hasattr(self.form, '_meta') and self.form._meta.exclude:
        exclude.extend(self.form._meta.exclude)
    exclude = exclude or None
    can_delete = self.can_delete and self.has_delete_permission(request, obj)
    defaults = {'form': self.form, 'formset': self.formset, 'fk_name': self.fk_name, 'fields': fields, 'exclude': exclude, 'formfield_callback': partial(self.formfield_for_dbfield, request=request), 'extra': self.get_extra(request, obj, **kwargs), 'min_num': self.get_min_num(request, obj, **kwargs), 'max_num': self.get_max_num(request, obj, **kwargs), 'can_delete': can_delete, **kwargs}
    base_model_form = defaults['form']
    can_change = self.has_change_permission(request, obj) if request else True
    can_add = self.has_add_permission(request, obj) if request else True
    delete_confirmation_max_display = self.delete_confirmation_max_display if self.delete_confirmation_max_display else sys.maxsize

    class DeleteProtectedModelForm(base_model_form):

        def hand_clean_DELETE(self):
            """
                We don't validate the 'DELETE' field itself because on
                templates it's not rendered using the field information, but
                just using a generic "deletion_field" of the InlineModelAdmin.
                """
            if self.cleaned_data.get(DELETION_FIELD_NAME, False):
                using = router.db_for_write(self._meta.model)
                collector = NestedObjects(using=using)
                if self.instance._state.adding:
                    return
                collector.collect([self.instance])
                if collector.protected:
                    objs = []
                    protected = itertools.islice(collector.protected, delete_confirmation_max_display)
                    for p in protected:
                        objs.append(_('%(class_name)s %(instance)s') % {'class_name': p._meta.verbose_name, 'instance': p})
                    params = {'class_name': self._meta.model._meta.verbose_name, 'instance': self.instance}
                    remaining_object_count = len(collector.protected) - delete_confirmation_max_display
                    if remaining_object_count > 0:
                        related = _(', ').join((str(i) for i in objs)) + _(', ') + ngettext('…and %(count)d more object.', '…and %(count)d more objects.', remaining_object_count) % {'count': remaining_object_count}
                    else:
                        related = get_text_list(objs, _('and'))
                    params['related_objects'] = related
                    msg = _('Deleting %(class_name)s %(instance)s would require deleting the following protected related objects: %(related_objects)s')
                    raise ValidationError(msg, code='deleting_protected', params=params)

        def is_valid(self):
            result = super().is_valid()
            self.hand_clean_DELETE()
            return result

        def has_changed(self):
            if not can_change and (not self.instance._state.adding):
                return False
            if not can_add and self.instance._state.adding:
                return False
            return super().has_changed()
    defaults['form'] = DeleteProtectedModelForm
    if defaults['fields'] is None and (not modelform_defines_fields(defaults['form'])):
        defaults['fields'] = forms.ALL_FIELDS
    return inlineformset_factory(self.parent_model, self.model, **defaults)

def _has_any_perms_for_target_model(self, request, perms):
    opts = self.opts
    for field in opts.fields:
        if field.remote_field and field.remote_field.model != self.parent_model:
            opts = field.remote_field.model._meta
            break
    return any((request.user.has_perm('%s.%s' % (opts.app_label, get_permission_codename(perm, opts))) for perm in perms))

def construct_search(field_name):
    if field_name.startswith('^'):
        return ('%s__istartswith' % field_name.removeprefix('^'), None)
    elif field_name.startswith('='):
        return ('%s__iexact' % field_name.removeprefix('='), None)
    elif field_name.startswith('@'):
        return ('%s__search' % field_name.removeprefix('@'), None)
    opts = queryset.model._meta
    lookup_fields = field_name.split(LOOKUP_SEP)
    prev_field = None
    for path_part in lookup_fields:
        if path_part == 'pk':
            path_part = opts.pk.name
        try:
            field = opts.get_field(path_part)
        except FieldDoesNotExist:
            if prev_field and prev_field.get_lookup(path_part):
                if path_part == 'exact' and (not isinstance(prev_field, (models.CharField, models.TextField))):
                    return (field_name, prev_field)
                return (field_name, None)
        else:
            prev_field = field
            if hasattr(field, 'path_infos'):
                opts = field.path_infos[-1].to_opts
    return ('%s__icontains' % field_name, None)

