@method_decorator(never_cache)
@login_not_required
def login(self, request, extra_context=None):
    from django.contrib.admin.forms import AdminAuthenticationForm
    from django.contrib.auth.views import LoginView
    redirect_url = LoginView().get_redirect_url(request) or reverse('admin:index', current_app=self.name)
    if request.method == 'GET' and self.has_permission(request):
        return HttpResponseRedirect(redirect_url)
    context = {**self.each_context(request), 'title': _('Log in'), 'subtitle': None, 'app_path': request.get_full_path(), 'username': request.user.get_username(), REDIRECT_FIELD_NAME: redirect_url}
    context.update(extra_context or {})
    defaults = {'extra_context': context, 'authentication_form': self.login_form or AdminAuthenticationForm, 'template_name': self.login_template or 'admin/login.html'}
    request.current_app = self.name
    return LoginView.as_view(**defaults)(request)

def _build_app_dict(self, request, label=None):
    app_dict = {}
    if label:
        models = {m: m_a for m, m_a in self._registry.items() if m._meta.app_label == label}
    else:
        models = self._registry
    for model, model_admin in models.items():
        app_label = model._meta.app_label
        has_module_perms = model_admin.has_module_permission(request)
        if not has_module_perms:
            continue
        perms = model_admin.get_model_perms(request)
        if True not in perms.values():
            continue
        info = (app_label, model._meta.model_name)
        model_dict = {'model': model, 'name': capfirst(model._meta.verbose_name_plural), 'object_name': model._meta.object_name, 'perms': perms, 'admin_url': None, 'add_url': None}
        if perms.get('change') or perms.get('view'):
            model_dict['view_only'] = not perms.get('change')
            try:
                model_dict['admin_url'] = reverse('admin:%s_%s_changelist' % info, current_app=self.name)
            except NoReverseMatch:
                pass
        if perms.get('add'):
            try:
                model_dict['add_url'] = reverse('admin:%s_%s_add' % info, current_app=self.name)
            except NoReverseMatch:
                pass
        if app_label in app_dict:
            app_dict[app_label]['models'].append(model_dict)
        else:
            app_dict[app_label] = {'name': apps.get_app_config(app_label).verbose_name, 'app_label': app_label, 'app_url': reverse('admin:app_list', kwargs={'app_label': app_label}, current_app=self.name), 'has_module_perms': has_module_perms, 'models': [model_dict]}
    return app_dict

def get_app_list(self, request, app_label=None):
    app_dict = self._build_app_dict(request, app_label)
    app_list = sorted(app_dict.values(), key=lambda x: x['name'].lower())
    for app in app_list:
        app['models'].sort(key=lambda x: x['name'])
    return app_list

def index(self, request, extra_context=None):
    app_list = self.get_app_list(request)
    context = {**self.each_context(request), 'title': self.index_title, 'subtitle': None, 'app_list': app_list, **(extra_context or {})}
    request.current_app = self.name
    return TemplateResponse(request, self.index_template or 'admin/index.html', context)

def wait_until(self, callback, timeout=10):
    from selenium.webdriver.support.wait import WebDriverWait
    WebDriverWait(self.selenium, timeout).until(callback)

@contextmanager
def wait_page_loaded(self, timeout=10):
    from selenium.common.exceptions import WebDriverException
    from selenium.webdriver.common.by import By
    from selenium.webdriver.support import expected_conditions as ec
    old_page = self.selenium.find_element(By.TAG_NAME, 'html')
    yield
    try:
        self.wait_until(ec.staleness_of(old_page), timeout=timeout)
    except WebDriverException:
        pass
    self.wait_page_ready(timeout=timeout)

def is_disabled(self, selector):
    from selenium.webdriver.common.by import By
    return self.selenium.find_element(By.CSS_SELECTOR, selector).get_attribute('disabled') == 'true'

def lookup_spawns_duplicates(opts, lookup_path):
    lookup_fields = lookup_path.split(LOOKUP_SEP)
    for field_name in lookup_fields:
        if field_name == 'pk':
            field_name = opts.pk.name
        try:
            field = opts.get_field(field_name)
        except FieldDoesNotExist:
            continue
        else:
            if hasattr(field, 'path_infos'):
                path_info = field.path_infos
                opts = path_info[-1].to_opts
                if any((path.m2m for path in path_info)):
                    return True
    return False

def prepare_lookup_value(key, value, separator=','):
    if isinstance(value, list):
        return [prepare_lookup_value(key, v, separator=separator) for v in value]
    if key.endswith('__in'):
        value = value.split(separator)
    elif key.endswith('__isnull'):
        value = value.lower() not in ('', 'false', '0')
    return value

def flatten(fields):
    flat = []
    for field in fields:
        if isinstance(field, (list, tuple)):
            flat.extend(field)
        else:
            flat.append(field)
    return flat

def flatten_fieldsets(fieldsets):
    field_names = []
    for name, opts in fieldsets:
        field_names.extend(flatten(opts['fields']))
    return field_names

def get_deleted_objects(objs, request, admin_site):
    from django.contrib.admin.options import EMPTY_VALUE_STRING
    try:
        obj = objs[0]
    except IndexError:
        return ([], {}, set(), [])
    else:
        using = router.db_for_write(obj._meta.model)
    collector = NestedObjects(using=using, origin=objs)
    collector.collect(objs)
    perms_needed = set()

    def format_callback(obj):
        model = obj.__class__
        opts = obj._meta
        no_edit_link = '%s: %s' % (capfirst(opts.verbose_name), obj)
        if admin_site.is_registered(model):
            if not admin_site.get_model_admin(model).has_delete_permission(request, obj):
                perms_needed.add(opts.verbose_name)
            try:
                admin_url = reverse('%s:%s_%s_change' % (admin_site.name, opts.app_label, opts.model_name), None, (quote(obj.pk),))
            except NoReverseMatch:
                return no_edit_link
            obj_display = display_for_value(str(obj), EMPTY_VALUE_STRING)
            return format_html('{}: <a href="{}">{}</a>', capfirst(opts.verbose_name), admin_url, obj_display)
        else:
            return no_edit_link
    to_delete = collector.nested(format_callback)
    protected = [format_callback(obj) for obj in collector.protected]
    model_count = {model._meta.verbose_name_plural: len(objs) for model, objs in collector.model_objs.items()}
    return (to_delete, model_count, perms_needed, protected)

def model_format_dict(obj):
    if isinstance(obj, (models.Model, models.base.ModelBase)):
        opts = obj._meta
    elif isinstance(obj, models.query.QuerySet):
        opts = obj.model._meta
    else:
        opts = obj
    return {'verbose_name': opts.verbose_name, 'verbose_name_plural': opts.verbose_name_plural}

def model_ngettext(obj, n=None):
    if isinstance(obj, models.query.QuerySet):
        if n is None:
            n = obj.count()
        obj = obj.model
    d = model_format_dict(obj)
    singular, plural = (d['verbose_name'], d['verbose_name_plural'])
    return ngettext(singular, plural, n or 0)

def _get_non_gfk_field(opts, name):
    field = opts.get_field(name)
    if field.is_relation and (field.many_to_one and (not field.related_model) or field.one_to_many):
        raise FieldDoesNotExist()
    if field.is_relation and (not field.many_to_many) and hasattr(field, 'attname') and (field.attname == name):
        raise FieldIsAForeignKeyColumnName()
    return field

def label_for_field(name, model, model_admin=None, return_attr=False, form=None):
    attr = None
    try:
        field = _get_non_gfk_field(model._meta, name)
        try:
            label = field.verbose_name
        except AttributeError:
            label = field.related_model._meta.verbose_name
    except FieldDoesNotExist:
        if name == '__str__':
            label = str(model._meta.verbose_name)
            attr = str
        else:
            if callable(name):
                attr = name
            elif hasattr(model_admin, name):
                attr = getattr(model_admin, name)
            elif hasattr(model, name):
                attr = getattr(model, name)
            elif form and name in form.fields:
                attr = form.fields[name]
            else:
                try:
                    attr = get_fields_from_path(model, name)[-1]
                except (FieldDoesNotExist, NotRelationField):
                    message = f"Unable to lookup '{name}' on {model._meta.object_name}"
                    if model_admin:
                        message += f' or {model_admin.__class__.__name__}'
                    if form:
                        message += f' or {form.__class__.__name__}'
                    raise AttributeError(message)
            if hasattr(attr, 'short_description'):
                label = attr.short_description
            elif isinstance(attr, property) and hasattr(attr, 'fget') and hasattr(attr.fget, 'short_description'):
                label = attr.fget.short_description
            elif callable(attr):
                if attr.__name__ == '<lambda>':
                    label = '--'
                else:
                    label = pretty_name(attr.__name__)
            else:
                label = pretty_name(name)
    except FieldIsAForeignKeyColumnName:
        label = pretty_name(name)
        attr = name
    if return_attr:
        return (label, attr)
    else:
        return label

def reverse_field_path(model, path):
    reversed_path = []
    parent = model
    pieces = path.split(LOOKUP_SEP)
    for piece in pieces:
        field = parent._meta.get_field(piece)
        if len(reversed_path) == len(pieces) - 1:
            try:
                get_model_from_relation(field)
            except NotRelationField:
                break
        if field.is_relation and (not (field.auto_created and (not field.concrete))):
            related_name = field.related_query_name()
            parent = field.remote_field.model
        else:
            related_name = field.field.name
            parent = field.related_model
        reversed_path.insert(0, related_name)
    return (parent, LOOKUP_SEP.join(reversed_path))

def get_fields_from_path(model, path):
    pieces = path.split(LOOKUP_SEP)
    fields = []
    for piece in pieces:
        if fields:
            parent = get_model_from_relation(fields[-1])
        else:
            parent = model
        fields.append(parent._meta.get_field(piece))
    return fields

def construct_change_message(form, formsets, add):
    change_message = []
    if add:
        change_message.append({'added': {}})
    elif (changed_data := form.changed_data):
        with translation_override(None):
            changed_field_labels = _get_changed_field_labels_from_form(form, changed_data)
        change_message.append({'changed': {'fields': changed_field_labels}})
    if formsets:
        with translation_override(None):
            for formset in formsets:
                for added_object in formset.new_objects:
                    change_message.append({'added': {'name': str(added_object._meta.verbose_name), 'object': str(added_object)}})
                for changed_object, changed_fields in formset.changed_objects:
                    change_message.append({'changed': {'name': str(changed_object._meta.verbose_name), 'object': str(changed_object), 'fields': _get_changed_field_labels_from_form(formset.forms[0], changed_fields)}})
                for deleted_object in formset.deleted_objects:
                    change_message.append({'deleted': {'name': str(deleted_object._meta.verbose_name), 'object': str(deleted_object)}})
    return change_message

def nested(self, format_callback=None):
    seen = set()
    roots = []
    for root in self.edges.get(None, ()):
        roots.extend(self._nested(root, seen, format_callback))
    return roots

def url_params_from_lookup_dict(lookups):
    params = {}
    if lookups and hasattr(lookups, 'items'):
        for k, v in lookups.items():
            if callable(v):
                v = v()
            if isinstance(v, (tuple, list)):
                v = ','.join((str(x) for x in v))
            elif isinstance(v, bool):
                v = ('0', '1')[v]
            else:
                v = str(v)
            params[k] = v
    return params

@register.filter(is_safe=True, needs_autoescape=True)
def truncated_unordered_list(value, max_items, autoescape=True):
    has_unlimited_items = max_items is None
    if not has_unlimited_items:
        max_items = int(max_items)
        if max_items <= 0:
            return mark_safe('')
    if autoescape:
        escaper = conditional_escape
    else:

        def escaper(x):
            return x
    item_count = 0

    def list_formatter(item_list, tabs=1):
        nonlocal item_count
        indent = '\t' * tabs
        output = []
        for item, children in _walk_items(item_list):
            sublist = ''
            item_count += 1
            should_display_item = has_unlimited_items or 0 < item_count <= max_items
            if children:
                sublist = '\n%s<ul>\n%s\n%s</ul>\n%s' % (indent, list_formatter(children, tabs + 1), indent, indent)
            if should_display_item:
                output.append('%s<li>%s%s</li>' % (indent, escaper(item), sublist))
        return '\n'.join(output)
    rendered_object_list = list_formatter(value)
    remaining_objects_message = ''
    if not has_unlimited_items and item_count > max_items:
        remaining_object_count = item_count - max_items
        remaining_objects_message = '\n\t<li>%s</li>' % (ngettext('…and %(count)d more object.', '…and %(count)d more objects.', remaining_object_count) % {'count': remaining_object_count})
    return mark_safe(rendered_object_list + remaining_objects_message)

@register.simple_tag
def paginator_number(cl, i):
    if i == cl.paginator.ELLIPSIS:
        return format_html('{} ', cl.paginator.ELLIPSIS)
    elif i == cl.page_num:
        return format_html('<a role="button" href="" aria-current="page">{}</a> ', i)
    else:
        return format_html('<a role="button" href="{}">{}</a> ', cl.get_query_string({PAGE_VAR: i}), i)

def pagination(cl):
    pagination_required = (not cl.show_all or not cl.can_show_all) and cl.multi_page
    page_range = cl.paginator.get_elided_page_range(cl.page_num) if pagination_required else []
    need_show_all_link = cl.can_show_all and (not cl.show_all) and cl.multi_page
    return {'cl': cl, 'pagination_required': pagination_required, 'show_all_url': need_show_all_link and cl.get_query_string({ALL_VAR: ''}), 'page_range': page_range, 'ALL_VAR': ALL_VAR, '1': 1}

def result_headers(cl):
    ordering_field_columns = cl.get_ordering_field_columns()
    for i, field_name in enumerate(cl.list_display):
        text, attr = label_for_field(field_name, cl.model, model_admin=cl.model_admin, return_attr=True)
        is_field_sortable = cl.sortable_by is None or field_name in cl.sortable_by
        if attr:
            field_name = _coerce_field_name(field_name, i)
            if field_name == 'action_checkbox':
                aria_label = _('Select all objects on this page for an action')
                yield {'text': SafeString(f'<input type="checkbox" id="action-toggle" aria-label="{aria_label}">'), 'class_attrib': SafeString(' class="action-checkbox-column"'), 'sortable': False}
                continue
            admin_order_field = getattr(attr, 'admin_order_field', None)
            if isinstance(attr, property) and hasattr(attr, 'fget'):
                admin_order_field = getattr(attr.fget, 'admin_order_field', None)
            if not admin_order_field and LOOKUP_SEP not in field_name:
                is_field_sortable = False
        if not is_field_sortable:
            yield {'text': text, 'class_attrib': format_html(' class="column-{}"', field_name), 'sortable': False}
            continue
        th_classes = ['sortable', 'column-{}'.format(field_name)]
        order_type = ''
        new_order_type = 'asc'
        sort_priority = 0
        is_sorted = i in ordering_field_columns
        if is_sorted:
            order_type = ordering_field_columns.get(i).lower()
            sort_priority = list(ordering_field_columns).index(i) + 1
            th_classes.append('sorted %sending' % order_type)
            new_order_type = {'asc': 'desc', 'desc': 'asc'}[order_type]
        o_list_primary = []
        o_list_remove = []
        o_list_toggle = []

        def make_qs_param(t, n):
            return ('-' if t == 'desc' else '') + str(n)
        for j, ot in ordering_field_columns.items():
            if j == i:
                param = make_qs_param(new_order_type, j)
                o_list_primary.insert(0, param)
                o_list_toggle.append(param)
            else:
                param = make_qs_param(ot, j)
                o_list_primary.append(param)
                o_list_toggle.append(param)
                o_list_remove.append(param)
        if i not in ordering_field_columns:
            o_list_primary.insert(0, make_qs_param(new_order_type, i))
        yield {'text': text, 'sortable': True, 'sorted': is_sorted, 'ascending': order_type == 'asc', 'sort_priority': sort_priority, 'url_primary': cl.get_query_string({ORDER_VAR: '.'.join(o_list_primary)}), 'url_remove': cl.get_query_string({ORDER_VAR: '.'.join(o_list_remove)}), 'url_toggle': cl.get_query_string({ORDER_VAR: '.'.join(o_list_toggle)}), 'class_attrib': format_html(' class="{}"', ' '.join(th_classes)) if th_classes else ''}

def _coerce_field_name(field_name, field_index):
    if callable(field_name):
        if field_name.__name__ == '<lambda>':
            return 'lambda' + str(field_index)
        else:
            return field_name.__name__
    return field_name

def items_for_result(cl, result, form):

    def link_in_col(is_first, field_name, cl):
        if cl.list_display_links is None:
            return False
        if is_first and (not cl.list_display_links):
            return True
        return field_name in cl.list_display_links
    first = True
    pk = cl.lookup_opts.pk.attname
    for field_index, field_name in enumerate(cl.list_display):
        empty_value_display = cl.model_admin.get_empty_value_display()
        row_classes = ['field-%s' % _coerce_field_name(field_name, field_index)]
        link_to_changelist = link_in_col(first, field_name, cl)
        try:
            f, attr, value = lookup_field(field_name, result, cl.model_admin)
        except ObjectDoesNotExist:
            result_repr = empty_value_display
        else:
            empty_value_display = getattr(attr, 'empty_value_display', empty_value_display)
            if f is None or f.auto_created:
                if field_name == 'action_checkbox':
                    row_classes = ['action-checkbox']
                boolean = getattr(attr, 'boolean', False)
                if isinstance(attr, property) and hasattr(attr, 'fget'):
                    boolean = getattr(attr.fget, 'boolean', False)
                result_repr = display_for_value(value, empty_value_display, boolean)
                if isinstance(value, (datetime.date, datetime.time)):
                    row_classes.append('nowrap')
            else:
                if isinstance(f.remote_field, models.ManyToOneRel):
                    field_val = getattr(result, f.name)
                    if field_val is None:
                        result_repr = empty_value_display
                    else:
                        result_repr = field_val
                else:
                    result_repr = display_for_field(value, f, empty_value_display, avoid_link=link_to_changelist)
                if isinstance(f, (models.DateField, models.TimeField, models.ForeignKey)):
                    row_classes.append('nowrap')
        row_class = SafeString(' class="%s"' % ' '.join(row_classes))
        if link_to_changelist:
            table_tag = 'th' if first else 'td'
            first = False
            try:
                url = cl.url_for_result(result)
            except NoReverseMatch:
                link_or_text = result_repr
            else:
                url = add_preserved_filters({'preserved_filters': cl.preserved_filters, 'opts': cl.opts}, url)
                if cl.to_field:
                    attr = str(cl.to_field)
                else:
                    attr = pk
                value = result.serializable_value(attr)
                link_or_text = format_html('<a href="{}"{}>{}</a>', url, format_html(' data-popup-opener="{}"', value) if cl.is_popup else '', result_repr)
            yield format_html('<{}{}>{}</{}>', table_tag, row_class, link_or_text, table_tag)
        else:
            if form and field_name in form.fields and (not (field_name == cl.model._meta.pk.name and form[cl.model._meta.pk.name].is_hidden)):
                bf = form[field_name]
                result_repr = mark_safe(str(bf.errors) + str(bf))
            yield format_html('<td{}>{}</td>', row_class, result_repr)
    if form and (not form[cl.model._meta.pk.name].is_hidden):
        yield format_html('<td>{}</td>', form[cl.model._meta.pk.name])

def result_list(cl):
    headers = list(result_headers(cl))
    num_sorted_fields = 0
    for h in headers:
        if h['sortable'] and h['sorted']:
            num_sorted_fields += 1
    return {'cl': cl, 'result_hidden_fields': list(result_hidden_fields(cl)), 'result_headers': headers, 'num_sorted_fields': num_sorted_fields, 'results': list(results(cl))}

def date_hierarchy(cl):
    if cl.date_hierarchy:
        field_name = cl.date_hierarchy
        field = get_fields_from_path(cl.model, field_name)[-1]
        field_verbose_name = field.verbose_name
        if isinstance(field, models.DateTimeField):
            dates_or_datetimes = 'datetimes'
        else:
            dates_or_datetimes = 'dates'
        year_field = '%s__year' % field_name
        month_field = '%s__month' % field_name
        day_field = '%s__day' % field_name
        field_generic = '%s__' % field_name
        year_lookup = cl.params.get(year_field)
        month_lookup = cl.params.get(month_field)
        day_lookup = cl.params.get(day_field)

        def link(filters):
            return cl.get_query_string(filters, [field_generic])
        if not (year_lookup or month_lookup or day_lookup):
            date_range = cl.queryset.aggregate(first=models.Min(field_name), last=models.Max(field_name))
            if date_range['first'] and date_range['last']:
                if dates_or_datetimes == 'datetimes':
                    date_range = {k: timezone.localtime(v) if timezone.is_aware(v) else v for k, v in date_range.items()}
                if date_range['first'].year == date_range['last'].year:
                    year_lookup = date_range['first'].year
                    if date_range['first'].month == date_range['last'].month:
                        month_lookup = date_range['first'].month
        if year_lookup and month_lookup and day_lookup:
            day = datetime.date(int(year_lookup), int(month_lookup), int(day_lookup))
            return {'show': True, 'back': {'link': link({year_field: year_lookup, month_field: month_lookup}), 'title': capfirst(formats.date_format(day, 'YEAR_MONTH_FORMAT'))}, 'choices': [{'title': capfirst(formats.date_format(day, 'MONTH_DAY_FORMAT'))}], 'field_name': field_verbose_name}
        elif year_lookup and month_lookup:
            days = getattr(cl.queryset, dates_or_datetimes)(field_name, 'day')
            return {'show': True, 'back': {'link': link({year_field: year_lookup}), 'title': str(year_lookup)}, 'choices': [{'link': link({year_field: year_lookup, month_field: month_lookup, day_field: day.day}), 'title': capfirst(formats.date_format(day, 'MONTH_DAY_FORMAT'))} for day in days], 'field_name': field_verbose_name}
        elif year_lookup:
            months = getattr(cl.queryset, dates_or_datetimes)(field_name, 'month')
            return {'show': True, 'back': {'link': link({}), 'title': _('All dates')}, 'choices': [{'link': link({year_field: year_lookup, month_field: month.month}), 'title': capfirst(formats.date_format(month, 'YEAR_MONTH_FORMAT'))} for month in months], 'field_name': field_verbose_name}
        else:
            years = getattr(cl.queryset, dates_or_datetimes)(field_name, 'year')
