    thing_being_parsed = thing_being_parsed and '<%s>' % thing_being_parsed
    source = '\n.. default-role:: cmsreference\n\n%s\n\n.. default-role::\n'
    writer_instance = docutils.writers.get_writer_class('html')()
    parts = docutils.core.publish_parts(source % text, source_path=thing_being_parsed, destination_path=None, writer=writer_instance, settings_overrides=overrides)
    return mark_safe(parts['fragment'])

