def verify_password(password, encoded, preferred='default'):
    fake_runtime = password is None or not is_password_usable(encoded)
    preferred = get_hasher(preferred)
    try:
        hasher = identify_hasher(encoded)
    except ValueError:
        fake_runtime = True
    if fake_runtime:
        make_password(get_random_string(UNUSABLE_PASSWORD_SUFFIX_LENGTH))
        return (False, False)
    hasher_changed = hasher.algorithm != preferred.algorithm
    must_update = hasher_changed or preferred.must_update(encoded)
    is_correct = hasher.verify(password, encoded)
    if not is_correct and (not hasher_changed) and must_update:
        hasher.harden_runtime(password, encoded)
    return (is_correct, must_update)

def check_password(password, encoded, setter=None, preferred='default'):
    is_correct, must_update = verify_password(password, encoded, preferred=preferred)
    if setter and is_correct and must_update:
        setter(password)
    return is_correct

def make_password(password, salt=None, hasher='default'):
    if password is None:
        return UNUSABLE_PASSWORD_PREFIX + get_random_string(UNUSABLE_PASSWORD_SUFFIX_LENGTH)
    if not isinstance(password, (bytes, str)):
        raise TypeError('Password must be a string or bytes, got %s.' % type(password).__qualname__)
    hasher = get_hasher(hasher)
    salt = salt or hasher.salt()
    return hasher.encode(password, salt)

def get_hasher(algorithm='default'):
    if hasattr(algorithm, 'algorithm'):
        return algorithm
    elif algorithm == 'default':
        return get_hashers()[0]
    else:
        hashers = get_hashers_by_algorithm()
        try:
            return hashers[algorithm]
        except KeyError:
            raise ValueError("Unknown password hashing algorithm '%s'. Did you specify it in the PASSWORD_HASHERS setting?" % algorithm)

def identify_hasher(encoded):
    if len(encoded) == 32 and '$' not in encoded or (len(encoded) == 37 and encoded.startswith('md5$$')):
        algorithm = 'unsalted_md5'
    elif len(encoded) == 46 and encoded.startswith('sha1$$'):
        algorithm = 'unsalted_sha1'
    else:
        algorithm = encoded.split('$', 1)[0]
    return get_hasher(algorithm)

def salt(self):
    char_count = math.ceil(self.salt_entropy / math.log2(len(RANDOM_STRING_CHARS)))
    return get_random_string(char_count, allowed_chars=RANDOM_STRING_CHARS)

