    redirect_to = request.POST.get(self.redirect_field_name, request.GET.get(self.redirect_field_name))
    url_is_safe = url_has_allowed_host_and_scheme(url=redirect_to, allowed_hosts=self.get_success_url_allowed_hosts(request), require_https=request.is_secure())
    return redirect_to if url_is_safe else ''

