def shortcut(request, content_type_id, object_id):
    try:
        content_type = ContentType.objects.get(pk=content_type_id)
        if not content_type.model_class():
            raise Http404(_('Content type %(ct_id)s object has no associated model') % {'ct_id': content_type_id})
        obj = content_type.get_object_for_this_type(pk=object_id)
    except (ObjectDoesNotExist, ValueError, ValidationError):
        raise Http404(_('Content type %(ct_id)s object %(obj_id)s doesn’t exist') % {'ct_id': content_type_id, 'obj_id': object_id})
    try:
        get_absolute_url = obj.get_absolute_url
    except AttributeError:
        raise Http404(_('%(ct_name)s objects don’t have a get_absolute_url() method') % {'ct_name': content_type.name})
    absurl = get_absolute_url()
    if absurl.startswith(('http://', 'https://', '//')):
        return HttpResponseRedirect(absurl)
    try:
        object_domain = get_current_site(request).domain
    except ObjectDoesNotExist:
        object_domain = None
    if apps.is_installed('django.contrib.sites'):
        Site = apps.get_model('sites.Site')
        opts = obj._meta
        for field in opts.many_to_many:
            if field.remote_field.model is Site:
                site_qs = getattr(obj, field.name).all()
                if object_domain and site_qs.filter(domain=object_domain).exists():
                    break
                site = site_qs.first()
                if site:
                    object_domain = site.domain
                    break
        else:
            for field in obj._meta.fields:
                if field.remote_field and field.remote_field.model is Site:
                    try:
                        site = getattr(obj, field.name)
                    except Site.DoesNotExist:
                        continue
                    if site is not None:
                        object_domain = site.domain
                        break
    if object_domain is not None:
        protocol = request.scheme
        return HttpResponseRedirect('%s://%s%s' % (protocol, object_domain, absurl))
    else:
        return HttpResponseRedirect(absurl)

def inject_rename_contenttypes_operations(plan=None, apps=global_apps, using=DEFAULT_DB_ALIAS, **kwargs):
    if plan is None:
        return
    try:
        ContentType = apps.get_model('contenttypes', 'ContentType')
    except LookupError:
        available = False
    else:
        if not router.allow_migrate_model(using, ContentType):
            return
        available = True
    for migration, backward in plan:
        if (migration.app_label, migration.name) == ('contenttypes', '0001_initial'):
            if backward:
                break
            else:
                available = True
                continue
        if not available:
            continue
        inserts = []
        for index, operation in enumerate(migration.operations):
            if isinstance(operation, migrations.RenameModel):
                operation = RenameContentType(migration.app_label, operation.old_name_lower, operation.new_name_lower)
                inserts.append((index + 1, operation))
        for inserted, (index, operation) in enumerate(inserts):
            migration.operations.insert(inserted + index, operation)

def create_contenttypes(app_config, verbosity=2, interactive=True, using=DEFAULT_DB_ALIAS, apps=global_apps, **kwargs):
    if not app_config.models_module:
        return
    try:
        app_config = apps.get_app_config(app_config.label)
        ContentType = apps.get_model('contenttypes', 'ContentType')
    except LookupError:
        return
    if not router.allow_migrate_model(using, ContentType):
        return
    all_model_names = {model._meta.model_name for model in app_config.get_models()}
    if not all_model_names:
        return
    ContentType.objects.clear_cache()
    existing_model_names = set(ContentType.objects.using(using).filter(app_label=app_config.label).values_list('model', flat=True))
    cts = [ContentType(app_label=app_config.label, model=model_name) for model_name in sorted(all_model_names - existing_model_names)]
    ContentType.objects.using(using).bulk_create(cts)
    if verbosity >= 2:
        for ct in cts:
            print(f"Adding content type '{ct.app_label} | {ct.model}'")

