    try:
        version = self.spatialite_version_tuple()[1:]
    except Exception as exc:
        raise ImproperlyConfigured('Cannot determine the SpatiaLite version for the "%s" database. Was the SpatiaLite initialization SQL loaded on this database?' % (self.connection.settings_dict['NAME'],)) from exc
    if version < (4, 3, 0):
        raise ImproperlyConfigured('GeoDjango supports SpatiaLite 4.3.0 and above.')
    return version

def convert_extent(self, box):
    if box is None:
        return None
    shell = GEOSGeometry(box).shell
    xmin, ymin = shell[0][:2]
    xmax, ymax = shell[2][:2]
    return (xmin, ymin, xmax, ymax)

def get_distance(self, f, value, lookup_type):
    if not value:
        return []
    value = value[0]
    if isinstance(value, Distance):
        if f.geodetic(self.connection):
            if lookup_type == 'dwithin':
                raise ValueError('Only numeric values of degree units are allowed on geographic DWithin queries.')
            dist_param = value.m
        else:
            dist_param = getattr(value, Distance.unit_attname(f.units_name(self.connection)))
    else:
        dist_param = value
    return [dist_param]

