    return (sql, params)

def process_band_indices(self, only_lhs=False):
    if only_lhs:
        self.band_rhs = 1
        self.band_lhs = self.lhs.band_index + 1
        return
    if isinstance(self.lhs, RasterBandTransform):
        self.band_lhs = self.lhs.band_index + 1
    else:
        self.band_lhs = 1
    self.band_rhs, *self.rhs_params = self.rhs_params

def __get__(self, instance, cls=None):
    if instance is None:
        return self
    try:
        geo_value = instance.__dict__[self.field.attname]
    except KeyError:
        geo_value = super().__get__(instance, cls)
    if isinstance(geo_value, self._klass):
        geo_obj = geo_value
    elif geo_value is None or geo_value == '':
        geo_obj = None
    else:
        geo_obj = self._load_func(geo_value)
        setattr(instance, self.field.attname, geo_obj)
    return geo_obj

def __set__(self, instance, value):
    gtype = self.field.geom_type
    if gtype == 'RASTER' and (value is None or isinstance(value, (str, dict, self._klass))):
        pass
    elif isinstance(value, self._klass):
        if value.srid is None:
            value.srid = self.field.srid
    elif value is None or isinstance(value, (str, memoryview)):
        pass
    else:
        raise TypeError('Cannot set %s SpatialProxy (%s) with value of type: %s' % (instance.__class__.__name__, gtype, type(value)))
    instance.__dict__[self.field.attname] = value
    return value

def to_python(self, value):
    if value in self.empty_values:
        return None
    if not isinstance(value, GEOSGeometry):
        if hasattr(self.widget, 'deserialize'):
            value = self.widget.deserialize(value)
        else:
            try:
                value = GEOSGeometry(value)
            except (GEOSException, ValueError, TypeError):
                value = None
        if value is None:
            raise ValidationError(self.error_messages['invalid_geom'], code='invalid_geom')
    if not value.srid:
        try:
            value.srid = self.widget.map_srid
        except AttributeError:
            if self.srid:
                value.srid = self.srid
    return value

def clean(self, value):
    geom = super().clean(value)
    if geom is None:
        return geom
    if str(geom.geom_type).upper() != self.geom_type and self.geom_type != 'GEOMETRY':
        raise ValidationError(self.error_messages['invalid_geom_type'], code='invalid_geom_type')
    if self.srid and self.srid != -1 and (self.srid != geom.srid):
        try:
            geom.transform(self.srid)
        except GEOSException:
            raise ValidationError(self.error_messages['transform_error'], code='transform_error')
    return geom

def has_changed(self, initial, data):
    try:
        data = self.to_python(data)
        initial = self.to_python(initial)
    except ValidationError:
        return True
    if initial and data:
        data.transform(initial.srid)
        return not initial.equals_exact(data, tolerance=1e-06)
    else:
        return bool(initial) != bool(data)

