def __init__(self, *args):
    if len(args) == 1:
        if isinstance(args[0], OGREnvelope):
            self._envelope = args[0]
        elif isinstance(args[0], (tuple, list)):
            if len(args[0]) != 4:
                raise GDALException('Incorrect number of tuple elements (%d).' % len(args[0]))
            else:
                self._from_sequence(args[0])
        else:
            raise TypeError('Incorrect type of argument: %s' % type(args[0]))
    elif len(args) == 4:
        self._from_sequence([float(a) for a in args])
    else:
        raise GDALException('Incorrect number (%d) of arguments.' % len(args))
    if self.min_x > self.max_x:
        raise GDALException('Envelope minimum X > maximum X.')
    if self.min_y > self.max_y:
        raise GDALException('Envelope minimum Y > maximum Y.')

def __eq__(self, other):
    if isinstance(other, Envelope):
        return self.min_x == other.min_x and self.min_y == other.min_y and (self.max_x == other.max_x) and (self.max_y == other.max_y)
    elif isinstance(other, tuple) and len(other) == 4:
        return self.min_x == other[0] and self.min_y == other[1] and (self.max_x == other[2]) and (self.max_y == other[3])
    else:
        raise GDALException('Equivalence testing only works with other Envelopes.')

def expand_to_include(self, *args):
    if len(args) == 1:
        if isinstance(args[0], Envelope):
            return self.expand_to_include(args[0].tuple)
        elif hasattr(args[0], 'x') and hasattr(args[0], 'y'):
            return self.expand_to_include(args[0].x, args[0].y, args[0].x, args[0].y)
        elif isinstance(args[0], (tuple, list)):
            if len(args[0]) == 2:
                return self.expand_to_include((args[0][0], args[0][1], args[0][0], args[0][1]))
            elif len(args[0]) == 4:
                minx, miny, maxx, maxy = args[0]
                if minx < self._envelope.MinX:
                    self._envelope.MinX = minx
                if miny < self._envelope.MinY:
                    self._envelope.MinY = miny
                if maxx > self._envelope.MaxX:
                    self._envelope.MaxX = maxx
                if maxy > self._envelope.MaxY:
                    self._envelope.MaxY = maxy
            else:
                raise GDALException('Incorrect number of tuple elements (%d).' % len(args[0]))
        else:
            raise TypeError('Incorrect type of argument: %s' % type(args[0]))
    elif len(args) == 2:
        return self.expand_to_include((args[0], args[1], args[0], args[1]))
    elif len(args) == 4:
        return self.expand_to_include(args)
    else:
        raise GDALException('Incorrect number (%d) of arguments.' % len(args[0]))

