def data(self, data=None, offset=None, size=None, shape=None, as_memoryview=False):
    offset = offset or (0, 0)
    size = size or (self.width - offset[0], self.height - offset[1])
    shape = shape or size
    if any((x <= 0 for x in size)):
        raise ValueError('Offset too big for this raster.')
    if size[0] > self.width or size[1] > self.height:
        raise ValueError('Size is larger than raster.')
    ctypes_array = GDAL_TO_CTYPES[self.datatype()] * (shape[0] * shape[1])
    if data is None:
        access_flag = 0
        data_array = ctypes_array()
    else:
        access_flag = 1
        if isinstance(data, (bytes, memoryview)) or (numpy and isinstance(data, numpy.ndarray)):
            data_array = ctypes_array.from_buffer_copy(data)
        else:
            data_array = ctypes_array(*data)
    capi.band_io(self._ptr, access_flag, offset[0], offset[1], size[0], size[1], byref(data_array), shape[0], shape[1], self.datatype(), 0, 0)
    if data is None:
        if as_memoryview:
            return memoryview(data_array)
        elif numpy:
            return numpy.frombuffer(data_array, dtype=numpy.dtype(data_array)).reshape(tuple(reversed(size)))
        else:
            return list(data_array)
    else:
        self._flush()

@property
def metadata(self):
    domain_list = ['DEFAULT']
    meta_list = capi.get_ds_metadata_domain_list(self._ptr)
    if meta_list:
        counter = 0
        domain = meta_list[counter]
        while domain:
            domain_list.append(domain.decode())
            counter += 1
            domain = meta_list[counter]
    capi.free_dsl(meta_list)
    result = {}
    for domain in domain_list:
        data = capi.get_ds_metadata(self._ptr, None if domain == 'DEFAULT' else domain.encode())
        if not data:
            continue
        domain_meta = {}
        counter = 0
        item = data[counter]
        while item:
            key, val = item.decode().split('=')
            domain_meta[key] = val
            counter += 1
            item = data[counter]
        result[domain or 'DEFAULT'] = domain_meta
    return result

@metadata.setter
def metadata(self, value):
    for domain, metadata in value.items():
        domain = None if domain == 'DEFAULT' else domain.encode()
        for meta_name, meta_value in metadata.items():
            capi.set_ds_metadata_item(self._ptr, meta_name.encode(), meta_value.encode() if meta_value else None, domain)

