        iterator = iter(stream_or_iterable)
    except TypeError:
        iterator = ChunkIter(stream_or_iterable, 16384)

    for __ in iterator:
        pass

def get_commands():
    commands = {name: 'django.core' for name in find_commands(__path__[0])}

    # Find the installed apps
    try:
        settings.INSTALLED_APPS
    except ImproperlyConfigured:
        # Still useful for commands that do not require functional
        # settings, like startproject or help.
        app_names = []
    else:
        # Setup Django outside of the try/except block to avoid catching
        # ImproperlyConfigured errors that aren't caused by the absence of
        # a settings module.
        django.setup()
        app_configs = apps.get_app_configs()
        app_names = [app_config.name for app_config in app_configs]

    # Find and load the management module for each installed app.
    for app_name in app_names:
        try:
            path = find_management_module(app_name)
            commands.update({name: app_name for name in find_commands(path)})
        except ImportError:
            pass  # No management module - ignore this app

    return commands

def as_sql(self, qn=None):
    if not qn:
        qn = connection.ops.quote_name
    if not self.children:
        return None, []
    result = []
    result_params = []
    empty = True
    for child in self.children:
        try:
            if hasattr(child, 'as_sql'):
                sql, params = child.as_sql(qn=qn)
            else:
                # A leaf node in the tree.
                sql, params = self.make_atom(child, qn)
        except EmptyResultSet:
            if self.connector == AND and not self.negated:
                # We can bail out early in this particular case (only).
                raise
            elif self.negated:
                empty = False
            continue
        except FullResultSet:
            if self.connector == OR:
                if self.negated:
                    empty = True
                    break
                # We match everything. No need for any constraints.
                return '', []
            if self.negated:
                empty = True
            continue
        empty = False
        if sql:
            result.append(sql)
            result_params.extend(params)
    if empty:
        raise EmptyResultSet

    conn = ' %s ' % self.connector
    sql_string = conn.join(result)
    if sql_string:
        if self.negated:
            sql_string = 'NOT (%s)' % sql_string
        elif len(self.children) != 1:
            sql_string = '(%s)' % sql_string
    return sql_string, result_params

def __init__(self, geo_input, srid=None):
    input_srid = None
    if isinstance(geo_input, bytes):
        geo_input = force_str(geo_input)
    if isinstance(geo_input, str):
        wkt_m = wkt_regex.match(geo_input)
        if wkt_m:
            if wkt_m['srid']:
                input_srid = int(wkt_m['srid'])
            g = self._from_wkt(force_bytes(wkt_m['wkt']))
        elif hex_regex.match(geo_input):
            g = wkb_r().read(force_bytes(geo_input))
        elif json_regex.match(geo_input):
            ogr = gdal.OGRGeometry.from_json(geo_input)
            g = ogr._geos_ptr()
            input_srid = ogr.srid
        else:
            raise ValueError('String input unrecognized as WKT EWKT, and HEXEWKB.')
    elif isinstance(geo_input, GEOM_PTR):
        g = geo_input
    elif isinstance(geo_input, memoryview):
        g = wkb_r().read(geo_input)
    elif isinstance(geo_input, GEOSGeometry):
        g = capi.geom_clone(geo_input.ptr)
    else:
        raise TypeError('Improper geometry input type: %s' % type(geo_input))
    if not g:
        raise GEOSException('Could not initialize GEOS Geometry with given input.')
    input_srid = input_srid or capi.geos_get_srid(g) or None
    if input_srid and srid and (input_srid != srid):
        raise ValueError('Input geometry already has SRID: %d.' % input_srid)
    super().__init__(g, None)
    srid = input_srid or srid
    if srid and isinstance(srid, int):
        self.srid = srid

