def _build_kml_sources(self, sources):
    kml_sources = []
    if sources is None:
        sources = apps.get_models()
    for source in sources:
        if isinstance(source, models.base.ModelBase):
            for field in source._meta.fields:
                if isinstance(field, GeometryField):
                    kml_sources.append((source._meta.app_label, source._meta.model_name, field.name))
        elif isinstance(source, (list, tuple)):
            if len(source) != 3:
                raise ValueError('Must specify a 3-tuple of (app_label, module_name, field_name).')
            kml_sources.append(source)
        else:
            raise TypeError('KML Sources must be a model or a 3-tuple.')
    return kml_sources

def kml(request, label, model, field_name=None, compress=False, using=DEFAULT_DB_ALIAS):
    placemarks = []
    try:
        klass = apps.get_model(label, model)
    except LookupError:
        raise Http404('You must supply a valid app label and module name. Got "%s.%s"' % (label, model))
    if field_name:
        try:
            field = klass._meta.get_field(field_name)
            if not isinstance(field, GeometryField):
                raise FieldDoesNotExist
        except FieldDoesNotExist:
            raise Http404('Invalid geometry field.')
    connection = connections[using]
    if connection.features.has_AsKML_function:
        placemarks = klass._default_manager.using(using).annotate(kml=AsKML(field_name))
    else:
        placemarks = []
        if connection.features.has_Transform_function:
            qs = klass._default_manager.using(using).annotate(**{'%s_4326' % field_name: Transform(field_name, 4326)})
            field_name += '_4326'
        else:
            qs = klass._default_manager.using(using).all()
        for mod in qs:
            mod.kml = getattr(mod, field_name).kml
            placemarks.append(mod)
    if compress:
        render = render_to_kmz
    else:
        render = render_to_kml
    return render('gis/kml/placemarks.kml', {'places': placemarks})

def __init__(self, model, data, mapping, layer=0, source_srs=None, encoding='utf-8', transaction_mode='commit_on_success', transform=True, unique=None, using=None):
    if isinstance(data, (str, Path)):
        self.ds = DataSource(data, encoding=encoding)
    else:
        self.ds = data
    self.layer = self.ds[layer]
    self.using = using if using is not None else router.db_for_write(model)
    connection = connections[self.using]
    self.spatial_backend = connection.ops
    self.mapping = mapping
    self.model = model
    self.check_layer()
    if connection.features.supports_transform:
        self.geo_field = self.geometry_field()
    else:
        transform = False
    if transform:
        self.source_srs = self.check_srs(source_srs)
        self.transform = self.coord_transform()
    else:
        self.transform = transform
    if encoding:
        from codecs import lookup
        lookup(encoding)
        self.encoding = encoding
    else:
        self.encoding = None
    if unique:
        self.check_unique(unique)
        transaction_mode = 'autocommit'
        self.unique = unique
    else:
        self.unique = None
    self.transaction_mode = transaction_mode
    if transaction_mode == 'autocommit':
        self.transaction_decorator = None
    elif transaction_mode == 'commit_on_success':
        self.transaction_decorator = transaction.atomic
    else:
        raise LayerMapError('Unrecognized transaction mode: %s' % transaction_mode)

def check_fid_range(self, fid_range):
    if fid_range:
        if isinstance(fid_range, (tuple, list)):
            return slice(*fid_range)
        elif isinstance(fid_range, slice):
            return fid_range
        else:
            raise TypeError
    else:
        return None

def check_unique(self, unique):
    if isinstance(unique, (list, tuple)):
        for attr in unique:
            if attr not in self.mapping:
                raise ValueError
    elif isinstance(unique, str):
        if unique not in self.mapping:
            raise ValueError
    else:
        raise TypeError('Unique keyword argument must be set with a tuple, list, or string.')

def feature_kwargs(self, feat):
    kwargs = {}
    for field_name, ogr_name in self.mapping.items():
        model_field = self.fields[field_name]
        if isinstance(model_field, GeometryField):
            try:
                val = self.verify_geom(feat.geom, model_field)
            except GDALException:
                raise LayerMapError('Could not retrieve geometry from feature.')
        elif isinstance(model_field, models.base.ModelBase):
            val = self.verify_fk(feat, model_field, ogr_name)
        else:
            val = self.verify_ogr_field(feat[ogr_name], model_field)
        kwargs[field_name] = val
    return kwargs

def unique_kwargs(self, kwargs):
    if isinstance(self.unique, str):
        return {self.unique: kwargs[self.unique]}
    else:
        return {fld: kwargs[fld] for fld in self.unique}

def verify_geom(self, geom, model_field):
    if geom.is_measured:
        geom.set_measured(False)
    if self.coord_dim == 2 and geom.is_3d:
        geom.set_3d(False)
    if self.make_multi(geom.geom_type, model_field):
        multi_type = self.MULTI_TYPES[geom.geom_type.num]
        g = OGRGeometry(multi_type)
        g.add(geom)
    else:
        g = geom
    if self.transform:
        g.transform(self.transform)
    return g.wkt

def coord_transform(self):
    SpatialRefSys = self.spatial_backend.spatial_ref_sys()
    try:
        target_srs = SpatialRefSys.objects.using(self.using).get(srid=self.geo_field.srid).srs
        return CoordTransform(self.source_srs, target_srs)
    except Exception as exc:
        raise LayerMapError('Could not translate between the data source and model geometry.') from exc

def geometry_field(self):
    opts = self.model._meta
    return opts.get_field(self.geom_field)

def save(self, verbose=False, fid_range=False, step=False, progress=False, silent=False, stream=sys.stdout, strict=False):
    default_range = self.check_fid_range(fid_range)
    if progress:
        if progress is True or not isinstance(progress, int):
            progress_interval = 1000
        else:
            progress_interval = progress

    def _save(feat_range=default_range, num_feat=0, num_saved=0):
        if feat_range:
            layer_iter = self.layer[feat_range]
        else:
            layer_iter = self.layer
        for feat in layer_iter:
            num_feat += 1
            try:
                kwargs = self.feature_kwargs(feat)
            except LayerMapError as msg:
                if strict:
                    raise
                elif not silent:
                    stream.write('Ignoring Feature ID %s because: %s\n' % (feat.fid, msg))
            else:
                is_update = False
                if self.unique:
                    try:
                        u_kwargs = self.unique_kwargs(kwargs)
                        m = self.model.objects.using(self.using).get(**u_kwargs)
                        is_update = True
                        geom_value = getattr(m, self.geom_field)
                        if geom_value is None:
                            geom = OGRGeometry(kwargs[self.geom_field])
                        else:
                            geom = geom_value.ogr
                            new = OGRGeometry(kwargs[self.geom_field])
                            for g in new:
                                geom.add(g)
                        setattr(m, self.geom_field, geom.wkt)
                    except ObjectDoesNotExist:
                        m = self.model(**kwargs)
                else:
                    m = self.model(**kwargs)
                try:
                    m.save(using=self.using)
                    num_saved += 1
                    if verbose:
                        stream.write('%s: %s\n' % ('Updated' if is_update else 'Saved', m))
                except Exception as msg:
                    if strict:
                        if not silent:
                            stream.write('Failed to save the feature (id: %s) into the model with the keyword arguments:\n' % feat.fid)
                            stream.write('%s\n' % kwargs)
                        raise
                    elif not silent:
                        stream.write('Failed to save %s:\n %s\nContinuing\n' % (kwargs, msg))
            if progress and num_feat % progress_interval == 0:
                stream.write('Processed %d features, saved %d ...\n' % (num_feat, num_saved))
        return (num_saved, num_feat)
    if self.transaction_decorator is not None:
        _save = self.transaction_decorator(_save)
    nfeat = self.layer.num_feat
    if step and isinstance(step, int) and (step < nfeat):
        if default_range:
            raise LayerMapError('The `step` keyword may not be used in conjunction with the `fid_range` keyword.')
        beg, num_feat, num_saved = (0, 0, 0)
        indices = range(step, nfeat, step)
        n_i = len(indices)
        for i, end in enumerate(indices):
            if i + 1 == n_i:
                step_slice = slice(beg, None)
            else:
                step_slice = slice(beg, end)
            try:
                num_feat, num_saved = _save(step_slice, num_feat, num_saved)
                beg = end
            except Exception:
                stream.write('%s\nFailed to save slice: %s\n' % ('=-' * 20, step_slice))
                raise
    else:
        _save()

def ogrinfo(data_source, num_features=10):
    if isinstance(data_source, str):
        data_source = DataSource(data_source)
    elif isinstance(data_source, DataSource):
        pass
    else:
        raise Exception('Data source parameter must be a string or a DataSource object.')
    for i, layer in enumerate(data_source):
        print('data source : %s' % data_source.name)
        print('==== layer %s' % i)
        print('  shape type: %s' % GEO_CLASSES[layer.geom_type.num].__name__)
        print('  # features: %s' % len(layer))
        print('         srs: %s' % layer.srs)
        extent_tup = layer.extent.tuple
        print('      extent: %s - %s' % (extent_tup[0:2], extent_tup[2:4]))
        print('Displaying the first %s features ====' % num_features)
        width = max(*map(len, layer.fields))
        fmt = ' %%%ss: %%s' % width
        for j, feature in enumerate(layer[:num_features]):
            print('=== Feature %s' % j)
            for fld_name in layer.fields:
                type_name = feature[fld_name].type_name
                output = fmt % (fld_name, type_name)
                val = feature.get(fld_name)
                if val:
                    if isinstance(val, str):
                        val_fmt = ' ("%s")'
                    else:
                        val_fmt = ' (%s)'
                    output += val_fmt % val
                else:
                    output += ' (None)'
                print(output)

def mapping(data_source, geom_name='geom', layer_key=0, multi_geom=False):
    if isinstance(data_source, str):
        data_source = DataSource(data_source)
    elif isinstance(data_source, DataSource):
        pass
    else:
        raise TypeError('Data source parameter must be a string or a DataSource object.')
    _mapping = {}
    for field in data_source[layer_key].fields:
        mfield = field.lower()
        if mfield[-1:] == '_':
            mfield += 'field'
        _mapping[mfield] = field
    gtype = data_source[layer_key].geom_type
    if multi_geom:
        gtype.to_multi()
    _mapping[geom_name] = str(gtype).upper()
    return _mapping

