        kwargs['ref_sys_name'] = ref_sys_name or srs.name
    try:
        SpatialRefSys.objects.using(database).get(srid=srs.srid)
    except SpatialRefSys.DoesNotExist:
        SpatialRefSys.objects.using(database).create(**kwargs)

