def chunks(self, chunk_size=None):
    chunk_size = chunk_size or self.DEFAULT_CHUNK_SIZE
    try:
        self.seek(0)
    except (AttributeError, UnsupportedOperation):
        pass
    while True:
        data = self.read(chunk_size)
        if not data:
            break
        yield data

def get_image_dimensions(file_or_path, close=False):
    from PIL import ImageFile as PillowImageFile
    p = PillowImageFile.Parser()
    if hasattr(file_or_path, 'read'):
        file = file_or_path
        file_pos = file.tell()
        file.seek(0)
    else:
        try:
            file = open(file_or_path, 'rb')
        except OSError:
            return (None, None)
        close = True
    try:
        chunk_size = 1024
        while 1:
            data = file.read(chunk_size)
            if not data:
                break
            try:
                p.feed(data)
            except zlib.error as e:
                if e.args[0].startswith('Error -5'):
                    pass
                else:
                    raise
            except struct.error:
                pass
            except RuntimeError:
                pass
            if p.image:
                return p.image.size
            chunk_size *= 2
        return (None, None)
    finally:
        if close:
            file.close()
        else:
            file.seek(file_pos)

def file_move_safe(old_file_name, new_file_name, chunk_size=1024 * 64, allow_overwrite=False):
    try:
        if os.path.samefile(old_file_name, new_file_name):
            return
    except OSError:
        pass
    if not allow_overwrite and os.access(new_file_name, os.F_OK):
        raise FileExistsError(f'Destination file {new_file_name} exists and allow_overwrite is False.')
    try:
        os.rename(old_file_name, new_file_name)
        return
    except OSError:
        pass
    with open(old_file_name, 'rb') as old_file:
        fd = os.open(new_file_name, os.O_WRONLY | os.O_CREAT | getattr(os, 'O_BINARY', 0) | (os.O_EXCL if not allow_overwrite else 0) | os.O_TRUNC)
        try:
            locks.lock(fd, locks.LOCK_EX)
            current_chunk = None
            while current_chunk != b'':
                current_chunk = old_file.read(chunk_size)
                os.write(fd, current_chunk)
        finally:
            locks.unlock(fd)
            os.close(fd)
    try:
        copystat(old_file_name, new_file_name)
    except PermissionError:
        try:
            copymode(old_file_name, new_file_name)
        except PermissionError:
            pass
    try:
        os.remove(old_file_name)
    except PermissionError as e:
        if getattr(e, 'winerror', 0) != 32:
            raise

@classmethod
def from_dict(cls, file_dict):
    return cls(file_dict['filename'], file_dict['content'], file_dict.get('content-type', 'text/plain'))

def new_file(self, *args, **kwargs):
    super().new_file(*args, **kwargs)
    self.file = TemporaryUploadedFile(self.file_name, self.content_type, 0, self.charset, self.content_type_extra)

def handle_raw_input(self, input_data, META, content_length, boundary, encoding=None):
    stream = getattr(input_data, '_stream', input_data)
    try:
        content_length = stream.seek(0, os.SEEK_END)
    except (UnsupportedOperation, AttributeError):
        pass
    else:
        stream.seek(0)
    self.activated = content_length is not None and content_length <= settings.FILE_UPLOAD_MAX_MEMORY_SIZE

def file_complete(self, file_size):
    if not self.activated:
        return
    self.file.seek(0)
    return InMemoryUploadedFile(file=self.file, field_name=self.field_name, name=self.file_name, content_type=self.content_type, size=file_size, charset=self.charset, content_type_extra=self.content_type_extra)

def get_available_name(self, name, max_length=None):
    name = str(name).replace('\\', '/')
    dir_name, file_name = os.path.split(name)
    if '..' in pathlib.PurePath(dir_name).parts:
        raise SuspiciousFileOperation("Detected path traversal attempt in '%s'" % dir_name)
    validate_file_name(file_name)
    file_ext = ''.join(pathlib.PurePath(file_name).suffixes)
    file_root = file_name.removesuffix(file_ext)
    while not self.is_name_available(name, max_length=max_length):
        name = os.path.join(dir_name, self.get_alternative_name(file_root, file_ext))
        if max_length is None:
            continue
        truncation = len(name) - max_length
        if truncation > 0:
            file_root = file_root[:-truncation]
            if not file_root:
                raise SuspiciousFileOperation('Storage can not find an available filename for "%s". Please make sure that the corresponding file field allows sufficient "max_length".' % name)
            name = os.path.join(dir_name, self.get_alternative_name(file_root, file_ext))
    return name

def generate_filename(self, filename):
    filename = str(filename).replace('\\', '/')
    dirname, filename = os.path.split(filename)
    if '..' in pathlib.PurePath(dirname).parts:
        raise SuspiciousFileOperation("Detected path traversal attempt in '%s'" % dirname)
    return os.path.normpath(os.path.join(dirname, self.get_valid_name(filename)))

def resolve(self, path, create_if_missing=False, leaf_cls=None, check_exists=True):
    path_segments = list(pathlib.Path(path).parts)
    current_node = self
    while path_segments:
        path_segment = path_segments.pop(0)
        if isinstance(current_node, InMemoryFileNode):
            path_segments = os.path.split(path)
            current_path = '/'.join(path_segments[:path_segments.index(path_segment)])
            raise NotADirectoryError(errno.ENOTDIR, os.strerror(errno.ENOTDIR), current_path)
        current_node = current_node._resolve_child(path_segment, create_if_missing, leaf_cls if len(path_segments) == 0 else InMemoryDirNode)
        if current_node is None:
            break
    if current_node is None and check_exists:
        raise FileNotFoundError(errno.ENOENT, os.strerror(errno.ENOENT), path)
    if leaf_cls and (not isinstance(current_node, leaf_cls)):
        error_cls, error_code = (NotADirectoryError, errno.ENOTDIR) if leaf_cls is InMemoryDirNode else (IsADirectoryError, errno.EISDIR)
        raise error_cls(error_code, os.strerror(error_code), path)
    return current_node

