async def send_response(self, response, send):
    response_headers = []
    for header, value in response.items():
        if isinstance(header, str):
            header = header.encode('ascii')
        if isinstance(value, str):
            value = value.encode('latin1')
        response_headers.append((bytes(header), bytes(value)))
    for c in response.cookies.values():
        response_headers.append((b'Set-Cookie', c.OutputString().encode('ascii')))
    await send({'type': 'http.response.start', 'status': response.status_code, 'headers': response_headers})
    if response.streaming:
        async with aclosing(aiter(response)) as content:
            async for part in content:
                for chunk, _ in self.chunk_bytes(part):
                    await send({'type': 'http.response.body', 'body': chunk, 'more_body': True})
        await send({'type': 'http.response.body'})
    else:
        for chunk, last in self.chunk_bytes(response.content):
            await send({'type': 'http.response.body', 'body': chunk, 'more_body': not last})

@classmethod
def chunk_bytes(cls, data):
    position = 0
    if not data:
        yield (data, True)
        return
    while position < len(data):
        yield (data[position:position + cls.chunk_size], position + cls.chunk_size >= len(data))
        position += cls.chunk_size

def adapt_method_mode(self, is_async, method, method_is_async=None, debug=False, name=None):
    if method_is_async is None:
        method_is_async = iscoroutinefunction(method)
    if debug and (not name):
        name = name or 'method %s()' % method.__qualname__
    if is_async:
        if not method_is_async:
            if debug:
                logger.debug('Synchronous handler adapted for %s.', name)
            return sync_to_async(method, thread_sensitive=True)
    elif method_is_async:
        if debug:
            logger.debug('Asynchronous handler adapted for %s.', name)
        return async_to_sync(method)
    return method

def _get_response(self, request):
    response = None
    callback, callback_args, callback_kwargs = self.resolve_request(request)
    for middleware_method in self._view_middleware:
        response = middleware_method(request, callback, callback_args, callback_kwargs)
        if response:
            break
    if response is None:
        wrapped_callback = self.make_view_atomic(callback)
        if iscoroutinefunction(wrapped_callback):
            wrapped_callback = async_to_sync(wrapped_callback)
        try:
            response = wrapped_callback(request, *callback_args, **callback_kwargs)
        except Exception as e:
            response = self.process_exception_by_middleware(e, request)
            if response is None:
                raise
    self.check_response(response, callback)
    if hasattr(response, 'render') and callable(response.render):
        for middleware_method in self._template_response_middleware:
            response = middleware_method(request, response)
            self.check_response(response, middleware_method, name='%s.process_template_response' % (middleware_method.__self__.__class__.__name__,))
        try:
            response = response.render()
        except Exception as e:
            response = self.process_exception_by_middleware(e, request)
            if response is None:
                raise
    return response

async def _get_response_async(self, request):
    response = None
    callback, callback_args, callback_kwargs = self.resolve_request(request)
    for middleware_method in self._view_middleware:
        response = await middleware_method(request, callback, callback_args, callback_kwargs)
        if response:
            break
    if response is None:
        wrapped_callback = self.make_view_atomic(callback)
        if not iscoroutinefunction(wrapped_callback):
            wrapped_callback = sync_to_async(wrapped_callback, thread_sensitive=True)
        try:
            response = await wrapped_callback(request, *callback_args, **callback_kwargs)
        except Exception as e:
            response = await sync_to_async(self.process_exception_by_middleware, thread_sensitive=True)(e, request)
            if response is None:
                raise
    self.check_response(response, callback)
    if hasattr(response, 'render') and callable(response.render):
        for middleware_method in self._template_response_middleware:
            response = await middleware_method(request, response)
            self.check_response(response, middleware_method, name='%s.process_template_response' % (middleware_method.__self__.__class__.__name__,))
        try:
            if iscoroutinefunction(response.render):
                response = await response.render()
            else:
                response = await sync_to_async(response.render, thread_sensitive=True)()
        except Exception as e:
            response = await sync_to_async(self.process_exception_by_middleware, thread_sensitive=True)(e, request)
            if response is None:
                raise
    if asyncio.iscoroutine(response):
        raise RuntimeError('Response is still a coroutine.')
    return response

def resolve_request(self, request):
    if hasattr(request, 'urlconf'):
        urlconf = request.urlconf
        set_urlconf(urlconf)
        resolver = get_resolver(urlconf)
    else:
        resolver = get_resolver()
    resolver_match = resolver.resolve(request.path_info)
    request.resolver_match = resolver_match
    return resolver_match

def check_response(self, response, callback, name=None):
    if not (response is None or asyncio.iscoroutine(response)):
        return
    if not name:
        if isinstance(callback, types.FunctionType):
            name = 'The view %s.%s' % (callback.__module__, callback.__name__)
        else:
            name = 'The view %s.%s.__call__' % (callback.__module__, callback.__class__.__name__)
    if response is None:
        raise ValueError("%s didn't return an HttpResponse object. It returned None instead." % name)
    elif asyncio.iscoroutine(response):
        raise ValueError("%s didn't return an HttpResponse object. It returned an unawaited coroutine instead. You may need to add an 'await' into your view." % name)

def process_exception_by_middleware(self, exception, request):
    for middleware_method in self._exception_middleware:
        response = middleware_method(request, exception)
        if response:
            return response
    return None

def convert_exception_to_response(get_response):
    if iscoroutinefunction(get_response):

        @wraps(get_response)
        async def inner(request):
            try:
                response = await get_response(request)
            except Exception as exc:
                response = await sync_to_async(response_for_exception, thread_sensitive=False)(request, exc)
            return response
        return inner
    else:

        @wraps(get_response)
        def inner(request):
            try:
                response = get_response(request)
            except Exception as exc:
                response = response_for_exception(request, exc)
            return response
        return inner

def get_path_info(environ):
    path_info = get_bytes_from_wsgi(environ, 'PATH_INFO', '/')
    return repercent_broken_unicode(path_info).decode()

def get_script_name(environ):
    if settings.FORCE_SCRIPT_NAME is not None:
        return settings.FORCE_SCRIPT_NAME
    script_url = get_bytes_from_wsgi(environ, 'SCRIPT_URL', '') or get_bytes_from_wsgi(environ, 'REDIRECT_URL', '')
    if script_url:
        if b'//' in script_url:
            script_url = _slashes_re.sub(b'/', script_url)
        path_info = get_bytes_from_wsgi(environ, 'PATH_INFO', '')
        script_name = script_url.removesuffix(path_info)
    else:
        script_name = get_bytes_from_wsgi(environ, 'SCRIPT_NAME', '')
    return script_name.decode()

def get_bytes_from_wsgi(environ, key, default):
    value = environ.get(key, default)
    return value.encode('iso-8859-1')

def get_str_from_wsgi(environ, key, default):
    value = get_bytes_from_wsgi(environ, key, default)
    return value.decode(errors='replace')

def as_string(self, unixfrom=False, linesep='\n'):
    fp = StringIO()
    g = generator.Generator(fp, mangle_from_=False)
    g.flatten(self, unixfrom=unixfrom, linesep=linesep)
    return fp.getvalue()

def as_bytes(self, unixfrom=False, linesep='\n'):
    fp = BytesIO()
    g = generator.BytesGenerator(fp, mangle_from_=False)
    g.flatten(self, unixfrom=unixfrom, linesep=linesep)
    return fp.getvalue()

@deprecate_posargs(RemovedInDjango70Warning, ['bcc', 'connection', 'attachments', 'headers', 'cc', 'reply_to'])
def __init__(self, subject='', body='', from_email=None, to=None, *, bcc=None, connection=None, attachments=None, headers=None, cc=None, reply_to=None):
    if to:
        if isinstance(to, str):
            raise TypeError('"to" argument must be a list or tuple')
        self.to = list(to)
    else:
        self.to = []
    if cc:
        if isinstance(cc, str):
            raise TypeError('"cc" argument must be a list or tuple')
        self.cc = list(cc)
    else:
        self.cc = []
    if bcc:
        if isinstance(bcc, str):
            raise TypeError('"bcc" argument must be a list or tuple')
        self.bcc = list(bcc)
    else:
        self.bcc = []
    if reply_to:
        if isinstance(reply_to, str):
            raise TypeError('"reply_to" argument must be a list or tuple')
        self.reply_to = list(reply_to)
    else:
        self.reply_to = []
    self.from_email = from_email or settings.DEFAULT_FROM_EMAIL
    self.subject = subject
    self.body = body or ''
    self.attachments = []
    if attachments:
        for attachment in attachments:
            if isinstance(attachment, email.message.MIMEPart):
                self.attach(attachment)
            elif isinstance(attachment, MIMEBase):
                self.attach(attachment)
            else:
                self.attach(*attachment)
    self.extra_headers = headers or {}
    if connection is not None:
        warn_about_external_use(CONNECTION_ARG_WARNING, RemovedInDjango70Warning, skip_frames=1)
    self._connection = connection

def attach(self, filename=None, content=None, mimetype=None):
    if isinstance(filename, email.message.MIMEPart):
        if content is not None or mimetype is not None:
            raise ValueError('content and mimetype must not be given when a MIMEPart instance is provided.')
        self.attachments.append(filename)
    elif isinstance(filename, MIMEBase):
        warnings.warn('MIMEBase attachments are deprecated. Use an email.message.MIMEPart instead.', RemovedInDjango70Warning)
        if content is not None or mimetype is not None:
            raise ValueError('content and mimetype must not be given when a MIMEBase instance is provided.')
        self.attachments.append(filename)
    elif content is None:
        raise ValueError('content must be provided.')
    else:
        mimetype = mimetype or mimetypes.guess_type(filename)[0] or DEFAULT_ATTACHMENT_MIME_TYPE
        basetype, subtype = mimetype.split('/', 1)
        if basetype == 'text':
            if isinstance(content, bytes):
                try:
                    content = content.decode()
                except UnicodeDecodeError:
                    mimetype = DEFAULT_ATTACHMENT_MIME_TYPE
        self.attachments.append(EmailAttachment(filename, content, mimetype))

def _set_list_header_if_not_empty(self, msg, header, values):
    try:
        msg[header] = self.extra_headers[header]
    except KeyError:
        if values:
            msg[header] = ', '.join((str(v) for v in values))

def _idna_encode_address_header_domains(self, msg):
    if not getattr(msg.policy, 'utf8', False):
        for field, value in msg.items():
            if isinstance(value, AddressHeader) and any((not addr.domain.isascii() for addr in value.addresses)):
                msg.replace_header(field, [Address(display_name=addr.display_name, username=addr.username, domain=punycode(addr.domain)) for addr in value.addresses])

