def _get_filename(self):
    if self._fname is None:
        timestamp = datetime.datetime.now().strftime('%Y%m%d-%H%M%S')
        fname = '%s-%s.log' % (timestamp, abs(id(self)))
        self._fname = os.path.join(self.file_path, fname)
    return self._fname

def open(self):
    if self.connection:
        return False
    if self._partial_connection is not None:
        self._close_connection(self._partial_connection)
        self._partial_connection = None
    connection_params = {'local_hostname': DNS_NAME.get_fqdn()}
    if self.timeout is not None:
        connection_params['timeout'] = self.timeout
    if self.use_ssl:
        connection_params['context'] = self.ssl_context
    try:
        self._partial_connection = self.connection_class(self.host, self.port, **connection_params)
        if not self.use_ssl and self.use_tls:
            self._partial_connection.starttls(context=self.ssl_context)
        if self.username and self.password:
            self._partial_connection.login(self.username, self.password)
        self.connection = self._partial_connection
        self._partial_connection = None
        return True
    except OSError:
        if not self.fail_silently:
            raise

def send_messages(self, email_messages):
    if not email_messages:
        return 0
    with self._lock:
        new_conn_created = self.open()
        if not self.connection or new_conn_created is None:
            return 0
        num_sent = 0
        try:
            for message in email_messages:
                sent = self._send(message)
                if sent:
                    num_sent += 1
        finally:
            if new_conn_created:
                self.close()
    return num_sent

def prep_address(self, address, force_ascii=True):
    address = force_str(address)
    parsed = AddressHeader.value_parser(address)
    defects = set((str(defect) for defect in parsed.all_defects))
    defects.discard('addr-spec local part with no domain')
    if not force_ascii:
        defects.discard('local-part contains non-ASCII characters)')
    if defects:
        raise ValueError(f"Invalid address {address!r}: {'; '.join(defects)}")
    mailboxes = parsed.all_mailboxes
    if len(mailboxes) != 1:
        raise ValueError(f'Invalid address {address!r}: must be a single address')
    mailbox = mailboxes[0]
    if force_ascii and mailbox.domain and (not mailbox.domain.isascii()):
        domain = punycode(mailbox.domain)
        return str(Address(username=mailbox.local_part, domain=domain))
    else:
        return mailbox.addr_spec

def handle_default_options(options):
    if options.settings:
        os.environ['DJANGO_SETTINGS_MODULE'] = options.settings
    if options.pythonpath:
        sys.path.insert(0, options.pythonpath)

def add_base_argument(self, parser, *args, **kwargs):
    for arg in args:
        if arg in self.suppressed_base_arguments:
            kwargs['help'] = argparse.SUPPRESS
            break
    parser.add_argument(*args, **kwargs)

def run_from_argv(self, argv):
    self._called_from_command_line = True
    parser = self.create_parser(argv[0], argv[1])
    options = parser.parse_args(argv[2:])
    cmd_options = vars(options)
    args = cmd_options.pop('args', ())
    handle_default_options(options)
    try:
        self.execute(*args, **cmd_options)
    except CommandError as e:
        if options.traceback:
            raise
        if isinstance(e, SystemCheckError):
            self.stderr.write(str(e), lambda x: x)
        else:
            self.stderr.write('%s: %s' % (e.__class__.__name__, e))
        sys.exit(e.returncode)
    finally:
        try:
            connections.close_all()
        except ImproperlyConfigured:
            pass

def check(self, app_configs=None, tags=None, display_num_errors=False, include_deployment_checks=False, fail_level=checks.ERROR, databases=None):
    all_issues = checks.run_checks(app_configs=app_configs, tags=tags, include_deployment_checks=include_deployment_checks, databases=databases)
    header, body, footer = ('', '', '')
    visible_issue_count = 0
    if all_issues:
        debugs = [e for e in all_issues if e.level < checks.INFO and (not e.is_silenced())]
        infos = [e for e in all_issues if checks.INFO <= e.level < checks.WARNING and (not e.is_silenced())]
        warnings = [e for e in all_issues if checks.WARNING <= e.level < checks.ERROR and (not e.is_silenced())]
        errors = [e for e in all_issues if checks.ERROR <= e.level < checks.CRITICAL and (not e.is_silenced())]
        criticals = [e for e in all_issues if checks.CRITICAL <= e.level and (not e.is_silenced())]
        sorted_issues = [(criticals, 'CRITICALS'), (errors, 'ERRORS'), (warnings, 'WARNINGS'), (infos, 'INFOS'), (debugs, 'DEBUGS')]
        for issues, group_name in sorted_issues:
            if issues:
                visible_issue_count += len(issues)
                formatted = (self.style.ERROR(str(e)) if e.is_serious() else self.style.WARNING(str(e)) for e in issues)
                formatted = '\n'.join(sorted(formatted))
                body += '\n%s:\n%s\n' % (group_name, formatted)
    if visible_issue_count:
        header = 'System check identified some issues:\n'
    if display_num_errors:
        if visible_issue_count:
            footer += '\n'
        footer += 'System check identified %s (%s silenced).' % ('no issues' if visible_issue_count == 0 else '1 issue' if visible_issue_count == 1 else '%s issues' % visible_issue_count, len(all_issues) - visible_issue_count)
    if any((e.is_serious(fail_level) and (not e.is_silenced()) for e in all_issues)):
        msg = self.style.ERROR('SystemCheckError: %s' % header) + body + footer
        raise SystemCheckError(msg)
    else:
        msg = header + body + footer
    if msg:
        if visible_issue_count:
            self.stderr.write(msg, lambda x: x)
        else:
            self.stdout.write(msg)

def supports_color():

    def vt_codes_enabled_in_windows_registry():
        """
        Check the Windows Registry to see if VT code handling has been enabled
        by default, see https://superuser.com/a/1300251/447564.
        """
        try:
            import winreg
        except ImportError:
            return False
        else:
            try:
                reg_key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, 'Console')
                reg_key_value, _ = winreg.QueryValueEx(reg_key, 'VirtualTerminalLevel')
            except FileNotFoundError:
                return False
            else:
                return reg_key_value == 1
    is_a_tty = hasattr(sys.stdout, 'isatty') and sys.stdout.isatty()
    return is_a_tty and (sys.platform != 'win32' or (HAS_COLORAMA and getattr(colorama, 'fixed_windows_console', False)) or 'ANSICON' in os.environ or ('WT_SESSION' in os.environ) or (os.environ.get('TERM_PROGRAM') == 'vscode') or vt_codes_enabled_in_windows_registry())

