def parse_apps_and_model_labels(labels):
    apps = set()
    models = set()
    for label in labels:
        if '.' in label:
            try:
                model = installed_apps.get_model(label)
            except LookupError:
                raise CommandError('Unknown model: %s' % label)
            models.add(model)
        else:
            try:
                app_config = installed_apps.get_app_config(label)
            except LookupError as e:
                raise CommandError(str(e))
            apps.add(app_config)
    return (models, apps)

def get_command_line_option(argv, option):
    parser = CommandParser(add_help=False, allow_abbrev=False)
    parser.add_argument(option, dest='value')
    try:
        options, _ = parser.parse_known_args(argv[2:])
    except CommandError:
        return None
    else:
        return options.value

def normalize_path_patterns(patterns):
    patterns = [os.path.normcase(p) for p in patterns]
    dir_suffixes = {'%s*' % path_sep for path_sep in {'/', os.sep}}
    norm_patterns = []
    for pattern in patterns:
        for dir_suffix in dir_suffixes:
            if pattern.endswith(dir_suffix):
                norm_patterns.append(pattern.removesuffix(dir_suffix))
                break
        else:
            norm_patterns.append(pattern)
    return norm_patterns

def is_ignored_path(path, ignore_patterns):
    path = Path(path)

    def ignore(pattern):
        return fnmatch.fnmatchcase(path.name, pattern) or fnmatch.fnmatchcase(str(path), pattern)
    return any((ignore(pattern) for pattern in normalize_path_patterns(ignore_patterns)))

def find_commands(management_dir):
    command_dir = os.path.join(management_dir, 'commands')
    return [name for _, name, is_pkg in pkgutil.iter_modules([command_dir]) if not is_pkg and (not name.startswith('_'))]

def load_command_class(app_name, name):
    module = import_module('%s.management.commands.%s' % (app_name, name))
    return module.Command()

@functools.cache
def get_commands():
    commands = {name: 'django.core' for name in find_commands(__path__[0])}
    if not settings.configured:
        return commands
    for app_config in reversed(apps.get_app_configs()):
        path = os.path.join(app_config.path, 'management')
        commands.update({name: app_config.name for name in find_commands(path)})
    return commands

def call_command(command_name, *args, **options):
    if isinstance(command_name, BaseCommand):
        command = command_name
        command_name = command.__class__.__module__.split('.')[-1]
    else:
        try:
            app_name = get_commands()[command_name]
        except KeyError:
            raise CommandError('Unknown command: %r' % command_name)
        if isinstance(app_name, BaseCommand):
            command = app_name
        else:
            command = load_command_class(app_name, command_name)
    parser = command.create_parser('', command_name)
    opt_mapping = {min(s_opt.option_strings).lstrip('-').replace('-', '_'): s_opt.dest for s_opt in parser._actions if s_opt.option_strings}
    arg_options = {opt_mapping.get(key, key): value for key, value in options.items()}
    parse_args = []
    for arg in args:
        if isinstance(arg, (list, tuple)):
            parse_args += map(str, arg)
        else:
            parse_args.append(str(arg))

    def get_actions(parser):
        for opt in parser._actions:
            if isinstance(opt, _SubParsersAction):
                for sub_opt in opt.choices.values():
                    yield from get_actions(sub_opt)
            else:
                yield opt
    parser_actions = list(get_actions(parser))
    mutually_exclusive_required_options = {opt for group in parser._mutually_exclusive_groups for opt in group._group_actions if group.required}
    for opt in parser_actions:
        if opt.dest in options and (opt.required or opt in mutually_exclusive_required_options):
            opt_dest_count = sum((v == opt.dest for v in opt_mapping.values()))
            if opt_dest_count > 1:
                raise TypeError(f'Cannot pass the dest {opt.dest!r} that matches multiple arguments via **options.')
            parse_args.append(min(opt.option_strings))
            if isinstance(opt, (_AppendConstAction, _CountAction, _StoreConstAction)):
                continue
            value = arg_options[opt.dest]
            if isinstance(value, (list, tuple)):
                parse_args += map(str, value)
            else:
                parse_args.append(str(value))
    defaults = parser.parse_args(args=parse_args)
    defaults = dict(defaults._get_kwargs(), **arg_options)
    stealth_options = set(command.base_stealth_options + command.stealth_options)
    dest_parameters = {action.dest for action in parser_actions}
    valid_options = (dest_parameters | stealth_options).union(opt_mapping)
    unknown_options = set(options) - valid_options
    if unknown_options:
        raise TypeError('Unknown option(s) for %s command: %s. Valid options are: %s.' % (command_name, ', '.join(sorted(unknown_options)), ', '.join(sorted(valid_options))))
    args = defaults.pop('args', ())
    if 'skip_checks' not in options:
        defaults['skip_checks'] = True
    return command.execute(*args, **defaults)

def main_help_text(self, commands_only=False):
    if commands_only:
        usage = sorted(get_commands())
    else:
        usage = ['', "Type '%s help <subcommand>' for help on a specific subcommand." % self.prog_name, '', 'Available subcommands:']
        commands_dict = defaultdict(lambda: [])
        for name, app in get_commands().items():
            if app == 'django.core':
                app = 'django'
            else:
                app = app.rpartition('.')[-1]
            commands_dict[app].append(name)
        for app in sorted(commands_dict):
            usage.append('')
            usage.append(self.style.NOTICE('[%s]' % app))
            for name in sorted(commands_dict[app]):
                usage.append('    %s' % name)
        if self.settings_exception is not None:
            usage.append(self.style.NOTICE('Note that only Django core commands are listed as settings are not properly configured (error: %s).' % self.settings_exception))
    return '\n'.join(usage)

def fetch_command(self, subcommand):
    commands = get_commands()
    try:
        app_name = commands[subcommand]
    except KeyError:
        if os.environ.get('DJANGO_SETTINGS_MODULE') and self.settings_exception:
            sys.stderr.write(self.style.NOTICE(str(self.settings_exception) + '\n'))
        elif not settings.configured:
            sys.stderr.write(self.style.NOTICE('No Django settings specified.\n'))
        possible_matches = get_close_matches(subcommand, commands)
        sys.stderr.write('Unknown command: %r' % subcommand)
        if possible_matches:
            sys.stderr.write('. Did you mean %s?' % possible_matches[0])
        sys.stderr.write("\nType '%s help' for usage.\n" % self.prog_name)
        sys.exit(1)
    if isinstance(app_name, BaseCommand):
        klass = app_name
    else:
        klass = load_command_class(app_name, subcommand)
    if self.settings_exception and klass.requires_settings:
        sys.stderr.write(self.style.NOTICE(str(self.settings_exception) + '\n'))
        sys.exit(1)
    return klass

def autocomplete(self):
    if 'DJANGO_AUTO_COMPLETE' not in os.environ:
        return
    cwords = os.environ['COMP_WORDS'].split()[1:]
    cword = int(os.environ['COMP_CWORD'])
    try:
        curr = cwords[cword - 1]
    except IndexError:
        curr = ''
    subcommands = [*get_commands(), 'help']
    options = [('--help', False)]
    if cword == 1:
        print(' '.join(sorted(filter(lambda x: x.startswith(curr), subcommands))))
    elif cwords[0] in subcommands and cwords[0] != 'help':
        subcommand_cls = self.fetch_command(cwords[0])
        if cwords[0] in ('dumpdata', 'sqlmigrate', 'sqlsequencereset', 'test'):
            try:
                app_configs = apps.get_app_configs()
                options.extend(((app_config.label, 0) for app_config in app_configs))
            except ImportError:
                pass
        parser = subcommand_cls.create_parser('', cwords[0])
        options.extend(((min(s_opt.option_strings), s_opt.nargs != 0) for s_opt in parser._actions if s_opt.option_strings))
        prev_opts = {x.split('=')[0] for x in cwords[1:cword - 1]}
        options = (opt for opt in options if opt[0] not in prev_opts)
        options = sorted(((k, v) for k, v in options if k.startswith(curr)))
        for opt_label, require_arg in options:
            if require_arg:
                opt_label += '='
            print(opt_label)
    sys.exit(0)

def execute(self):
    try:
        subcommand = self.argv[1]
    except IndexError:
        subcommand = 'help'
    parser = CommandParser(prog=self.prog_name, usage='%(prog)s subcommand [options] [args]', add_help=False, allow_abbrev=False)
    parser.add_argument('--settings')
    parser.add_argument('--pythonpath')
    parser.add_argument('args', nargs='*')
    try:
        options, args = parser.parse_known_args(self.argv[2:])
        handle_default_options(options)
    except CommandError:
        pass
    try:
        settings.INSTALLED_APPS
    except ImproperlyConfigured as exc:
        self.settings_exception = exc
    if settings.configured:
        if subcommand == 'runserver' and '--noreload' not in self.argv:
            try:
                autoreload.check_errors(django.setup)()
            except Exception:
                apps.all_models = defaultdict(dict)
                apps.app_configs = {}
                apps.apps_ready = apps.models_ready = apps.ready = True
                _parser = self.fetch_command('runserver').create_parser('django', 'runserver')
                _options, _args = _parser.parse_known_args(self.argv[2:])
                for _arg in _args:
                    self.argv.remove(_arg)
        else:
            django.setup()
    self.autocomplete()
    if subcommand == 'help':
        if '--commands' in args:
            sys.stdout.write(self.main_help_text(commands_only=True) + '\n')
        elif not options.args:
            sys.stdout.write(self.main_help_text() + '\n')
        else:
            self.fetch_command(options.args[0]).print_help(self.prog_name, options.args[0])
    elif subcommand == 'version' or self.argv[1:] == ['--version']:
        sys.stdout.write(django.get_version() + '\n')
    elif self.argv[1:] in (['--help'], ['-h']):
        sys.stdout.write(self.main_help_text() + '\n')
    else:
        self.fetch_command(subcommand).run_from_argv(self.argv)

def compile_messages(self, locations):
    with concurrent.futures.ThreadPoolExecutor() as executor:
        futures = []
        for i, (dirpath, f) in enumerate(locations):
            po_path = Path(dirpath) / f
            mo_path = po_path.with_suffix('.mo')
            try:
                if mo_path.stat().st_mtime >= po_path.stat().st_mtime:
                    if self.verbosity > 0:
                        self.stdout.write('File “%s” is already compiled and up to date.' % po_path)
                    continue
            except FileNotFoundError:
                pass
            if self.verbosity > 0:
                self.stdout.write('processing file %s in %s' % (f, dirpath))
            if has_bom(po_path):
                self.stderr.write('The %s file has a BOM (Byte Order Mark). Django only supports .po files encoded in UTF-8 and without any BOM.' % po_path)
                self.has_errors = True
                continue
            if i == 0 and (not is_dir_writable(mo_path.parent)):
                self.stderr.write('The po files under %s are in a seemingly not writable location. mo files will not be updated/created.' % dirpath)
                self.has_errors = True
                return
            args = [self.program, *self.program_options, '-o', mo_path, po_path]
            futures.append(executor.submit(popen_wrapper, args))
        for future in concurrent.futures.as_completed(futures):
            output, errors, status = future.result()
            if status:
                if self.verbosity > 0:
                    if errors:
                        self.stderr.write('Execution of %s failed: %s' % (self.program, errors))
                    else:
                        self.stderr.write('Execution of %s failed' % self.program)
                self.has_errors = True

def get_objects(count_only=False):
    if use_natural_foreign_keys:
        models = serializers.sort_dependencies(app_list.items(), allow_cycles=True)
    else:
        models = []
        for app_config, model_list in app_list.items():
            if model_list is None:
                models.extend(app_config.get_models())
            else:
                models.extend(model_list)
    for model in models:
        if model in excluded_models:
            continue
        if model._meta.proxy and model._meta.proxy_for_model not in models:
            warnings.warn("%s is a proxy model and won't be serialized." % model._meta.label, category=ProxyModelWarning)
        if not model._meta.proxy and router.allow_migrate_model(using, model):
            if use_base_manager:
                objects = model._base_manager
            else:
                objects = model._default_manager
            queryset = objects.using(using).order_by(model._meta.pk.name)
            if primary_keys:
                queryset = queryset.filter(pk__in=primary_keys)
            if count_only:
                yield queryset.order_by().count()
            else:
                chunk_size = 2000 if queryset._prefetch_related_lookups else None
                yield from queryset.iterator(chunk_size=chunk_size)

def get_field_type(self, connection, table_name, row):
    field_params = {}
    field_notes = []
    try:
        field_type = connection.introspection.get_field_type(row.type_code, row)
    except KeyError:
        field_type = 'TextField'
        field_notes.append('This field type is a guess.')
    if field_type == 'CharField' and row.display_size:
        if (size := int(row.display_size)) and size > 0:
            field_params['max_length'] = size
    if field_type in {'CharField', 'TextField'} and row.collation:
        field_params['db_collation'] = row.collation
    if field_type == 'DecimalField' and (row.precision is not None or row.scale is not None):
        field_params['max_digits'] = row.precision
        field_params['decimal_places'] = row.scale
    return (field_type, field_params, field_notes)

def get_meta(self, table_name, constraints, column_to_field_name, is_view, is_partition, comment):
    unique_together = []
    has_unsupported_constraint = False
    for params in constraints.values():
        if params['unique']:
            columns = params['columns']
            if None in columns:
                has_unsupported_constraint = True
            columns = [x for x in columns if x is not None and x in column_to_field_name]
            if len(columns) > 1 and (not params['primary_key']):
                unique_together.append(str(tuple((column_to_field_name[c] for c in columns))))
    if is_view:
        managed_comment = "  # Created from a view. Don't remove."
    elif is_partition:
        managed_comment = "  # Created from a partition. Don't remove."
    else:
        managed_comment = ''
    meta = ['']
    if has_unsupported_constraint:
        meta.append('    # A unique constraint could not be introspected.')
    meta += ['    class Meta:', '        managed = False%s' % managed_comment, '        db_table = %r' % table_name]
    if unique_together:
        tup = '(' + ', '.join(unique_together) + ',)'
        meta += ['        unique_together = %s' % tup]
    if comment:
        meta += [f'        db_table_comment = {comment!r}']
    return meta

@classmethod
def get_url_patterns(cls, prefixes=None):
    url_patterns = []
    urlconf = import_module(settings.ROOT_URLCONF)
    for view_func, regex, namespace, name in extract_views_from_urlpatterns(urlconf.urlpatterns):
        route = simplify_regex(regex)
        if hasattr(view_func, 'view_class'):
            view_func = view_func.view_class
        view = '{}.{}'.format(view_func.__module__, getattr(view_func, '__name__', view_func.__class__.__name__))
        namespace_list = namespace or []
        name = ':'.join(namespace_list + [name]) if name else ''
        pattern = URLPattern(route, view, name)
        if not prefixes or any((pattern.route.startswith(prefix) for prefix in prefixes)):
            url_patterns.append(pattern)
    return url_patterns

def reset_sequences(self, connection, models):
    sequence_sql = connection.ops.sequence_reset_sql(no_style(), models)
    if sequence_sql:
        if self.verbosity >= 2:
            self.stdout.write('Resetting sequences')
        with connection.cursor() as cursor:
            for line in sequence_sql:
                cursor.execute(line)

def load_label(self, fixture_label):
    show_progress = self.verbosity >= 3
    for fixture_file, fixture_dir, fixture_name in self.find_fixtures(fixture_label):
        _, ser_fmt, cmp_fmt = self.parse_name(os.path.basename(fixture_file))
        open_method, mode = self.compression_formats[cmp_fmt]
        fixture = open_method(fixture_file, mode)
        self.fixture_count += 1
        objects_in_fixture = 0
        loaded_objects_in_fixture = 0
        if self.verbosity >= 2:
            self.stdout.write("Installing %s fixture '%s' from %s." % (ser_fmt, fixture_name, humanize(fixture_dir)))
        try:
            objects = serializers.deserialize(ser_fmt, fixture, using=self.using, ignorenonexistent=self.ignore, handle_forward_references=True)
            for obj in objects:
                objects_in_fixture += 1
                if self.save_obj(obj):
                    loaded_objects_in_fixture += 1
                    if show_progress:
                        self.stdout.write('\rProcessed %i object(s).' % loaded_objects_in_fixture, ending='')
        except Exception as e:
            if not isinstance(e, CommandError):
                e.args = ("Problem installing fixture '%s': %s" % (fixture_file, e),)
            raise
        finally:
            fixture.close()
        if objects_in_fixture and show_progress:
            self.stdout.write()
        self.loaded_object_count += loaded_objects_in_fixture
        self.fixture_object_count += objects_in_fixture
        if objects_in_fixture == 0:
            warnings.warn("No fixture data found for '%s'. (File format may be invalid.)" % fixture_name, RuntimeWarning)

@cached_property
def fixture_dirs(self):
    dirs = []
    fixture_dirs = settings.FIXTURE_DIRS
    if len(fixture_dirs) != len(set(fixture_dirs)):
        raise ImproperlyConfigured('settings.FIXTURE_DIRS contains duplicates.')
    for app_config in apps.get_app_configs():
        app_label = app_config.label
        app_dir = os.path.join(app_config.path, 'fixtures')
        if app_dir in [str(d) for d in fixture_dirs]:
            raise ImproperlyConfigured("'%s' is a default fixture directory for the '%s' app and cannot be listed in settings.FIXTURE_DIRS." % (app_dir, app_label))
        if self.app_label and app_label != self.app_label:
            continue
        if os.path.isdir(app_dir):
            dirs.append(app_dir)
    dirs.extend(fixture_dirs)
    dirs.append('')
    return [os.path.realpath(d) for d in dirs]

def normalize_eols(raw_contents):
    lines_list = raw_contents.splitlines()
    if lines_list and lines_list[-1]:
        lines_list.append('')
    return '\n'.join(lines_list)

def write_pot_file(potfile, msgs):
    pot_lines = msgs.splitlines()
    if os.path.exists(potfile):
        lines = dropwhile(len, pot_lines)
    else:
        lines = []
        found, header_read = (False, False)
        for line in pot_lines:
            if not found and (not header_read):
                if 'charset=CHARSET' in line:
                    found = True
                    line = line.replace('charset=CHARSET', 'charset=UTF-8')
            if not line and (not found):
                header_read = True
            lines.append(line)
    msgs = '\n'.join(lines)
    with open(potfile, 'a', encoding='utf-8', newline='\n') as fp:
        fp.write(msgs)

def cleanup(self):
    if self.is_templatized:
        if os.path.exists(self.work_path):
            os.unlink(self.work_path)

def find_files(self, root):
    all_files = []
    ignored_roots = []
    if self.settings_available:
        ignored_roots = [os.path.normpath(p) for p in (settings.MEDIA_ROOT, settings.STATIC_ROOT) if p]
    for dirpath, dirnames, filenames in os.walk(root, topdown=True, followlinks=self.symlinks):
        for dirname in dirnames[:]:
            if is_ignored_path(os.path.normpath(os.path.join(dirpath, dirname)), self.ignore_patterns) or os.path.join(os.path.abspath(dirpath), dirname) in ignored_roots:
                dirnames.remove(dirname)
                if self.verbosity > 1:
                    self.stdout.write('ignoring directory %s' % dirname)
            elif dirname == 'locale':
                dirnames.remove(dirname)
                locale_dir = os.path.join(os.path.abspath(dirpath), dirname)
                if locale_dir in self.locale_paths:
                    self.locale_paths.remove(locale_dir)
                self.locale_paths.insert(0, locale_dir)
        for filename in filenames:
            file_path = os.path.normpath(os.path.join(dirpath, filename))
            file_ext = os.path.splitext(filename)[1]
            if file_ext not in self.extensions or is_ignored_path(file_path, self.ignore_patterns):
                if self.verbosity > 1:
                    self.stdout.write('ignoring file %s in %s' % (filename, dirpath))
            else:
                locale_dir = None
                for path in self.locale_paths:
                    if os.path.abspath(dirpath).startswith(os.path.dirname(path)):
                        locale_dir = path
                        break
                locale_dir = locale_dir or self.default_locale_path or NO_LOCALE_DIR
                all_files.append(self.translatable_file_class(dirpath, filename, locale_dir))
    return sorted(all_files)

def process_locale_dir(self, locale_dir, files):
    build_files = []
    for translatable in files:
        if self.verbosity > 1:
            self.stdout.write('processing file %s in %s' % (translatable.file, translatable.dirpath))
        if self.domain not in ('djangojs', 'django'):
            continue
        build_file = self.build_file_class(self, self.domain, translatable)
        try:
            build_file.preprocess()
        except UnicodeDecodeError as e:
            self.stdout.write('UnicodeDecodeError: skipped file %s in %s (reason: %s)' % (translatable.file, translatable.dirpath, e))
            continue
        except BaseException:
            for build_file in build_files:
                build_file.cleanup()
            raise
        build_files.append(build_file)
    if self.domain == 'djangojs':
        args = ['xgettext', '-d', self.domain, '--language=JavaScript', '--keyword=gettext_noop', '--keyword=gettext_lazy', '--keyword=ngettext_lazy:1,2', '--keyword=pgettext:1c,2', '--keyword=npgettext:1c,2,3', '--output=-']
    elif self.domain == 'django':
        args = ['xgettext', '-d', self.domain, '--language=Python', '--keyword=gettext_noop', '--keyword=gettext_lazy', '--keyword=ngettext_lazy:1,2', '--keyword=pgettext:1c,2', '--keyword=npgettext:1c,2,3', '--keyword=pgettext_lazy:1c,2', '--keyword=npgettext_lazy:1c,2,3', '--output=-']
    else:
        return
    input_files = [bf.work_path for bf in build_files]
    with NamedTemporaryFile(mode='w+') as input_files_list:
        input_files_list.write('\n'.join(input_files))
        input_files_list.flush()
        args.extend(['--files-from', input_files_list.name])
        args.extend(self.xgettext_options)
        msgs, errors, status = popen_wrapper(args)
    if errors:
        if status != STATUS_OK:
            for build_file in build_files:
                build_file.cleanup()
            raise CommandError('errors happened while running xgettext on %s\n%s' % ('\n'.join(input_files), errors))
        elif self.verbosity > 0:
            self.stdout.write(errors)
    if msgs:
        if locale_dir is NO_LOCALE_DIR:
            for build_file in build_files:
                build_file.cleanup()
            file_path = os.path.normpath(build_files[0].path)
            raise CommandError("Unable to find a locale path to store translations for file %s. Make sure the 'locale' directory exists in an app or LOCALE_PATHS setting is set." % file_path)
        for build_file in build_files:
            msgs = build_file.postprocess_messages(msgs)
        potfile = os.path.join(locale_dir, '%s.pot' % self.domain)
        write_pot_file(potfile, msgs)
    for build_file in build_files:
        build_file.cleanup()

def write_po_file(self, potfile, locale):
    basedir = os.path.join(os.path.dirname(potfile), locale, 'LC_MESSAGES')
    os.makedirs(basedir, exist_ok=True)
    pofile = os.path.join(basedir, '%s.po' % self.domain)
    if os.path.exists(pofile):
        args = ['msgmerge', *self.msgmerge_options, pofile, potfile]
        _, errors, status = popen_wrapper(args)
        if errors:
            if status != STATUS_OK:
                raise CommandError('errors happened while running msgmerge\n%s' % errors)
            elif self.verbosity > 0:
                self.stdout.write(errors)
        msgs = Path(pofile).read_text(encoding='utf-8')
    else:
        with open(potfile, encoding='utf-8') as fp:
            msgs = fp.read()
        if not self.invoked_for_django:
            msgs = self.copy_plural_forms(msgs, locale)
    msgs = normalize_eols(msgs)
    msgs = msgs.replace('#. #-#-#-#-#  %s.pot (PACKAGE VERSION)  #-#-#-#-#\n' % self.domain, '')
    with open(pofile, 'w', encoding='utf-8') as fp:
        fp.write(msgs)
    if self.no_obsolete:
        args = ['msgattrib', *self.msgattrib_options, '-o', pofile, pofile]
        msgs, errors, status = popen_wrapper(args)
        if errors:
            if status != STATUS_OK:
                raise CommandError('errors happened while running msgattrib\n%s' % errors)
            elif self.verbosity > 0:
                self.stdout.write(errors)

def copy_plural_forms(self, msgs, locale):
    django_dir = os.path.normpath(os.path.join(os.path.dirname(django.__file__)))
    if self.domain == 'djangojs':
        domains = ('djangojs', 'django')
    else:
        domains = ('django',)
    for domain in domains:
        django_po = os.path.join(django_dir, 'conf', 'locale', locale, 'LC_MESSAGES', '%s.po' % domain)
        if os.path.exists(django_po):
            with open(django_po, encoding='utf-8') as fp:
                m = plural_forms_re.search(fp.read())
            if m:
                plural_form_line = m['value']
                if self.verbosity > 1:
                    self.stdout.write('copying plural forms: %s' % plural_form_line)
                lines = []
                found = False
                for line in msgs.splitlines():
                    if not found and (not line or plural_forms_re.search(line)):
                        line = plural_form_line
                        found = True
                    lines.append(line)
                msgs = '\n'.join(lines)
                break
    return msgs

def write_migration_files(self, changes, update_previous_migration_paths=None):
    directory_created = {}
    for app_label, app_migrations in changes.items():
        if self.verbosity >= 1:
            self.log(self.style.MIGRATE_HEADING("Migrations for '%s':" % app_label))
        for migration in app_migrations:
            writer = MigrationWriter(migration, self.include_header)
            if self.verbosity >= 1:
                migration_string = self.get_relative_path(writer.path)
                self.log('  %s\n' % self.style.MIGRATE_LABEL(migration_string))
                for operation in migration.operations:
                    self.log('    %s' % operation.formatted_description())
                if self.scriptable:
                    self.stdout.write(migration_string)
            if not self.dry_run:
                migrations_directory = os.path.dirname(writer.path)
                if not directory_created.get(app_label):
                    os.makedirs(migrations_directory, exist_ok=True)
                    init_path = os.path.join(migrations_directory, '__init__.py')
                    if not os.path.isfile(init_path):
                        open(init_path, 'w').close()
                    directory_created[app_label] = True
                migration_string = writer.as_string()
                with open(writer.path, 'w', encoding='utf-8') as fh:
                    fh.write(migration_string)
                    self.written_files.append(writer.path)
                if update_previous_migration_paths:
                    prev_path = update_previous_migration_paths[app_label]
                    rel_prev_path = self.get_relative_path(prev_path)
                    if writer.needs_manual_porting:
                        migration_path = self.get_relative_path(writer.path)
                        self.log(self.style.WARNING(f'Updated migration {migration_path} requires manual porting.\nPrevious migration {rel_prev_path} was kept and must be deleted after porting functions manually.'))
                    else:
                        os.remove(prev_path)
                        self.log(f'Deleted {rel_prev_path}')
            elif self.verbosity == 3:
                self.log(self.style.MIGRATE_HEADING("Full migrations file '%s':" % writer.filename))
                self.log(writer.as_string())
    run_formatters(self.written_files, stderr=self.stderr)

def sync_apps(self, connection, app_labels):
    with connection.cursor() as cursor:
        tables = connection.introspection.table_names(cursor)
    all_models = [(app_config.label, router.get_migratable_models(app_config, connection.alias, include_auto_created=False)) for app_config in apps.get_app_configs() if app_config.models_module is not None and app_config.label in app_labels]

    def model_installed(model):
        opts = model._meta
        converter = connection.introspection.identifier_converter
        max_name_length = connection.ops.max_name_length()
        return not (converter(truncate_name(opts.db_table, max_name_length)) in tables or (opts.auto_created and converter(opts.auto_created._meta.db_table) in tables))
    manifest = {app_name: list(filter(model_installed, model_list)) for app_name, model_list in all_models}
    if self.verbosity >= 1:
        self.stdout.write('  Creating tables...')
    with connection.schema_editor() as editor:
        for app_name, model_list in manifest.items():
            for model in model_list:
                if not model._meta.can_migrate(connection):
                    continue
                if self.verbosity >= 3:
                    self.stdout.write('    Processing %s.%s model' % (app_name, model._meta.object_name))
                if self.verbosity >= 1:
                    self.stdout.write('    Creating table %s' % model._meta.db_table)
                editor.create_model(model)
        if self.verbosity >= 1:
            self.stdout.write('    Running deferred SQL...')

@staticmethod
def describe_operation(operation, backwards):
    prefix = ''
    is_error = False
    if hasattr(operation, 'code'):
        code = operation.reverse_code if backwards else operation.code
        action = code.__doc__ or '' if code else None
    elif hasattr(operation, 'sql'):
        action = operation.reverse_sql if backwards else operation.sql
    else:
        action = ''
        if backwards:
            prefix = 'Undo '
    if action is not None:
        action = str(action).replace('\n', '')
    elif backwards:
        action = 'IRREVERSIBLE'
        is_error = True
    if action:
        action = ' -> ' + action
    truncated = Truncator(action)
    return (prefix + operation.describe() + truncated.chars(40), is_error)

def show_plan(self, connection, app_names=None):
    loader = MigrationLoader(connection)
    graph = loader.graph
    if app_names:
        self._validate_app_names(loader, app_names)
        targets = [key for key in graph.leaf_nodes() if key[0] in app_names]
    else:
        targets = graph.leaf_nodes()
    plan = []
    seen = set()
    for target in targets:
        for migration in graph.forwards_plan(target):
            if migration not in seen:
                node = graph.node_map[migration]
                plan.append(node)
                seen.add(migration)

    def print_deps(node):
        out = []
        for parent in sorted(node.parents):
            out.append('%s.%s' % parent.key)
        if out:
            return ' ... (%s)' % ', '.join(out)
        return ''
    for node in plan:
        deps = ''
        if self.verbosity >= 2:
            deps = print_deps(node)
        if node.key in loader.applied_migrations:
            self.stdout.write('[X]  %s.%s%s' % (node.key[0], node.key[1], deps))
        else:
            self.stdout.write('[ ]  %s.%s%s' % (node.key[0], node.key[1], deps))
    if not plan:
        self.stdout.write('(no migrations)', self.style.ERROR)

def serialize(self, queryset, *, stream=None, fields=None, use_natural_foreign_keys=False, use_natural_primary_keys=False, progress_output=None, object_count=0, **options):
    self.options = options
    self.stream = stream if stream is not None else self.stream_class()
    self.selected_fields = fields
    self.use_natural_foreign_keys = use_natural_foreign_keys
    self.use_natural_primary_keys = use_natural_primary_keys
    progress_bar = self.progress_class(progress_output, object_count)
    self.start_serialization()
    self.first = True
    for count, obj in enumerate(queryset, start=1):
        self.start_object(obj)
        concrete_model = obj._meta.concrete_model
        if self.use_natural_primary_keys:
            pk = concrete_model._meta.pk
            pk_parent = pk if pk.remote_field and pk.remote_field.parent_link else None
        else:
            pk_parent = None
        for field in concrete_model._meta.local_fields:
            if field.serialize or field is pk_parent:
                if field.remote_field is None:
                    if self.selected_fields is None or field.attname in self.selected_fields:
                        self.handle_field(obj, field)
                elif self.selected_fields is None or field.attname[:-3] in self.selected_fields:
                    self.handle_fk_field(obj, field)
        for field in concrete_model._meta.local_many_to_many:
            if field.serialize:
                if self.selected_fields is None or field.attname in self.selected_fields:
                    self.handle_m2m_field(obj, field)
        self.end_object(obj)
        progress_bar.update(count)
        self.first = self.first and False
    self.end_serialization()
    return self.getvalue()

def getvalue(self):
    if callable(getattr(self.stream, 'getvalue', None)):
        return self.stream.getvalue()

def _resolve_natural_key(self, obj):
    try:
        return obj.natural_key()
    except AttributeError:
        return None

def _resolve_fk_natural_key(self, obj, field):
    if not self._model_supports_natural_key(field.remote_field.model):
        return None
    related = getattr(obj, field.name, None)
    try:
        return related.natural_key()
    except AttributeError:
        return None

def _model_supports_natural_key(self, model):
    try:
        return callable(model.natural_key)
    except AttributeError:
        return False

def handle_field(self, obj, field):
    self.indent_level += 1
    self.indent(self.indent_level)
    self.xml.startElement('field', {'name': field.name, 'type': field.get_internal_type()})
    if getattr(obj, field.name) is not None:
        value = field.value_to_string(obj)
        if field.get_internal_type() == 'JSONField':
            value = json.dumps(value, cls=field.encoder)
        try:
            self.xml.characters(value)
        except UnserializableContentError:
            raise ValueError('%s.%s (pk:%s) contains unserializable characters' % (obj.__class__.__name__, field.name, obj.pk))
    else:
        self.xml.addQuickElement('None')
    self.xml.endElement('field')
    self.indent_level -= 1

def _handle_object(self, node):
    Model = self._get_model_from_node(node, 'model')
    data = {}
    if node.hasAttribute('pk'):
        data[Model._meta.pk.attname] = Model._meta.pk.to_python(node.getAttribute('pk'))
    m2m_data = {}
    deferred_fields = {}
    field_names = {f.name for f in Model._meta.get_fields()}
    for field_node in getChildrenByTagName(node, 'field'):
        field_name = field_node.getAttribute('name')
        if not field_name:
            raise base.DeserializationError("<field> node is missing the 'name' attribute")
        if self.ignore and field_name not in field_names:
            continue
        field = Model._meta.get_field(field_name)
        if field.remote_field and isinstance(field.remote_field, models.ManyToManyRel):
            value = self._handle_m2m_field_node(field_node, field)
            if value == base.DEFER_FIELD:
                deferred_fields[field] = [[None if getChildrenByTagName(nat_node, 'None') else getInnerText(nat_node).strip() for nat_node in getChildrenByTagName(obj_node, 'natural')] for obj_node in getChildrenByTagName(field_node, 'object')]
            else:
                m2m_data[field.name] = value
        elif field.remote_field and isinstance(field.remote_field, models.ManyToOneRel):
            value = self._handle_fk_field_node(field_node, field)
            if value == base.DEFER_FIELD:
                deferred_fields[field] = [None if getChildrenByTagName(k, 'None') else getInnerText(k).strip() for k in getChildrenByTagName(field_node, 'natural')]
            else:
                data[field.attname] = value
        else:
            if getChildrenByTagName(field_node, 'None'):
                value = None
            else:
                value = field.to_python(getInnerText(field_node).strip())
                if field.get_internal_type() == 'JSONField':
                    value = json.loads(value, cls=field.decoder)
            data[field.name] = value
    obj = base.build_instance(Model, data, self.db)
    return base.DeserializedObject(obj, m2m_data, deferred_fields)

def _handle_fk_field_node(self, node, field):
    natural_keys = getChildrenByTagName(node, 'natural')
    if getChildrenByTagName(node, 'None') and (not natural_keys):
        return None
    else:
        model = field.remote_field.model
        if hasattr(model._default_manager, 'get_by_natural_key'):
            if natural_keys:
                field_value = []
                for k in natural_keys:
                    if getChildrenByTagName(k, 'None'):
                        field_value.append(None)
                    else:
                        field_value.append(getInnerText(k).strip())
                try:
                    obj = model._default_manager.db_manager(self.db).get_by_natural_key(*field_value)
                except ObjectDoesNotExist:
                    if self.handle_forward_references:
                        return base.DEFER_FIELD
                    else:
                        raise
                obj_pk = getattr(obj, field.remote_field.field_name)
                if field.remote_field.model._meta.pk.remote_field:
                    obj_pk = obj_pk.pk
            else:
                field_value = getInnerText(node).strip()
                obj_pk = model._meta.get_field(field.remote_field.field_name).to_python(field_value)
            return obj_pk
        else:
            field_value = getInnerText(node).strip()
            return model._meta.get_field(field.remote_field.field_name).to_python(field_value)

def _handle_m2m_field_node(self, node, field):
    model = field.remote_field.model
    default_manager = model._default_manager
    if hasattr(default_manager, 'get_by_natural_key'):

        def m2m_convert(n):
            keys = getChildrenByTagName(n, 'natural')
            if keys:
                field_value = []
                for k in keys:
                    if getChildrenByTagName(k, 'None'):
                        field_value.append(None)
                    else:
                        field_value.append(getInnerText(k).strip())
                obj_pk = default_manager.db_manager(self.db).get_by_natural_key(*field_value).pk
            else:
                obj_pk = model._meta.pk.to_python(n.getAttribute('pk'))
            return obj_pk
    else:

        def m2m_convert(n):
            return model._meta.pk.to_python(n.getAttribute('pk'))
    values = []
    try:
        for c in getChildrenByTagName(node, 'object'):
            values.append(m2m_convert(c))
    except SuspiciousOperation:
        raise
    except Exception as e:
        if isinstance(e, ObjectDoesNotExist) and self.handle_forward_references:
            return base.DEFER_FIELD
        else:
            raise base.M2MDeserializationError(e, c)
    else:
        return values

