        if db_params['check']:
            definition += ' ' + self.sql_check_constraint % db_params
        col_type_suffix = field.db_type_suffix(connection=self.connection)
        if col_type_suffix:
            definition += ' %s' % col_type_suffix
        params.extend(extra_params)
        if field.remote_field and field.db_constraint:
            to_table = field.remote_field.model._meta.db_table
            to_column = field.remote_field.model._meta.get_field(field.remote_field.field_name).column
            if self.sql_create_inline_fk:
                definition += ' ' + self.sql_create_inline_fk % {'to_table': self.quote_name(to_table), 'to_column': self.quote_name(to_column), 'on_delete_db': self._create_on_delete_sql(model, field)}
            elif self.connection.features.supports_foreign_keys:
                self.deferred_sql.append(self._create_fk_sql(model, field, '_fk_%(to_table)s_%(to_column)s'))
        column_sqls.append('%s %s' % (self.quote_name(field.column), definition))
        if field.get_internal_type() in ('AutoField', 'BigAutoField', 'SmallAutoField'):
            autoinc_sql = self.connection.ops.autoinc_sql(model._meta.db_table, field.column)
            if autoinc_sql:
                self.deferred_sql.extend(autoinc_sql)
    constraint_sqls = []
    if params:
        for constraint in model._meta.constraints:
            self.deferred_sql.append(constraint.create_sql(model, self))
    else:
        constraint_sqls.extend((constraint.constraint_sql(model, self) for constraint in model._meta.constraints))
    pk = model._meta.pk
    if isinstance(pk, CompositePrimaryKey):
        constraint_sqls.append(self._pk_constraint_sql(pk.columns))
    sql = self.sql_create_table % {'table': self.quote_name(model._meta.db_table), 'definition': ', '.join((str(statement) for statement in (*column_sqls, *constraint_sqls) if statement))}
    if model._meta.db_tablespace:
        tablespace_sql = self.connection.ops.tablespace_sql(model._meta.db_tablespace)
        if tablespace_sql:
            sql += ' ' + tablespace_sql
    return (sql, params)

def column_sql(self, model, field, include_default=False):
    field_db_params = field.db_parameters(connection=self.connection)
    column_db_type = field_db_params['type']
    if column_db_type is None:
        return (None, None)
    params = []
    return (' '.join(self._iter_column_sql(column_db_type, params, model, field, field_db_params, include_default)), params)

def _column_generated_sql(self, field):
    expression_sql, params = field.generated_sql(self.connection)
    persistency_sql = self._column_generated_persistency_sql(field)
    if self.connection.features.requires_literal_defaults:
        expression_sql = expression_sql % tuple((self.quote_value(p) for p in params))
        params = ()
    return (f'GENERATED ALWAYS AS ({expression_sql}) {persistency_sql}', params)

def create_model(self, model):
    sql, params = self.table_sql(model)
    self.execute(sql, params or None)
    if self.connection.features.supports_comments:
        if model._meta.db_table_comment:
            self.alter_db_table_comment(model, None, model._meta.db_table_comment)
        if not self.connection.features.supports_comments_inline:
            for field in model._meta.local_fields:
                if field.db_comment:
                    field_db_params = field.db_parameters(connection=self.connection)
                    field_type = field_db_params['type']
                    self.execute(*self._alter_column_comment_sql(model, field, field_type, field.db_comment))
    self.deferred_sql.extend(self._model_indexes_sql(model))
    for field in model._meta.local_many_to_many:
        if field.remote_field.through._meta.auto_created:
            self.create_model(field.remote_field.through)

def delete_model(self, model):
    for field in model._meta.local_many_to_many:
        if field.remote_field.through._meta.auto_created:
            self.delete_model(field.remote_field.through)
    self.execute(self.sql_delete_table % {'table': self.quote_name(model._meta.db_table)})
    for sql in list(self.deferred_sql):
        if isinstance(sql, Statement) and sql.references_table(model._meta.db_table):
            self.deferred_sql.remove(sql)

def add_index(self, model, index):
    if index.contains_expressions and (not self.connection.features.supports_expression_indexes):
        return None
    self.execute(index.create_sql(model, self), params=None)

def remove_index(self, model, index):
    if index.contains_expressions and (not self.connection.features.supports_expression_indexes):
        return None
    self.execute(index.remove_sql(model, self))

def add_constraint(self, model, constraint):
    sql = constraint.create_sql(model, self)
    if sql:
        self.execute(sql, params=None)

def remove_constraint(self, model, constraint):
    sql = constraint.remove_sql(model, self)
    if sql:
        self.execute(sql)

def alter_unique_together(self, model, old_unique_together, new_unique_together):
    olds = {tuple(fields) for fields in old_unique_together}
    news = {tuple(fields) for fields in new_unique_together}
    for fields in olds.difference(news):
        self._delete_composed_index(model, fields, {'unique': True, 'primary_key': False}, self.sql_delete_unique)
    for field_names in news.difference(olds):
        fields = [model._meta.get_field(field) for field in field_names]
        self.execute(self._create_unique_sql(model, fields))

def alter_index_together(self, model, old_index_together, new_index_together):
    olds = {tuple(fields) for fields in old_index_together}
    news = {tuple(fields) for fields in new_index_together}
    for fields in olds.difference(news):
        self._delete_composed_index(model, fields, {'index': True, 'unique': False}, self.sql_delete_index)
    for field_names in news.difference(olds):
        fields = [model._meta.get_field(field) for field in field_names]
        self.execute(self._create_index_sql(model, fields=fields, suffix='_idx'))

def alter_db_table(self, model, old_db_table, new_db_table):
    if old_db_table == new_db_table or (self.connection.features.ignores_table_name_case and old_db_table.lower() == new_db_table.lower()):
        return
    self.execute(self.sql_rename_table % {'old_table': self.quote_name(old_db_table), 'new_table': self.quote_name(new_db_table)})
    if self.collect_sql:
        existing_table = self.collected_table_renames.pop(old_db_table, old_db_table)
        self.collected_table_renames[new_db_table] = existing_table
    for sql in self.deferred_sql:
        if isinstance(sql, Statement):
            sql.rename_table_references(old_db_table, new_db_table)

def add_field(self, model, field):
    if field.many_to_many and field.remote_field.through._meta.auto_created:
        return self.create_model(field.remote_field.through)
    definition, params = self.column_sql(model, field, include_default=True)
    if definition is None:
        return
    if (col_type_suffix := field.db_type_suffix(connection=self.connection)):
        definition += f' {col_type_suffix}'
    db_params = field.db_parameters(connection=self.connection)
    if db_params['check']:
        definition += ' ' + self.sql_check_constraint % db_params
    if field.remote_field and self.connection.features.supports_foreign_keys and field.db_constraint:
        constraint_suffix = '_fk_%(to_table)s_%(to_column)s'
        if self.sql_create_column_inline_fk:
            to_table = field.remote_field.model._meta.db_table
            to_column = field.remote_field.model._meta.get_field(field.remote_field.field_name).column
            namespace, _ = split_identifier(model._meta.db_table)
            definition += ' ' + self.sql_create_column_inline_fk % {'name': self._fk_constraint_name(model, field, constraint_suffix), 'namespace': '%s.' % self.quote_name(namespace) if namespace else '', 'column': self.quote_name(field.column), 'to_table': self.quote_name(to_table), 'to_column': self.quote_name(to_column), 'deferrable': self.connection.ops.deferrable_sql(), 'on_delete_db': self._create_on_delete_sql(model, field)}
        else:
            self.deferred_sql.append(self._create_fk_sql(model, field, constraint_suffix))
    sql = self.sql_create_column % {'table': self.quote_name(model._meta.db_table), 'column': self.quote_name(field.column), 'definition': definition}
    self.execute(sql, params or None)
    if not field.has_db_default() and (not self.skip_default_on_alter(field)) and (self.effective_default(field) is not None):
        changes_sql, params = self._alter_column_default_sql(model, None, field, drop=True)
        sql = self.sql_alter_column % {'table': self.quote_name(model._meta.db_table), 'changes': changes_sql}
        self.execute(sql, params)
    if field.db_comment and self.connection.features.supports_comments and (not self.connection.features.supports_comments_inline):
        field_type = db_params['type']
        self.execute(*self._alter_column_comment_sql(model, field, field_type, field.db_comment))
    self.deferred_sql.extend(self._field_indexes_sql(model, field))
    if self.connection.features.connection_persists_old_columns:
        self.connection.close()

def remove_field(self, model, field):
    if field.many_to_many and field.remote_field.through._meta.auto_created:
        return self.delete_model(field.remote_field.through)
    if field.db_parameters(connection=self.connection)['type'] is None:
        return
    if field.remote_field:
        fk_names = self._constraint_names(model, [field.column], foreign_key=True)
        for fk_name in fk_names:
            self.execute(self._delete_fk_sql(model, fk_name))
    sql = self.sql_delete_column % {'table': self.quote_name(model._meta.db_table), 'column': self.quote_name(field.column)}
    self.execute(sql)
    if self.connection.features.connection_persists_old_columns:
        self.connection.close()
    for sql in list(self.deferred_sql):
        if isinstance(sql, Statement) and sql.references_column(model._meta.db_table, field.column):
            self.deferred_sql.remove(sql)

def alter_field(self, model, old_field, new_field, strict=False):
    if not self._field_should_be_altered(old_field, new_field):
        return
    old_db_params = old_field.db_parameters(connection=self.connection)
    old_type = old_db_params['type']
    new_db_params = new_field.db_parameters(connection=self.connection)
    new_type = new_db_params['type']
    modifying_generated_field = False
    if old_type is None and old_field.remote_field is None or (new_type is None and new_field.remote_field is None):
        raise ValueError('Cannot alter field %s into %s - they do not properly define db_type (are you using a badly-written custom field?)' % (old_field, new_field))
    elif old_type is None and new_type is None and (old_field.remote_field.through and new_field.remote_field.through and old_field.remote_field.through._meta.auto_created and new_field.remote_field.through._meta.auto_created):
        return self._alter_many_to_many(model, old_field, new_field, strict)
    elif old_type is None and new_type is None and (old_field.remote_field.through and new_field.remote_field.through and (not old_field.remote_field.through._meta.auto_created) and (not new_field.remote_field.through._meta.auto_created)):
        return
    elif old_type is None or new_type is None:
        raise ValueError('Cannot alter field %s into %s - they are not compatible types (you cannot alter to or from M2M fields, or add or remove through= on M2M fields)' % (old_field, new_field))
    elif old_field.generated != new_field.generated or (new_field.generated and old_field.db_persist != new_field.db_persist):
        modifying_generated_field = True
    elif new_field.generated:
        try:
            old_field_sql = old_field.generated_sql(self.connection)
        except FieldError:
            modifying_generated_field = True
        else:
            new_field_sql = new_field.generated_sql(self.connection)
            modifying_generated_field = old_field_sql != new_field_sql
            db_features = self.connection.features
            if not modifying_generated_field and old_type != new_type and (not db_features.supports_alter_generated_column_data_type):
                modifying_generated_field = True
    if modifying_generated_field:
        raise ValueError(f'Modifying GeneratedFields is not supported - the field {new_field} must be removed and re-added with the new definition.')
    self._alter_field(model, old_field, new_field, old_type, new_type, old_db_params, new_db_params, strict)

def _alter_column_null_sql(self, model, old_field, new_field):
    if self.connection.features.interprets_empty_strings_as_nulls and new_field.empty_strings_allowed:
        return
    else:
        new_db_params = new_field.db_parameters(connection=self.connection)
        sql = self.sql_alter_column_null if new_field.null else self.sql_alter_column_not_null
        return (sql % {'column': self.quote_name(new_field.column), 'type': new_db_params['type']}, [])

def _alter_column_default_sql(self, model, old_field, new_field, drop=False):
    new_default = self.effective_default(new_field)
    default = self._column_default_sql(new_field)
    params = [new_default]
    if drop:
        params = []
    elif self.connection.features.requires_literal_defaults:
        default = self.prepare_default(new_default)
        params = []
    new_db_params = new_field.db_parameters(connection=self.connection)
    if drop:
        if new_field.null:
            sql = self.sql_alter_column_no_default_null
        else:
            sql = self.sql_alter_column_no_default
    else:
        sql = self.sql_alter_column_default
    return (sql % {'column': self.quote_name(new_field.column), 'type': new_db_params['type'], 'default': default}, params)

def _alter_column_database_default_sql(self, model, old_field, new_field, drop=False):
    if drop:
        sql = self.sql_alter_column_no_default
        default_sql = ''
        params = []
    else:
        sql = self.sql_alter_column_default
        default_sql, params = self.db_default_sql(new_field)
    new_db_params = new_field.db_parameters(connection=self.connection)
    return (sql % {'column': self.quote_name(new_field.column), 'type': new_db_params['type'], 'default': default_sql}, params)

def _alter_column_type_sql(self, model, old_field, new_field, new_type, old_collation, new_collation):
    other_actions = []
    if (collate_sql := self._collate_sql(new_collation, old_collation, model._meta.db_table)):
        collate_sql = f' {collate_sql}'
    else:
        collate_sql = ''
    comment_sql = ''
    if self.connection.features.supports_comments and (not new_field.many_to_many):
        if old_field.db_comment != new_field.db_comment:
            sql, params = self._alter_column_comment_sql(model, new_field, new_type, new_field.db_comment)
            if sql:
                other_actions.append((sql, params))
        if new_field.db_comment:
            comment_sql = self._comment_sql(new_field.db_comment)
    return ((self.sql_alter_column_type % {'column': self.quote_name(new_field.column), 'type': new_type, 'collation': collate_sql, 'comment': comment_sql}, []), other_actions)

def _model_indexes_sql(self, model):
    if not model._meta.managed or model._meta.proxy or model._meta.swapped:
        return []
    output = []
    for field in model._meta.local_fields:
        output.extend(self._field_indexes_sql(model, field))
    for index in model._meta.indexes:
        if not index.contains_expressions or self.connection.features.supports_expression_indexes:
            output.append(index.create_sql(model, self))
    return output

def _field_indexes_sql(self, model, field):
    output = []
    if self._field_should_be_indexed(model, field):
        output.append(self._create_index_sql(model, fields=[field]))
    return output

def _constraint_names(self, model, column_names=None, unique=None, primary_key=None, index=None, foreign_key=None, check=None, type_=None, exclude=None):
    if column_names is not None:
        column_names = [self.connection.introspection.identifier_converter(truncate_name(name, self.connection.ops.max_name_length())) if self.connection.features.truncates_names else self.connection.introspection.identifier_converter(name) for name in column_names]
    table_name = model._meta.db_table
    if self.collect_sql:
        table_name = self.collected_table_renames.get(table_name, table_name)
    with self.connection.cursor() as cursor:
        constraints = self.connection.introspection.get_constraints(cursor, table_name)
    result = []
    for name, infodict in constraints.items():
        if column_names is None or column_names == infodict['columns']:
            if unique is not None and infodict['unique'] != unique:
                continue
            if primary_key is not None and infodict['primary_key'] != primary_key:
                continue
            if index is not None and infodict['index'] != index:
                continue
            if check is not None and infodict['check'] != check:
                continue
            if foreign_key is not None and (not infodict['foreign_key']):
                continue
            if type_ is not None and infodict['type'] != type_:
                continue
            if not exclude or name not in exclude:
                result.append(name)
    return result

def check_constraints(self, table_names=None):
    with self.cursor() as cursor:
        if table_names is None:
            table_names = self.introspection.table_names(cursor)
        for table_name in table_names:
            primary_key_column_name = self.introspection.get_primary_key_column(cursor, table_name)
            if not primary_key_column_name:
                continue
            relations = self.introspection.get_relations(cursor, table_name)
            for column_name, (referenced_column_name, referenced_table_name, _) in relations.items():
                cursor.execute('\n                        SELECT REFERRING.`%s`, REFERRING.`%s` FROM `%s` as REFERRING\n                        LEFT JOIN `%s` as REFERRED\n                        ON (REFERRING.`%s` = REFERRED.`%s`)\n                        WHERE REFERRING.`%s` IS NOT NULL AND REFERRED.`%s` IS NULL\n                        ' % (primary_key_column_name, column_name, table_name, referenced_table_name, column_name, referenced_column_name, column_name, referenced_column_name))
                for bad_row in cursor.fetchall():
                    raise IntegrityError("The row in table '%s' with primary key '%s' has an invalid foreign key: %s.%s contains a value '%s' that does not have a corresponding value in %s.%s." % (table_name, bad_row[0], table_name, column_name, bad_row[1], referenced_table_name, referenced_column_name))

