def _create_missing_fk_index(self, model, *, fields, expressions=None):
    first_field_name = None
    if fields:
        first_field_name = fields[0]
    elif expressions and self.connection.features.supports_expression_indexes and isinstance(expressions[0], F) and (LOOKUP_SEP not in expressions[0].name):
        first_field_name = expressions[0].name
    if not first_field_name:
        return
    first_field = model._meta.get_field(first_field_name)
    if first_field.get_internal_type() == 'ForeignKey':
        column = self.connection.introspection.identifier_converter(first_field.column)
        with self.connection.cursor() as cursor:
            constraint_names = [name for name, infodict in self.connection.introspection.get_constraints(cursor, model._meta.db_table).items() if infodict['index'] and infodict['columns'][0] == column]
        if len(constraint_names) == 1:
            self.execute(self._create_index_sql(model, fields=[first_field], suffix=''))

def _set_field_new_type(self, field, new_type):
    if field.has_db_default():
        default_sql, params = self.db_default_sql(field)
        default_sql %= tuple((self.quote_value(p) for p in params))
        new_type += f' DEFAULT {default_sql}'
    if field.null:
        new_type += ' NULL'
    else:
        new_type += ' NOT NULL'
    return new_type

def check_field_type(self, field, field_type):
    errors = []
    if field_type.startswith('varchar') and field.unique and (field.max_length is None or int(field.max_length) > 255):
        errors.append(checks.Warning('%s may not allow unique CharFields to have a max_length > 255.' % self.connection.display_name, obj=field, hint='See: https://docs.djangoproject.com/en/%s/ref/databases/#mysql-character-fields' % get_docs_version(), id='mysql.W003'))
    if field.db_index and field_type.lower() in self.connection._limited_data_types:
        errors.append(checks.Warning('%s does not support a database index on %s columns.' % (self.connection.display_name, field_type), hint="An index won't be created. Silence this warning if you don't care about it.", obj=field, id='fields.W162'))
    return errors

def _execute_allow_fail_statements(self, cursor, statements, parameters, verbosity, acceptable_ora_err):
    try:
        allow_quiet_fail = acceptable_ora_err is not None and len(acceptable_ora_err) > 0
        self._execute_statements(cursor, statements, parameters, verbosity, allow_quiet_fail=allow_quiet_fail)
        return True
    except DatabaseError as err:
        description = str(err)
        if acceptable_ora_err is None or acceptable_ora_err not in description:
            raise
        return False

def _test_settings_get(self, key, default=None, prefixed=None):
    settings_dict = self.connection.settings_dict
    val = settings_dict['TEST'].get(key, default)
    if val is None and prefixed:
        val = TEST_DATABASE_PREFIX + settings_dict[prefixed]
    return val

