def _create_like_index_sql(self, model, field):
    db_type = field.db_type(connection=self.connection)
    if db_type is not None and (field.db_index or field.unique):
        if '[' in db_type:
            return None
        collation_name = getattr(field, 'db_collation', None)
        if not collation_name and field.is_relation:
            collation_name = getattr(field.target_field, 'db_collation', None)
        if collation_name and (not self._is_collation_deterministic(collation_name)):
            return None
        if db_type.startswith('varchar'):
            return self._create_index_sql(model, fields=[field], suffix='_like', opclasses=['varchar_pattern_ops'])
        elif db_type.startswith('text'):
            return self._create_index_sql(model, fields=[field], suffix='_like', opclasses=['text_pattern_ops'])
    return None

def check_constraints(self, table_names=None):
    with self.cursor() as cursor:
        if table_names is None:
            violations = cursor.execute('PRAGMA foreign_key_check').fetchall()
        else:
            violations = chain.from_iterable((cursor.execute('PRAGMA foreign_key_check(%s)' % self.ops.quote_name(table_name)).fetchall() for table_name in table_names))
        for table_name, rowid, referenced_table_name, foreign_key_index in violations:
            foreign_key = cursor.execute('PRAGMA foreign_key_list(%s)' % self.ops.quote_name(table_name)).fetchall()[foreign_key_index]
            column_name, referenced_column_name = foreign_key[3:5]
            primary_key_column_name = self.introspection.get_primary_key_column(cursor, table_name)
            primary_key_value, bad_value = cursor.execute('SELECT %s, %s FROM %s WHERE rowid = %%s' % (self.ops.quote_name(primary_key_column_name), self.ops.quote_name(column_name), self.ops.quote_name(table_name)), (rowid,)).fetchone()
            raise IntegrityError("The row in table '%s' with primary key '%s' has an invalid foreign key: %s.%s contains a value '%s' that does not have a corresponding value in %s.%s." % (table_name, primary_key_value, table_name, column_name, bad_value, referenced_table_name, referenced_column_name))

def test_db_signature(self):
    test_database_name = self._get_test_db_name()
    sig = [self.connection.settings_dict['NAME']]
    if self.is_in_memory_db(test_database_name):
        sig.append(self.connection.alias)
    else:
        sig.append(test_database_name)
    return tuple(sig)

def get_field_size(name):
    m = field_size_re.search(name)
    return int(m[1]) if m else None

def get_table_description(self, cursor, table_name):
    cursor.execute('PRAGMA table_xinfo(%s)' % self.connection.ops.quote_name(table_name))
    table_info = cursor.fetchall()
    if not table_info:
