@cached_property
def convert_value(self):
    field = self.output_field
    internal_type = field.get_internal_type()
    if internal_type == 'FloatField':
        return lambda value, expression, connection: None if value is None else float(value)
    elif internal_type.endswith('IntegerField'):
        return lambda value, expression, connection: None if value is None else int(value)
    elif internal_type == 'DecimalField':
        return lambda value, expression, connection: None if value is None else Decimal(value)
    return self._convert_value_noop

def __init__(self, value, output_field=None):
    super().__init__(output_field=output_field)
    self.value = value

def clone(self):
    _, args, kwargs = self.deconstruct()
    return self.__class__(*args, **kwargs)

def deconstruct(self):
    qs_class = self._queryset_class
    if getattr(self, '_built_with_as_manager', False):
        return (True, None, '%s.%s' % (qs_class.__module__, qs_class.__name__), None, None)
    else:
        module_name = self.__module__
        name = self.__class__.__name__
        module = import_module(module_name)
        if not hasattr(module, name):
            raise ValueError("Could not find manager %s in %s.\nPlease note that you need to inherit from managers you dynamically generated with 'from_queryset()'." % (name, module_name))
        return (False, '%s.%s' % (module_name, name), None, self._constructor_args[0], self._constructor_args[1])

def normalize_together(option_together):
    try:
        if not option_together:
            return ()
        if not isinstance(option_together, (tuple, list)):
            raise TypeError
        first_element = option_together[0]
        if not isinstance(first_element, (tuple, list)):
            option_together = (option_together,)
        return tuple((tuple(ot) for ot in option_together))
    except TypeError:
        return option_together

def can_migrate(self, connection):
    if self.proxy or self.swapped or (not self.managed):
        return False
    if isinstance(connection, str):
        connection = connections[connection]
    if self.required_db_vendor:
        return self.required_db_vendor == connection.vendor
    if self.required_db_features:
        return all((getattr(connection.features, feat, False) for feat in self.required_db_features))
    return True

@cached_property
def verbose_name_raw(self):
    if isinstance(self.verbose_name, str):
        return self.verbose_name
    with override(None):
        return str(self.verbose_name)

@cached_property
def fields(self):

    def is_not_an_m2m_field(f):
        return not (f.is_relation and f.many_to_many)

    def is_not_a_generic_relation(f):
        return not (f.is_relation and f.one_to_many)

    def is_not_a_generic_foreign_key(f):
        return not (f.is_relation and f.many_to_one and (not (hasattr(f.remote_field, 'model') and f.remote_field.model)))
    return make_immutable_fields_list('fields', (f for f in self._get_fields(reverse=False) if is_not_an_m2m_field(f) and is_not_a_generic_relation(f) and is_not_a_generic_foreign_key(f)))

@cached_property
def concrete_fields(self):
    return make_immutable_fields_list('concrete_fields', (f for f in self.fields if f.concrete))

@cached_property
def local_concrete_fields(self):
    return make_immutable_fields_list('local_concrete_fields', (f for f in self.local_fields if f.concrete))

@cached_property
def many_to_many(self):
    return make_immutable_fields_list('many_to_many', (f for f in self._get_fields(reverse=False) if f.is_relation and f.many_to_many))

@cached_property
def related_objects(self):
    all_related_fields = self._get_fields(forward=False, reverse=True, include_hidden=True)
    return make_immutable_fields_list('related_objects', (obj for obj in all_related_fields if not obj.hidden or obj.field.many_to_many))

def get_field(self, field_name):
    try:
        return self._forward_fields_map[field_name]
    except KeyError:
        if not self.apps.models_ready:
            raise FieldDoesNotExist("%s has no field named '%s'. The app cache isn't ready yet, so if this is an auto-created related field, it won't be available yet." % (self.object_name, field_name))
    try:
        return self.fields_map[field_name]
    except KeyError:
        raise FieldDoesNotExist("%s has no field named '%s'" % (self.object_name, field_name))

def get_base_chain(self, model):
    if not self.parents:
        return []
    if model in self.parents:
        return [model]
    for parent in self.parents:
        res = parent._meta.get_base_chain(model)
        if res:
            res.insert(0, parent)
            return res
    return []

@cached_property
def all_parents(self):
    result = OrderedSet(self.parents)
    for parent in self.parents:
        for ancestor in parent._meta.all_parents:
            result.add(ancestor)
    return tuple(result)

def get_ancestor_link(self, ancestor):
    if ancestor in self.parents:
        return self.parents[ancestor]
    for parent in self.parents:
        parent_link = parent._meta.get_ancestor_link(ancestor)
        if parent_link:
            return self.parents[parent] or parent_link

def get_path_to_parent(self, parent):
    if self.model is parent:
        return []
    proxied_model = self.concrete_model
    path = []
    opts = self
    for int_model in self.get_base_chain(parent):
        if int_model is proxied_model:
            opts = int_model._meta
        else:
            final_field = opts.parents[int_model]
            targets = (final_field.remote_field.get_related_field(),)
            opts = int_model._meta
            path.append(PathInfo(from_opts=final_field.model._meta, to_opts=opts, target_fields=targets, join_field=final_field, m2m=False, direct=True, filtered_relation=None))
    return path

def get_fields(self, include_parents=True, include_hidden=False):
    if include_parents is False:
        include_parents = PROXY_PARENTS
    return self._get_fields(include_parents=include_parents, include_hidden=include_hidden)

def _get_fields(self, forward=True, reverse=True, include_parents=True, include_hidden=False, topmost_call=True):
    if include_parents not in (True, False, PROXY_PARENTS):
        raise TypeError('Invalid argument for include_parents: %s' % (include_parents,))
    cache_key = (forward, reverse, include_parents, include_hidden, topmost_call)
    try:
        return self._get_fields_cache[cache_key]
    except KeyError:
        pass
    fields = []
    if include_parents is not False:
        parent_fields = set()
        for parent in self.parents:
            if parent._meta.concrete_model != self.concrete_model and include_parents == PROXY_PARENTS:
                continue
            for obj in parent._meta._get_fields(forward=forward, reverse=reverse, include_parents=include_parents, include_hidden=include_hidden, topmost_call=False):
                if (not getattr(obj, 'parent_link', False) or obj.model == self.concrete_model) and obj not in parent_fields:
                    fields.append(obj)
                    parent_fields.add(obj)
    if reverse and (not self.proxy):
        all_fields = self._relation_tree
        for field in all_fields:
            if include_hidden or not field.remote_field.hidden:
                fields.append(field.remote_field)
    if forward:
        fields += self.local_fields
        fields += self.local_many_to_many
        if topmost_call:
            fields += self.private_fields
    fields = make_immutable_fields_list('get_fields()', fields)
    self._get_fields_cache[cache_key] = fields
    return fields

@cached_property
def total_unique_constraints(self):
    return [constraint for constraint in self.constraints if isinstance(constraint, UniqueConstraint) and constraint.condition is None and (not constraint.contains_expressions)]

@cached_property
def _property_names(self):
    names = set()
    seen = set()
    for klass in self.model.__mro__:
        names |= {name for name, value in klass.__dict__.items() if isinstance(value, property) and name not in seen}
        seen |= set(klass.__dict__)
    return frozenset(names)

@cached_property
def _non_pk_concrete_field_names(self):
    names = []
    all_pk_fields = set(self.pk_fields)
    for parent in self.all_parents:
        all_pk_fields.update(parent._meta.pk_fields)
    for field in self.concrete_fields:
        if field not in all_pk_fields:
            names.append(field.name)
            if field.name != field.attname:
                names.append(field.attname)
    return frozenset(names)

@cached_property
def _reverse_one_to_one_field_names(self):
    return frozenset((field.name for field in self.related_objects if field.one_to_one))

def normalize_prefetch_lookups(lookups, prefix=None):
    ret = []
    for lookup in lookups:
        if not isinstance(lookup, Prefetch):
            lookup = Prefetch(lookup)
        if prefix:
            lookup.add_prefix(prefix)
        ret.append(lookup)
    return ret

def get_prefetcher(instance, through_attr, to_attr):

    def is_to_attr_fetched(model, to_attr):
        if isinstance(getattr(model, to_attr, None), cached_property):

            def has_cached_property(instance):
                return to_attr in instance.__dict__
            return has_cached_property

        def has_to_attr_attribute(instance):
            return hasattr(instance, to_attr)
        return has_to_attr_attribute
    prefetcher = None
    is_fetched = is_to_attr_fetched(instance.__class__, to_attr)
    rel_obj_descriptor = getattr(instance.__class__, through_attr, None)
    if rel_obj_descriptor is None:
        attr_found = hasattr(instance, through_attr)
    else:
        attr_found = True
        if rel_obj_descriptor:
            if hasattr(rel_obj_descriptor, 'get_prefetch_querysets'):
                prefetcher = rel_obj_descriptor
                if through_attr == to_attr:
                    is_fetched = rel_obj_descriptor.is_cached
            else:
                rel_obj = getattr(instance, through_attr)
                if hasattr(rel_obj, 'get_prefetch_querysets'):
                    prefetcher = rel_obj
                if through_attr == to_attr:

                    def in_prefetched_cache(instance):
                        return through_attr in instance._prefetched_objects_cache
                    is_fetched = in_prefetched_cache
    return (prefetcher, rel_obj_descriptor, attr_found, is_fetched)

def prefetch_one_level(instances, prefetcher, lookup, level):
    rel_qs, rel_obj_attr, instance_attr, single, cache_name, is_descriptor = prefetcher.get_prefetch_querysets(instances, lookup.get_current_querysets(level))
    additional_lookups = [copy.copy(additional_lookup) for additional_lookup in getattr(rel_qs, '_prefetch_related_lookups', ())]
    if additional_lookups:
        rel_qs._prefetch_related_lookups = ()
    all_related_objects = list(rel_qs)
    rel_obj_cache = {}
    for rel_obj in all_related_objects:
        rel_attr_val = rel_obj_attr(rel_obj)
        rel_obj_cache.setdefault(rel_attr_val, []).append(rel_obj)
    to_attr, as_attr = lookup.get_current_to_attr(level)
    if as_attr and instances:
        model = instances[0].__class__
        try:
            model._meta.get_field(to_attr)
        except exceptions.FieldDoesNotExist:
            pass
        else:
            msg = 'to_attr={} conflicts with a field on the {} model.'
            raise ValueError(msg.format(to_attr, model.__name__))
    leaf = len(lookup.prefetch_through.split(LOOKUP_SEP)) - 1 == level
    for obj in instances:
        instance_attr_val = instance_attr(obj)
        vals = rel_obj_cache.get(instance_attr_val, [])
        if single:
            val = vals[0] if vals else None
            if as_attr:
                setattr(obj, to_attr, val)
            elif is_descriptor:
                setattr(obj, cache_name, val)
            else:
                obj._state.fields_cache[cache_name] = val
        elif as_attr:
            setattr(obj, to_attr, vals)
        else:
            manager = getattr(obj, to_attr)
            if leaf and lookup.queryset is not None:
                qs = manager._apply_rel_filters(lookup.queryset._chain())
            else:
                qs = manager.get_queryset()
            qs._result_cache = vals
            qs._prefetch_done = True
            obj._prefetched_objects_cache[cache_name] = qs
    return (all_related_objects, additional_lookups)

def iterator(self, chunk_size=None):
    if chunk_size is None:
        if self._prefetch_related_lookups:
            raise ValueError('chunk_size must be provided when using QuerySet.iterator() after prefetch_related().')
    elif chunk_size <= 0:
        raise ValueError('Chunk size must be strictly positive.')
    use_chunked_fetch = not connections[self.db].settings_dict.get('DISABLE_SERVER_SIDE_CURSORS')
    return self._iterator(use_chunked_fetch, chunk_size)

def aggregate(self, *args, **kwargs):
    if self.query.distinct_fields:
        raise NotImplementedError('aggregate() + distinct(fields) not implemented.')
    self._validate_values_are_expressions((*args, *kwargs.values()), method_name='aggregate')
    for arg in args:
        try:
            arg.default_alias
        except (AttributeError, TypeError):
            raise TypeError('Complex aggregates require an alias')
        kwargs[arg.default_alias] = arg
    return self.query.chain().get_aggregation(self.db, kwargs)

def count(self):
    if self._result_cache is not None:
        return len(self._result_cache)
    return self.query.get_count(using=self.db)

def get(self, *args, **kwargs):
    if self.query.combinator and (args or kwargs):
        raise NotSupportedError('Calling QuerySet.get(...) with filters after %s() is not supported.' % self.query.combinator)
    clone = self._chain() if self.query.combinator else self.filter(*args, **kwargs)
    if self.query.can_filter() and (not self.query.distinct_fields):
        clone = clone.order_by()
    limit = None
    if not clone.query.select_for_update or connections[clone.db].features.supports_select_for_update_with_limit:
        limit = MAX_GET_RESULTS
        clone.query.set_limits(high=limit)
    num = len(clone)
    if num == 1:
        return clone._result_cache[0]
    if not num:
        raise self.model.DoesNotExist('%s matching query does not exist.' % self.model._meta.object_name)
    raise self.model.MultipleObjectsReturned('get() returned more than one %s -- it returned %s!' % (self.model._meta.object_name, num if not limit or num < limit else 'more than %s' % (limit - 1)))

def bulk_update(self, objs, fields, batch_size=None):
    if batch_size is not None and batch_size <= 0:
        raise ValueError('Batch size must be a positive integer.')
    if not fields:
        raise ValueError('Field names must be given to bulk_update().')
    objs = tuple(objs)
    if not all((obj._is_pk_set() for obj in objs)):
        raise ValueError('All bulk_update() objects must have a primary key set.')
    opts = self.model._meta
    fields = [opts.get_field(name) for name in fields]
    if any((not f.concrete for f in fields)):
        raise ValueError('bulk_update() can only be used with concrete fields.')
    all_pk_fields = set(opts.pk_fields)
    for parent in opts.all_parents:
        all_pk_fields.update(parent._meta.pk_fields)
    if any((f in all_pk_fields for f in fields)):
        raise ValueError('bulk_update() cannot be used with primary key fields.')
    if not objs:
        return 0
    for obj in objs:
        obj._prepare_related_fields_for_save(operation_name='bulk_update', fields=fields)
    self._for_write = True
    connection = connections[self.db]
    max_batch_size = connection.ops.bulk_batch_size([opts.pk, opts.pk, *fields], objs)
    batch_size = min(batch_size, max_batch_size) if batch_size else max_batch_size
    requires_casting = connection.features.requires_casted_case_in_updates
    batches = (objs[i:i + batch_size] for i in range(0, len(objs), batch_size))
    updates = []
    for batch_objs in batches:
        update_kwargs = {}
        for field in fields:
            when_statements = []
            for obj in batch_objs:
                attr = getattr(obj, field.attname)
                if not hasattr(attr, 'resolve_expression'):
                    attr = Value(attr, output_field=field)
                when_statements.append(When(pk=obj.pk, then=attr))
            case_statement = Case(*when_statements, output_field=field)
            if requires_casting:
                case_statement = Cast(case_statement, output_field=field)
            update_kwargs[field.attname] = case_statement
        updates.append(([obj.pk for obj in batch_objs], update_kwargs))
    rows_updated = 0
    queryset = self.using(self.db)
    with transaction.atomic(using=self.db, savepoint=False):
        for pks, update_kwargs in updates:
            rows_updated += queryset.filter(pk__in=pks).update(**update_kwargs)
    return rows_updated

def get_or_create(self, defaults=None, **kwargs):
    self._for_write = True
    try:
        return (self.get(**kwargs), False)
    except self.model.DoesNotExist:
        params = self._extract_model_params(defaults, **kwargs)
        try:
            with transaction.atomic(using=self.db):
                params = dict(resolve_callables(params))
                return (self.create(**params), True)
        except IntegrityError:
            try:
                return (self.get(**kwargs), False)
            except self.model.DoesNotExist:
                pass
            raise

def update_or_create(self, defaults=None, create_defaults=None, **kwargs):
    update_defaults = defaults or {}
    if create_defaults is None:
        create_defaults = update_defaults
    self._for_write = True
    with transaction.atomic(using=self.db):
        obj, created = self.select_for_update().get_or_create(create_defaults, **kwargs)
        if created:
            return (obj, created)
        for k, v in resolve_callables(update_defaults):
            setattr(obj, k, v)
        update_fields = set(update_defaults)
        concrete_field_names = self.model._meta._non_pk_concrete_field_names
        if concrete_field_names.issuperset(update_fields):
            pk_fields = self.model._meta.pk_fields
            for field in self.model._meta.local_concrete_fields:
                if not (field in pk_fields or field.__class__.pre_save is Field.pre_save):
                    update_fields.add(field.name)
                    if field.name != field.attname:
                        update_fields.add(field.attname)
            obj.save(using=self.db, update_fields=update_fields)
        else:
            obj.save(using=self.db)
    return (obj, False)

def _extract_model_params(self, defaults, **kwargs):
    defaults = defaults or {}
    params = {k: v for k, v in kwargs.items() if LOOKUP_SEP not in k}
    params.update(defaults)
    property_names = self.model._meta._property_names
    invalid_params = []
    for param in params:
        try:
            self.model._meta.get_field(param)
        except exceptions.FieldDoesNotExist:
            if not (param in property_names and getattr(self.model, param).fset):
                invalid_params.append(param)
    if invalid_params:
        raise exceptions.FieldError("Invalid field name(s) for model %s: '%s'." % (self.model._meta.object_name, "', '".join(sorted(invalid_params))))
    return params

def _earliest(self, *fields):
    if fields:
        order_by = fields
    else:
        order_by = getattr(self.model._meta, 'get_latest_by')
        if order_by and (not isinstance(order_by, (tuple, list))):
            order_by = (order_by,)
    if order_by is None:
        raise ValueError("earliest() and latest() require either fields as positional arguments or 'get_latest_by' in the model's Meta.")
    obj = self._chain()
    obj.query.set_limits(high=1)
    obj.query.clear_ordering(force=True)
    obj.query.add_ordering(*order_by)
    return obj.get()

def latest(self, *fields):
    if self.query.is_sliced:
        raise TypeError('Cannot change a query once a slice has been taken.')
    return self.reverse()._earliest(*fields)

def first(self):
    if self.ordered or not self.query.default_ordering:
        queryset = self
    else:
        self._check_ordering_first_last_queryset_aggregation(method='first')
        queryset = self.order_by('pk')
    for obj in queryset[:1]:
        return obj

def last(self):
    if self.ordered or not self.query.default_ordering:
        queryset = self.reverse()
    else:
        self._check_ordering_first_last_queryset_aggregation(method='last')
        queryset = self.order_by('-pk')
    for obj in queryset[:1]:
        return obj

def in_bulk(self, id_list=None, *, field_name='pk'):
    if self.query.is_sliced:
        raise TypeError("Cannot use 'limit' or 'offset' with in_bulk().")
    if id_list is not None and (not id_list):
        return {}
    opts = self.model._meta
    unique_fields = [constraint.fields[0] for constraint in opts.total_unique_constraints if len(constraint.fields) == 1]
    if field_name != 'pk' and (not opts.get_field(field_name).unique) and (field_name not in unique_fields) and (self.query.distinct_fields != (field_name,)):
        raise ValueError("in_bulk()'s field_name must be a unique field but %r isn't." % field_name)
    qs = self

    def get_obj(obj):
        return obj
    if issubclass(self._iterable_class, ModelIterable):
        get_key = operator.attrgetter(field_name)
    elif issubclass(self._iterable_class, ValuesIterable):
        if field_name not in self.query.values_select:
            qs = qs.values(field_name, *self.query.values_select)

            def get_obj(obj):
                del obj[field_name]
                return obj
        get_key = operator.itemgetter(field_name)
    elif issubclass(self._iterable_class, ValuesListIterable):
        try:
            field_index = self.query.values_select.index(field_name)
        except ValueError:
            field_index = 0
            if issubclass(self._iterable_class, NamedValuesListIterable):
                kwargs = {'named': True}
            else:
                kwargs = {}
                get_obj = operator.itemgetter(slice(1, None))
            qs = qs.values_list(field_name, *self.query.values_select, **kwargs)
        get_key = operator.itemgetter(field_index)
    elif issubclass(self._iterable_class, FlatValuesListIterable):
        if self.query.values_select == (field_name,):
            get_key = get_obj
        else:
            qs = qs.values_list(field_name, *self.query.values_select)
            get_key = operator.itemgetter(0)
            get_obj = operator.itemgetter(1)
    else:
        raise TypeError(f'in_bulk() cannot be used with {self._iterable_class.__name__}.')
    if id_list is not None:
        filter_key = '{}__in'.format(field_name)
        id_list = tuple(id_list)
        batch_size = connections[self.db].ops.bulk_batch_size([opts.pk], id_list)
        if batch_size and batch_size < len(id_list):
            results = ()
            for offset in range(0, len(id_list), batch_size):
                batch = id_list[offset:offset + batch_size]
                results += tuple(qs.filter(**{filter_key: batch}))
            qs = results
        else:
            qs = qs.filter(**{filter_key: id_list})
    else:
        qs = qs._chain()
    return {get_key(obj): get_obj(obj) for obj in qs}

def exists(self):
    if self._result_cache is None:
        return self.query.has_results(using=self.db)
    return bool(self._result_cache)

def contains(self, obj):
    self._not_support_combined_queries('contains')
    if self._fields is not None:
        raise TypeError('Cannot call QuerySet.contains() after .values() or .values_list().')
    try:
        if obj._meta.concrete_model != self.model._meta.concrete_model:
            return False
    except AttributeError:
        raise TypeError("'obj' must be a model instance.")
    if not obj._is_pk_set():
        raise ValueError('QuerySet.contains() cannot be used on unsaved objects.')
    if self._result_cache is not None:
        return obj in self._result_cache
    return self.filter(pk=obj.pk).exists()

def dates(self, field_name, kind, order='ASC'):
    if kind not in ('year', 'month', 'week', 'day'):
        raise ValueError("'kind' must be one of 'year', 'month', 'week', or 'day'.")
    if order not in ('ASC', 'DESC'):
        raise ValueError("'order' must be either 'ASC' or 'DESC'.")
    return self.annotate(datefield=Trunc(field_name, kind, output_field=DateField()), plain_field=F(field_name)).values_list('datefield', flat=True).distinct().filter(plain_field__isnull=False).order_by(('-' if order == 'DESC' else '') + 'datefield')

def datetimes(self, field_name, kind, order='ASC', tzinfo=None):
    if kind not in ('year', 'month', 'week', 'day', 'hour', 'minute', 'second'):
        raise ValueError("'kind' must be one of 'year', 'month', 'week', 'day', 'hour', 'minute', or 'second'.")
    if order not in ('ASC', 'DESC'):
        raise ValueError("'order' must be either 'ASC' or 'DESC'.")
    if settings.USE_TZ:
        if tzinfo is None:
            tzinfo = timezone.get_current_timezone()
    else:
        tzinfo = None
    return self.annotate(datetimefield=Trunc(field_name, kind, output_field=DateTimeField(), tzinfo=tzinfo), plain_field=F(field_name)).values_list('datetimefield', flat=True).distinct().filter(plain_field__isnull=False).order_by(('-' if order == 'DESC' else '') + 'datetimefield')

def filter(self, *args, **kwargs):
    self._not_support_combined_queries('filter')
    return self._filter_or_exclude(False, args, kwargs)

def exclude(self, *args, **kwargs):
    self._not_support_combined_queries('exclude')
    return self._filter_or_exclude(True, args, kwargs)

def complex_filter(self, filter_obj):
    if isinstance(filter_obj, Q):
        clone = self._chain()
        clone.query.add_q(filter_obj)
        return clone
    else:
        return self._filter_or_exclude(False, args=(), kwargs=filter_obj)

def select_related(self, *fields):
    self._not_support_combined_queries('select_related')
    if self._fields is not None:
        raise TypeError('Cannot call select_related() after .values() or .values_list()')
    obj = self._chain()
    if fields == (None,):
        obj.query.select_related = False
    elif fields:
        obj.query.add_select_related(fields)
    else:
        warn_about_external_use('Calling select_related() with no arguments is deprecated. Specify the fields to fetch instead.', category=RemovedInDjango70Warning, skip_name_prefixes=('django.db.models',))
        obj.query.select_related = True
    return obj

def prefetch_related(self, *lookups):
    self._not_support_combined_queries('prefetch_related')
    clone = self._chain()
    if lookups == (None,):
        clone._prefetch_related_lookups = ()
    else:
        for lookup in lookups:
            if isinstance(lookup, Prefetch):
                lookup = lookup.prefetch_to
            lookup = lookup.split(LOOKUP_SEP, 1)[0]
            if lookup in self.query._filtered_relations:
                raise ValueError('prefetch_related() is not supported with FilteredRelation.')
        clone._prefetch_related_lookups = clone._prefetch_related_lookups + lookups
    return clone

def annotate(self, *args, **kwargs):
    self._not_support_combined_queries('annotate')
    return self._annotate(args, kwargs, select=True)

def alias(self, *args, **kwargs):
    self._not_support_combined_queries('alias')
    return self._annotate(args, kwargs, select=False)

def defer(self, *fields):
    self._not_support_combined_queries('defer')
    if self._fields is not None:
        raise TypeError('Cannot call defer() after .values() or .values_list()')
    clone = self._chain()
    if fields == (None,):
        clone.query.clear_deferred_loading()
    else:
        clone.query.add_deferred_loading(fields)
    return clone

def only(self, *fields):
    self._not_support_combined_queries('only')
    if self._fields is not None:
        raise TypeError('Cannot call only() after .values() or .values_list()')
    if fields == (None,):
        raise TypeError('Cannot pass None as an argument to only().')
    for field in fields:
        field = field.split(LOOKUP_SEP, 1)[0]
        if field in self.query._filtered_relations:
            raise ValueError('only() is not supported with FilteredRelation.')
    clone = self._chain()
    clone.query.add_immediate_loading(fields)
    return clone

@property
def ordered(self):
    if isinstance(self, EmptyQuerySet):
        return True
    if self.query.extra_order_by or self.query.order_by:
        return True
    elif self.query.default_ordering and self.query.get_meta().ordering and (not self.query.group_by):
        return True
    else:
        return False

@property
def totally_ordered(self):
    if not self.ordered:
        return False
    ordering = self.query.order_by
    if not ordering and self.query.default_ordering:
        ordering = self.query.get_meta().ordering
    if not ordering:
        return False
    opts = self.model._meta
    pk_fields = {f.attname for f in opts.pk_fields}
    ordering_fields = set()
    for part in ordering:
        field_name = None
        if isinstance(part, str):
            field_name = part.lstrip('-')
        elif isinstance(part, F):
            field_name = part.name
        elif isinstance(part, OrderBy) and isinstance(part.expression, F):
            field_name = part.expression.name
        if field_name:
            if field_name == 'pk':
                return True
            try:
                field = opts.get_field(field_name)
            except exceptions.FieldDoesNotExist:
                continue
            if field.remote_field and field_name == field.name:
                continue
            if field.attname in pk_fields and len(pk_fields) == 1:
                return True
            if field.unique and (not field.null):
                return True
            ordering_fields.add(field.attname)
    if ordering_fields.issuperset(pk_fields):
        return True
    constraint_field_names = (*opts.unique_together, *(constraint.fields for constraint in opts.total_unique_constraints))
    for field_names in constraint_field_names:
        try:
            fields = [opts.get_field(field_name) for field_name in field_names]
        except exceptions.FieldDoesNotExist:
            continue
        if any((field.null for field in fields)):
            continue
        if ordering_fields.issuperset((field.attname for field in fields)):
            return True
    return False

@property
def db(self):
    if self._for_write:
        return self._db or router.db_for_write(self.model, **self._hints)
    return self._db or router.db_for_read(self.model, **self._hints)

def _enable_cloning(self):
    self._cloning_enabled = True
    return self

def _chain(self):
    if not self._cloning_enabled:
        obj = self
    else:
        obj = self._clone()
    if obj._sticky_filter:
        obj.query.filter_is_sticky = True
        obj._sticky_filter = False
    return obj

@property
def db(self):
    return self._db or router.db_for_read(self.model, **self._hints)

def select_related_descend(field, restricted, requested, select_mask):
    if not field.remote_field:
        return False
    if getattr(field.remote_field, 'parent_link', False):
        return False
    if not restricted:
        return not field.null
    if field.name not in requested:
        return False
    if select_mask and field not in select_mask:
        raise FieldError(f'Field {field.model._meta.object_name}.{field.name} cannot be both deferred and traversed using select_related at the same time.')
    return True

def refs_expression(lookup_parts, annotations):
    for n in range(1, len(lookup_parts) + 1):
        level_n_lookup = LOOKUP_SEP.join(lookup_parts[0:n])
        if annotations.get(level_n_lookup):
            return (level_n_lookup, lookup_parts[n:])
    return (None, ())

def check_rel_lookup_compatibility(model, target_opts, field):

    def check(opts):
        return model._meta.concrete_model == opts.concrete_model or opts.concrete_model in model._meta.all_parents or model in opts.all_parents
    return check(target_opts) or (getattr(field, 'primary_key', False) and check(field.model._meta))

def _check_parent_chain(self, instance):
    opts = instance._meta
    link_field = opts.get_ancestor_link(self.field.model)
    if self.field.primary_key and self.field != link_field:
        return getattr(instance, link_field.attname)
    return None

@staticmethod
def merge_dicts(dicts):
    merged = {}
    for d in reversed(dicts):
        merged.update(d)
    return merged

def _unregister_class_lookup(cls, lookup, lookup_name=None):
    if lookup_name is None:
        lookup_name = lookup.lookup_name
    del cls.class_lookups[lookup_name]
    cls._clear_cached_class_lookups()

def _unregister_instance_lookup(self, lookup, lookup_name=None):
    if lookup_name is None:
        lookup_name = lookup.lookup_name
    del self.instance_lookups[lookup_name]

def make_model_tuple(model):
    try:
        if isinstance(model, tuple):
            model_tuple = model
        elif isinstance(model, str):
            app_label, model_name = model.split('.')
            model_tuple = (app_label, model_name.lower())
        else:
            model_tuple = (model._meta.app_label, model._meta.model_name)
        assert len(model_tuple) == 2
        return model_tuple
    except (ValueError, AssertionError):
        raise ValueError("Invalid model reference '%s'. String model references must be of the form 'app_label.ModelName'." % model)

def resolve_callables(mapping):
    for k, v in mapping.items():
        yield (k, v() if callable(v) else v)

def generate_filename(self, instance, filename):
    if callable(self.upload_to):
        filename = self.upload_to(instance, filename)
    else:
        dirname = datetime.datetime.now().strftime(str(self.upload_to))
        filename = posixpath.join(dirname, filename)
    filename = validate_file_name(filename, allow_relative_path=True)
    return self.storage.generate_filename(filename)

def update_dimension_fields(self, instance, force=False, *args, **kwargs):
    has_dimension_fields = self.width_field or self.height_field
    if not has_dimension_fields or self.attname not in instance.__dict__:
        return
    file = getattr(instance, self.attname)
    if not file and (not force):
        return
    dimension_fields_filled = not (self.width_field and (not getattr(instance, self.width_field)) or (self.height_field and (not getattr(instance, self.height_field))))
    if dimension_fields_filled and (not force):
        return
    if file:
        width = file.width
        height = file.height
    else:
        width = None
        height = None
    if self.width_field:
        setattr(instance, self.width_field, width)
    if self.height_field:
        setattr(instance, self.height_field, height)

def resolve_relation(scope_model, relation):
    if relation == RECURSIVE_RELATIONSHIP_CONSTANT:
        relation = scope_model
    if isinstance(relation, str):
        if '.' not in relation:
            relation = '%s.%s' % (scope_model._meta.app_label, relation)
    return relation

def lazy_related_operation(function, model, *related_models, **kwargs):
    models = [model] + [resolve_relation(model, rel) for rel in related_models]
    model_keys = (make_model_tuple(m) for m in models)
    apps = model._meta.apps
    return apps.lazy_model_operation(partial(function, **kwargs), *model_keys)

def get_reverse_related_filter(self, obj):
    base_q = Q.create([(rh_field.attname, getattr(obj, lh_field.attname)) for lh_field, rh_field in self.related_fields])
    descriptor_filter = self.get_extra_descriptor_filter(obj)
    if isinstance(descriptor_filter, dict):
        return base_q & Q(**descriptor_filter)
    elif descriptor_filter:
        return base_q & descriptor_filter
    return base_q

@property
def swappable_setting(self):
    if self.swappable:
        if isinstance(self.remote_field.model, str):
            to_string = self.remote_field.model
        else:
            to_string = self.remote_field.model._meta.label
        return apps.get_swappable_settings_name(to_string)
    return None

def get_limit_choices_to(self):
    if callable(self.remote_field.limit_choices_to):
        return self.remote_field.limit_choices_to()
    return self.remote_field.limit_choices_to

@property
def target_field(self):
    target_fields = self.path_infos[-1].target_fields
    if len(target_fields) > 1:
        raise exceptions.FieldError('The relation has multiple target fields, but only single target field was asked for')
    return target_fields[0]

def get_default(self):
    field_default = super().get_default()
    if isinstance(field_default, self.remote_field.model):
        return getattr(field_default, self.target_field.attname)
    return field_default

def _get_path_info(self, direct=False, filtered_relation=None):
    int_model = self.remote_field.through
    linkfield1 = int_model._meta.get_field(self.m2m_field_name())
    linkfield2 = int_model._meta.get_field(self.m2m_reverse_field_name())
    if direct:
        join1infos = linkfield1.reverse_path_infos
        if filtered_relation:
            join2infos = linkfield2.get_path_info(filtered_relation)
        else:
            join2infos = linkfield2.path_infos
    else:
        join1infos = linkfield2.reverse_path_infos
        if filtered_relation:
            join2infos = linkfield1.get_path_info(filtered_relation)
        else:
            join2infos = linkfield1.path_infos
    join1_final = join1infos[-1].to_opts
    join2_initial = join2infos[0].from_opts
    if join1_final is join2_initial:
        intermediate_infos = []
    elif issubclass(join1_final.model, join2_initial.model):
        intermediate_infos = join1_final.get_path_to_parent(join2_initial.model)
    else:
        intermediate_infos = join2_initial.get_path_from_parent(join1_final.model)
    return [*join1infos, *intermediate_infos, *join2infos]

def _get_m2m_reverse_attr(self, related, attr):
    cache_attr = '_m2m_reverse_%s_cache' % attr
    if hasattr(self, cache_attr):
        return getattr(self, cache_attr)
    found = False
    if self.remote_field.through_fields is not None:
        link_field_name = self.remote_field.through_fields[1]
    else:
        link_field_name = None
    for f in self.remote_field.through._meta.fields:
        if f.is_relation and f.remote_field.model == related.model:
            if link_field_name is None and related.related_model == related.model:
                if found:
                    setattr(self, cache_attr, getattr(f, attr))
                    break
                else:
                    found = True
            elif link_field_name is None or link_field_name == f.name:
                setattr(self, cache_attr, getattr(f, attr))
                break
    return getattr(self, cache_attr)

def create_reverse_many_to_one_manager(superclass, rel):

    class RelatedManager(superclass, AltersData):

        def __init__(self, instance):
            super().__init__()
            self.instance = instance
            self.model = rel.related_model
            self.field = rel.field
            self.core_filters = {self.field.name: instance}

        def __call__(self, *, manager):
            manager = getattr(self.model, manager)
            manager_class = create_reverse_many_to_one_manager(manager.__class__, rel)
            return manager_class(self.instance)
        do_not_call_in_templates = True

        def _check_fk_val(self):
            for field in self.field.foreign_related_fields:
                if getattr(self.instance, field.attname) is None:
                    raise ValueError(f'"{self.instance!r}" needs to have a value for field "{field.attname}" before this relationship can be used.')

        def _apply_rel_filters(self, queryset):
            """
            Filter the queryset for the instance this manager is bound to.
            """
            db = self._db or router.db_for_read(self.model, instance=self.instance)
            empty_strings_as_null = connections[db].features.interprets_empty_strings_as_nulls
            with queryset._avoid_cloning():
                queryset._add_hints(instance=self.instance)
                if self._db:
                    queryset = queryset.using(self._db)
                queryset._fetch_mode = self.instance._state.fetch_mode
                queryset._defer_next_filter = True
                queryset = queryset.filter(**self.core_filters)
            for field in self.field.foreign_related_fields:
                val = getattr(self.instance, field.attname)
                if val is None or (val == '' and empty_strings_as_null):
                    return queryset.none()
            if self.field.many_to_one:
                try:
                    target_field = self.field.target_field
                except FieldError:
                    rel_obj_id = tuple([getattr(self.instance, target_field.attname) for target_field in self.field.path_infos[-1].target_fields])
                else:
                    rel_obj_id = getattr(self.instance, target_field.attname)
                queryset._known_related_objects = {self.field: {rel_obj_id: self.instance}}
            return queryset

        def _remove_prefetched_objects(self):
            try:
                self.instance._prefetched_objects_cache.pop(self.field.remote_field.cache_name)
            except (AttributeError, KeyError):
                pass

        def get_queryset(self):
            if not self.instance._is_pk_set():
                raise ValueError(f'{self.instance.__class__.__name__!r} instance needs to have a primary key value before this relationship can be used.')
            try:
                return self.instance._prefetched_objects_cache[self.field.remote_field.cache_name]
            except (AttributeError, KeyError):
                queryset = super().get_queryset()
                return self._apply_rel_filters(queryset)

        def get_prefetch_querysets(self, instances, querysets=None):
            _cloning_disabled = False
            if querysets:
                if len(querysets) != 1:
                    raise ValueError('querysets argument of get_prefetch_querysets() should have a length of 1.')
                queryset = querysets[0]
            else:
                _cloning_disabled = True
                queryset = super().get_queryset()._disable_cloning()
            queryset._add_hints(instance=instances[0])
            queryset = queryset.using(queryset._db or self._db)
            rel_obj_attr = self.field.get_local_related_value
            instance_attr = self.field.get_foreign_related_value
            instances_dict = {instance_attr(inst): inst for inst in instances}
            queryset = _filter_prefetch_queryset(queryset, self.field.name, instances)
            if _cloning_disabled:
                queryset._enable_cloning()
            for rel_obj in queryset:
                if not self.field.is_cached(rel_obj):
                    instance = instances_dict[rel_obj_attr(rel_obj)]
                    self.field.set_cached_value(rel_obj, instance)
            cache_name = self.field.remote_field.cache_name
            return (queryset, rel_obj_attr, instance_attr, False, cache_name, False)

        def add(self, *objs, bulk=True):
            self._check_fk_val()
            self._remove_prefetched_objects()
            db = router.db_for_write(self.model, instance=self.instance)

            def check_and_update_obj(obj):
                if not isinstance(obj, self.model):
                    raise TypeError("'%s' instance expected, got %r" % (self.model._meta.object_name, obj))
                setattr(obj, self.field.name, self.instance)
            if bulk:
                pks = []
                for obj in objs:
                    check_and_update_obj(obj)
                    if obj._state.adding or obj._state.db != db:
                        raise ValueError("%r instance isn't saved. Use bulk=False or save the object first." % obj)
                    pks.append(obj.pk)
                self.model._base_manager.using(db).filter(pk__in=pks).update(**{self.field.name: self.instance})
            else:
                with transaction.atomic(using=db, savepoint=False):
                    for obj in objs:
                        check_and_update_obj(obj)
                        obj.save()
        add.alters_data = True

        async def aadd(self, *objs, bulk=True):
            return await sync_to_async(self.add)(*objs, bulk=bulk)
        aadd.alters_data = True

        def create(self, **kwargs):
            self._check_fk_val()
            self._remove_prefetched_objects()
            kwargs[self.field.name] = self.instance
            db = router.db_for_write(self.model, instance=self.instance)
            return super(RelatedManager, self.db_manager(db)).create(**kwargs)
        create.alters_data = True

        async def acreate(self, **kwargs):
            return await sync_to_async(self.create)(**kwargs)
        acreate.alters_data = True

        def get_or_create(self, **kwargs):
            self._check_fk_val()
            kwargs[self.field.name] = self.instance
            db = router.db_for_write(self.model, instance=self.instance)
            return super(RelatedManager, self.db_manager(db)).get_or_create(**kwargs)
        get_or_create.alters_data = True

        async def aget_or_create(self, **kwargs):
            return await sync_to_async(self.get_or_create)(**kwargs)
        aget_or_create.alters_data = True

        def update_or_create(self, **kwargs):
            self._check_fk_val()
            kwargs[self.field.name] = self.instance
            db = router.db_for_write(self.model, instance=self.instance)
            return super(RelatedManager, self.db_manager(db)).update_or_create(**kwargs)
        update_or_create.alters_data = True

        async def aupdate_or_create(self, **kwargs):
            return await sync_to_async(self.update_or_create)(**kwargs)
        aupdate_or_create.alters_data = True
        if rel.field.null:

            def remove(self, *objs, bulk=True):
                if not objs:
                    return
                self._check_fk_val()
                val = self.field.get_foreign_related_value(self.instance)
                old_ids = set()
                for obj in objs:
                    if not isinstance(obj, self.model):
                        raise TypeError("'%s' instance expected, got %r" % (self.model._meta.object_name, obj))
                    if self.field.get_local_related_value(obj) == val:
                        old_ids.add(obj.pk)
                    else:
                        raise self.field.remote_field.model.DoesNotExist('%r is not related to %r.' % (obj, self.instance))
                self._clear(self.filter(pk__in=old_ids), bulk)
            remove.alters_data = True

            async def aremove(self, *objs, bulk=True):
                return await sync_to_async(self.remove)(*objs, bulk=bulk)
            aremove.alters_data = True

            def clear(self, *, bulk=True):
                self._check_fk_val()
                self._clear(self, bulk)
            clear.alters_data = True

            async def aclear(self, *, bulk=True):
                return await sync_to_async(self.clear)(bulk=bulk)
            aclear.alters_data = True

            def _clear(self, queryset, bulk):
                self._remove_prefetched_objects()
                db = router.db_for_write(self.model, instance=self.instance)
                queryset = queryset.using(db)
                if bulk:
                    queryset.update(**{self.field.name: None})
                else:
                    with transaction.atomic(using=db, savepoint=False):
                        for obj in queryset:
                            setattr(obj, self.field.name, None)
                            obj.save(update_fields=[self.field.name])
            _clear.alters_data = True

        def set(self, objs, *, bulk=True, clear=False):
            self._check_fk_val()
            objs = tuple(objs)
            if self.field.null:
                db = router.db_for_write(self.model, instance=self.instance)
                with transaction.atomic(using=db, savepoint=False):
                    if clear:
                        self.clear(bulk=bulk)
                        self.add(*objs, bulk=bulk)
                    else:
                        old_objs = set(self.using(db).all())
                        new_objs = []
                        for obj in objs:
                            if obj in old_objs:
                                old_objs.remove(obj)
                            else:
                                new_objs.append(obj)
                        self.remove(*old_objs, bulk=bulk)
                        self.add(*new_objs, bulk=bulk)
            else:
                self.add(*objs, bulk=bulk)
        set.alters_data = True

        async def aset(self, objs, *, bulk=True, clear=False):
            return await sync_to_async(self.set)(objs=objs, bulk=bulk, clear=clear)
        aset.alters_data = True
    return RelatedManager

def create_forward_many_to_many_manager(superclass, rel, reverse):

    class ManyRelatedManager(superclass, AltersData):

        def __init__(self, instance=None):
            super().__init__()
            self.instance = instance
            if not reverse:
                self.model = rel.model
                self.query_field_name = rel.field.related_query_name()
                self.prefetch_cache_name = rel.field.name
                self.source_field_name = rel.field.m2m_field_name()
                self.target_field_name = rel.field.m2m_reverse_field_name()
                self.symmetrical = rel.symmetrical
            else:
                self.model = rel.related_model
                self.query_field_name = rel.field.name
                self.prefetch_cache_name = rel.field.related_query_name()
                self.source_field_name = rel.field.m2m_reverse_field_name()
                self.target_field_name = rel.field.m2m_field_name()
                self.symmetrical = False
            self.through = rel.through
            self.reverse = reverse
            self.source_field = self.through._meta.get_field(self.source_field_name)
            self.target_field = self.through._meta.get_field(self.target_field_name)
            self.core_filters = {}
            self.pk_field_names = {}
            for lh_field, rh_field in self.source_field.related_fields:
                core_filter_key = '%s__%s' % (self.query_field_name, rh_field.name)
                self.core_filters[core_filter_key] = getattr(instance, rh_field.attname)
                self.pk_field_names[lh_field.name] = rh_field.name
            self.related_val = self.source_field.get_foreign_related_value(instance)
            if None in self.related_val:
                raise ValueError('"%r" needs to have a value for field "%s" before this many-to-many relationship can be used.' % (instance, self.pk_field_names[self.source_field_name]))
            if not instance._is_pk_set():
                raise ValueError('%r instance needs to have a primary key value before a many-to-many relationship can be used.' % instance.__class__.__name__)

        def __call__(self, *, manager):
            manager = getattr(self.model, manager)
            manager_class = create_forward_many_to_many_manager(manager.__class__, rel, reverse)
            return manager_class(instance=self.instance)
        do_not_call_in_templates = True

        def _build_remove_filters(self, removed_vals):
            filters = Q.create([(self.source_field_name, self.related_val)])
            removed_vals_filters = not isinstance(removed_vals, QuerySet) or removed_vals._has_filters()
            if removed_vals_filters:
                filters &= Q.create([(f'{self.target_field_name}__in', removed_vals)])
            if self.symmetrical:
                symmetrical_filters = Q.create([(self.target_field_name, self.related_val)])
                if removed_vals_filters:
                    symmetrical_filters &= Q.create([(f'{self.source_field_name}__in', removed_vals)])
