        def _get_target_ids(self, target_field_name, objs):
            """
            Return the set of ids of `objs` that the target field references.
            """
            from django.db.models import Model
            target_ids = set()
            target_field = self.through._meta.get_field(target_field_name)
            for obj in objs:
                if isinstance(obj, self.model):
                    if not router.allow_relation(obj, self.instance):
                        raise ValueError('Cannot add "%r": instance is on database "%s", value is on database "%s"' % (obj, self.instance._state.db, obj._state.db))
                    target_id = target_field.get_foreign_related_value(obj)[0]
                    if target_id is None:
                        raise ValueError('Cannot add "%r": the value for field "%s" is None' % (obj, target_field_name))
                    target_ids.add(target_id)
                elif isinstance(obj, Model):
                    raise TypeError("'%s' instance expected, got %r" % (self.model._meta.object_name, obj))
                else:
                    target_ids.add(target_field.get_prep_value(obj))
            return target_ids

        def _get_missing_target_ids(self, source_field_name, target_field_name, db, target_ids):
            """
            Return the subset of ids of `objs` that aren't already assigned to
            this relationship.
            """
            vals = self.through._default_manager.using(db).values_list(target_field_name, flat=True).filter(**{source_field_name: self.related_val[0], '%s__in' % target_field_name: target_ids})
            return target_ids.difference(vals)

        def _get_add_plan(self, db, source_field_name):
            """
            Return a boolean triple of the way the add should be performed.

            The first element is whether or not bulk_create(ignore_conflicts)
            can be used, the second whether or not signals must be sent, and
            the third element is whether or not the immediate bulk insertion
            with conflicts ignored can be performed.
            """
            can_ignore_conflicts = self.through._meta.auto_created is not False and connections[db].features.supports_ignore_conflicts
            must_send_signals = (self.reverse or source_field_name == self.source_field_name) and signals.m2m_changed.has_listeners(self.through)
            return (can_ignore_conflicts, must_send_signals, can_ignore_conflicts and (not must_send_signals))

        def _add_items(self, source_field_name, target_field_name, *objs, through_defaults=None, using=None, raw=False):
            if not objs:
                return
            through_defaults = dict(resolve_callables(through_defaults or {}))
            target_ids = self._get_target_ids(target_field_name, objs)
            db = using or router.db_for_write(self.through, instance=self.instance)
            can_ignore_conflicts, must_send_signals, can_fast_add = self._get_add_plan(db, source_field_name)
            if can_fast_add:
                self.through._default_manager.using(db).bulk_create([self.through(**{'%s_id' % source_field_name: self.related_val[0], '%s_id' % target_field_name: target_id}) for target_id in target_ids], ignore_conflicts=True)
                return
            missing_target_ids = self._get_missing_target_ids(source_field_name, target_field_name, db, target_ids)
            with transaction.atomic(using=db, savepoint=False):
                if must_send_signals:
                    signals.m2m_changed.send(sender=self.through, action='pre_add', instance=self.instance, reverse=self.reverse, model=self.model, pk_set=missing_target_ids, using=db, raw=raw)
                self.through._default_manager.using(db).bulk_create([self.through(**through_defaults, **{'%s_id' % source_field_name: self.related_val[0], '%s_id' % target_field_name: target_id}) for target_id in missing_target_ids], ignore_conflicts=can_ignore_conflicts)
                if must_send_signals:
                    signals.m2m_changed.send(sender=self.through, action='post_add', instance=self.instance, reverse=self.reverse, model=self.model, pk_set=missing_target_ids, using=db, raw=raw)

        def _remove_items(self, source_field_name, target_field_name, *objs, using=None, raw=False):
            if not objs:
                return
            old_ids = set()
            for obj in objs:
                if isinstance(obj, self.model):
                    fk_val = self.target_field.get_foreign_related_value(obj)[0]
                    old_ids.add(fk_val)
                else:
                    old_ids.add(obj)
            db = using or router.db_for_write(self.through, instance=self.instance)
            with transaction.atomic(using=db, savepoint=False):
                signals.m2m_changed.send(sender=self.through, action='pre_remove', instance=self.instance, reverse=self.reverse, model=self.model, pk_set=old_ids, using=db, raw=raw)
                target_model_qs = super().get_queryset()
                if target_model_qs._has_filters():
                    old_vals = target_model_qs.using(db).filter(**{'%s__in' % self.target_field.target_field.attname: old_ids})
                else:
                    old_vals = old_ids
                filters = self._build_remove_filters(old_vals)
                self.through._default_manager.using(db).filter(filters).delete()
                signals.m2m_changed.send(sender=self.through, action='post_remove', instance=self.instance, reverse=self.reverse, model=self.model, pk_set=old_ids, using=db, raw=raw)
    return ManyRelatedManager

def __get__(self, instance, cls=None):
    if instance is None:
        return self
    try:
        rel_obj = self.field.get_cached_value(instance)
    except KeyError:
        rel_obj = None
        has_value = None not in self.field.get_local_related_value(instance)
        if has_value:
            model = self.field.model
            for current_instance, ancestor in _traverse_ancestors(model, instance):
                if ancestor:
                    rel_obj = self.field.get_cached_value(ancestor, default=None)
                    if rel_obj is not None:
                        break
        if rel_obj is None and has_value:
            instance._state.fetch_mode.fetch(self, instance)
            return self.field.get_cached_value(instance)
        self.field.set_cached_value(instance, rel_obj)
    if rel_obj is None and (not self.field.null):
        raise self.RelatedObjectDoesNotExist('%s has no %s.' % (self.field.model.__name__, self.field.name))
    else:
        return rel_obj

def __set__(self, instance, value):
    if value is not None and (not isinstance(value, self.field.remote_field.model._meta.concrete_model)):
        raise ValueError('Cannot assign "%r": "%s.%s" must be a "%s" instance.' % (value, instance._meta.object_name, self.field.name, self.field.remote_field.model._meta.object_name))
    elif value is not None:
        if instance._state.db is None:
            instance._state.db = router.db_for_write(instance.__class__, instance=value)
        if value._state.db is None:
            value._state.db = router.db_for_write(value.__class__, instance=instance)
        if not router.allow_relation(value, instance):
            raise ValueError('Cannot assign "%r": the current database router prevents this relation.' % value)
    remote_field = self.field.remote_field
    if value is None:
        related = self.field.get_cached_value(instance, default=None)
        if related is not None:
            remote_field.set_cached_value(related, None)
        for lh_field, rh_field in self.field.related_fields:
            setattr(instance, lh_field.attname, None)
    else:
        for lh_field, rh_field in self.field.related_fields:
            setattr(instance, lh_field.attname, getattr(value, rh_field.attname))
    self.field.set_cached_value(instance, value)
    if value is not None and (not remote_field.multiple):
        remote_field.set_cached_value(value, instance)

def __get__(self, instance, cls=None):
    if instance is None:
        return self
    try:
        rel_obj = self.related.get_cached_value(instance)
    except KeyError:
        if not instance._is_pk_set():
            rel_obj = None
        else:
            instance._state.fetch_mode.fetch(self, instance)
            rel_obj = self.related.get_cached_value(instance)
        self.related.set_cached_value(instance, rel_obj)
    if rel_obj is None:
        raise self.RelatedObjectDoesNotExist('%s has no %s.' % (instance.__class__.__name__, self.related.accessor_name))
    else:
        return rel_obj

def __set__(self, instance, value):
    if value is None:
        rel_obj = self.related.get_cached_value(instance, default=None)
        if rel_obj is not None:
            self.related.delete_cached_value(instance)
            setattr(rel_obj, self.related.field.name, None)
    elif not isinstance(value, self.related.related_model):
        raise ValueError('Cannot assign "%r": "%s.%s" must be a "%s" instance.' % (value, instance._meta.object_name, self.related.accessor_name, self.related.related_model._meta.object_name))
    else:
        if instance._state.db is None:
            instance._state.db = router.db_for_write(instance.__class__, instance=value)
        if value._state.db is None:
            value._state.db = router.db_for_write(value.__class__, instance=instance)
        if not router.allow_relation(value, instance):
            raise ValueError('Cannot assign "%r": the current database router prevents this relation.' % value)
        related_pk = tuple((getattr(instance, field.attname) for field in self.related.field.foreign_related_fields))
        for index, field in enumerate(self.related.field.local_related_fields):
            setattr(value, field.attname, related_pk[index])
        self.related.set_cached_value(instance, value)
        self.related.field.set_cached_value(value, instance)

