@property
def target_field(self):
    target_fields = self.path_infos[-1].target_fields
    if len(target_fields) > 1:
        raise exceptions.FieldError("Can't use target_field for multicolumn relations.")
    return target_fields[0]

def get_choices(self, include_blank=True, blank_choice=None, limit_choices_to=None, ordering=()):
    if blank_choice is None:
        blank_choice = [('', get_blank_choice_label())]
    limit_choices_to = limit_choices_to or self.limit_choices_to
    qs = self.related_model._default_manager.complex_filter(limit_choices_to)
    if ordering:
        qs = qs.order_by(*ordering)
    return (blank_choice if include_blank else []) + [(x.pk, str(x)) for x in qs]

@cached_property
def cache_name(self):
    return self.accessor_name

def get_related_field(self):
    field = self.model._meta.get_field(self.field_name)
    if not field.concrete:
        raise exceptions.FieldDoesNotExist("No related field named '%s'" % self.field_name)
    return field

def get_related_field(self):
    opts = self.through._meta
    if self.through_fields:
        field = opts.get_field(self.through_fields[0])
    else:
        for field in opts.fields:
            rel = getattr(field, 'remote_field', None)
            if rel and rel.model == self.model:
                break
    return field.foreign_related_fields[0]

def __str__(self):
    if not hasattr(self, 'model'):
        return super().__str__()
    model = self.model
    return '%s.%s' % (model._meta.label, self.name)

def deconstruct(self):
    path = f'{self.__class__.__module__}.{self.__class__.__qualname__}'
    if path.startswith('django.db.models.fields.'):
        submodule, _, remainder = path.removeprefix('django.db.models.fields.').partition('.')
        if submodule in ('related', 'files', 'generated', 'json', 'proxy', 'composite'):
            path = f'django.db.models.{remainder}'
        else:
            path = 'django.db.models' + path.removeprefix('django.db.models.fields')
    keywords = {}
    if (value := self._verbose_name) is not None:
        keywords['verbose_name'] = value
    if (value := self.primary_key) is not False:
        keywords['primary_key'] = value
    if (value := self.max_length) is not None:
        keywords['max_length'] = value
    if (value := self._unique) is not False:
        keywords['unique'] = value
    if (value := self.blank) is not False:
        keywords['blank'] = value
    if (value := self.null) is not False:
        keywords['null'] = value
    if (value := self.db_index) is not False:
        keywords['db_index'] = value
    if (value := self.default) is not NOT_PROVIDED:
        keywords['default'] = value
    if (value := self.db_default) is not NOT_PROVIDED:
        keywords['db_default'] = value
    if (value := self.editable) is not True:
        keywords['editable'] = value
    if (value := self.serialize) is not True:
        keywords['serialize'] = value
    if (value := self.unique_for_date) is not None:
        keywords['unique_for_date'] = value
    if (value := self.unique_for_month) is not None:
        keywords['unique_for_month'] = value
    if (value := self.unique_for_year) is not None:
        keywords['unique_for_year'] = value
    if (value := self.choices) is not None:
        if isinstance(value, CallableChoiceIterator):
            value = value.func
        keywords['choices'] = value
    if (value := self.help_text) != '':
        keywords['help_text'] = value
    if (value := self.db_column) is not None:
        keywords['db_column'] = value
    if (value := self.db_comment) is not None:
        keywords['db_comment'] = value
    if (value := self._db_tablespace) is not None:
        keywords['db_tablespace'] = value
    if (value := self.auto_created) is not False:
        keywords['auto_created'] = value
    if (value := self._validators) != []:
        keywords['validators'] = value
    if (value := self._error_messages) is not None:
        keywords['error_messages'] = value
    return (self.name, path, [], keywords)

def __reduce__(self):
    if not hasattr(self, 'model'):
        state = self.__dict__.copy()
        state.pop('_get_default', None)
        return (_empty, (self.__class__,), state)
    return (_load_field, (self.model._meta.app_label, self.model._meta.object_name, self.name))

def get_pk_value_on_save(self, instance):
    if self.default:
        return self.get_default()
    return None

def validate(self, value, model_instance):
    if not self.editable:
        return
    if self.choices is not None and value not in self.empty_values:
        for option_key, option_value in self.choices:
            if isinstance(option_value, (list, tuple)):
                for optgroup_key, optgroup_value in option_value:
                    if value == optgroup_key:
                        return
            elif value == option_key:
                return
        raise exceptions.ValidationError(self.error_messages['invalid_choice'], code='invalid_choice', params={'value': value})
    if value is None and (not self.null):
        raise exceptions.ValidationError(self.error_messages['null'], code='null')
    if not self.blank and value in self.empty_values:
        raise exceptions.ValidationError(self.error_messages['blank'], code='blank')

def db_check(self, connection):
    data = self.db_type_parameters(connection)
    try:
        return connection.data_type_check_constraints[self.get_internal_type()] % data
    except KeyError:
        return None

def db_type(self, connection):
    data = self.db_type_parameters(connection)
    try:
        column_type = connection.data_types[self.get_internal_type()]
    except KeyError:
        return None
    else:
        if callable(column_type):
            return column_type(data)
        return column_type % data

def cast_db_type(self, connection):
    db_type = connection.ops.cast_data_types.get(self.get_internal_type())
    if db_type:
        return db_type % self.db_type_parameters(connection)
    return self.db_type(connection)

def db_parameters(self, connection):
    type_string = self.db_type(connection)
    check_string = self.db_check(connection)
    return {'type': type_string, 'check': check_string}

def contribute_to_class(self, cls, name, private_only=False):
    self.set_attributes_from_name(name)
    self.model = cls
    cls._meta.add_field(self, private=private_only)
    if self.column:
        setattr(cls, self.attname, self.descriptor_class(self))
    if self.choices is not None:
        if 'get_%s_display' % self.name not in cls.__dict__:
            setattr(cls, 'get_%s_display' % self.name, partialmethod(cls._get_FIELD_display, field=self))

def get_prep_value(self, value):
    if isinstance(value, Promise):
        value = value._proxy____cast()
    return value

def get_db_prep_value(self, value, connection, prepared=False):
    if not prepared:
        value = self.get_prep_value(value)
    return value

def get_db_prep_save(self, value, connection):
    if hasattr(value, 'as_sql'):
        return value
    return self.get_db_prep_value(value, connection=connection, prepared=False)

def get_choices(self, include_blank=True, blank_choice=None, limit_choices_to=None, ordering=()):
    if blank_choice is None:
        blank_choice = [('', get_blank_choice_label())]
    if self.choices is not None:
        if include_blank:
            return BlankChoiceIterator(self.choices, blank_choice)
        return self.choices
    rel_model = self.remote_field.model
    limit_choices_to = limit_choices_to or self.get_limit_choices_to()
    choice_func = operator.attrgetter(self.remote_field.get_related_field().attname if hasattr(self.remote_field, 'get_related_field') else 'pk')
    qs = rel_model._default_manager.complex_filter(limit_choices_to)
    if ordering:
        qs = qs.order_by(*ordering)
    return (blank_choice if include_blank else []) + [(choice_func(x), str(x)) for x in qs]

def formfield(self, form_class=None, choices_form_class=None, **kwargs):
    defaults = {'required': not self.blank, 'label': capfirst(self.verbose_name), 'help_text': self.help_text}
    if self.has_default():
        if callable(self.default):
            defaults['initial'] = self.default
            defaults['show_hidden_initial'] = True
        else:
            defaults['initial'] = self.get_default()
    if self.choices is not None:
        include_blank = self.blank or not (self.has_default() or 'initial' in kwargs)
        defaults['choices'] = self.get_choices(include_blank=include_blank)
        defaults['coerce'] = self.to_python
        if self.null:
            defaults['empty_value'] = None
        if choices_form_class is not None:
            form_class = choices_form_class
        else:
            form_class = forms.TypedChoiceField
        for k in list(kwargs):
            if k not in ('coerce', 'empty_value', 'choices', 'required', 'widget', 'label', 'initial', 'help_text', 'error_messages', 'show_hidden_initial', 'disabled'):
                del kwargs[k]
    defaults.update(kwargs)
    if form_class is None:
        form_class = forms.CharField
    return form_class(**defaults)

def _check_if_value_fixed(self, value, now=None):
    if now is None:
        now = _get_naive_now()
    offset = datetime.timedelta(seconds=10)
    lower = now - offset
    upper = now + offset
    if isinstance(value, datetime.datetime):
        value = _to_naive(value)
    else:
        assert isinstance(value, datetime.date)
        lower = lower.date()
        upper = upper.date()
    if lower <= value <= upper:
        return [checks.Warning('Fixed default value provided.', hint='It seems you set a fixed date / time / datetime value as default for this field. This may not be what you want. If you want to have the current date as default, use `django.utils.timezone.now`', obj=self, id='fields.W161')]
    return []

def rel_db_type(self, connection):
    if connection.features.related_fields_match_type:
        return self.db_type(connection)
    else:
        return self.integer_field_class().db_type(connection=connection)

def __init__(self, expression, length, **extra):
    if not hasattr(length, 'resolve_expression'):
        if length < 1:
            raise ValueError("'length' must be greater than 0.")
    super().__init__(expression, length, **extra)

def __init__(self, expression, pos, length=None, **extra):
    if not hasattr(pos, 'resolve_expression'):
        if pos < 1:
            raise ValueError("'pos' must be greater than 0")
    expressions = [expression, pos]
    if length is not None:
        expressions.append(length)
    super().__init__(*expressions, **extra)

def cursor_iter(cursor, sentinel, col_count, itersize):
    try:
        for rows in iter(lambda: cursor.fetchmany(itersize), sentinel):
            yield (rows if col_count is None else [r[:col_count] for r in rows])
    finally:
        cursor.close()

def get_group_by(self, select, order_by):
    if self.query.group_by is None:
        return []
    expressions = []
    group_by_refs = set()
    if self.query.group_by is not True:
        for expr in self.query.group_by:
            if not hasattr(expr, 'as_sql'):
                expr = self.query.resolve_ref(expr)
            if isinstance(expr, Ref):
                if expr.refs not in group_by_refs:
                    group_by_refs.add(expr.refs)
                    expressions.append(expr.source)
            else:
                expressions.append(expr)
    selected_expr_positions = {}
    for ordinal, (expr, _, alias) in enumerate(select, start=1):
        if alias:
            selected_expr_positions[expr] = ordinal
        if alias in group_by_refs:
            continue
        expressions.extend(expr.get_group_by_cols())
    if not self._meta_ordering:
        for expr, (sql, params, is_ref) in order_by:
            if not is_ref:
                expressions.extend(expr.get_group_by_cols())
    having_group_by = self.having.get_group_by_cols() if self.having else ()
    for expr in having_group_by:
        expressions.append(expr)
    result = []
    seen = set()
    expressions = self.collapse_group_by(expressions, having_group_by)
    allows_group_by_select_index = self.connection.features.allows_group_by_select_index
    for expr in expressions:
        try:
            sql, params = self.compile(expr)
        except (EmptyResultSet, FullResultSet):
            continue
        if allows_group_by_select_index and (position := selected_expr_positions.get(expr)) is not None:
            sql, params = (str(position), ())
        else:
            sql, params = expr.select_format(self, sql, params)
        params_hash = make_hashable(params)
        if (sql, params_hash) not in seen:
            result.append((sql, params))
            seen.add((sql, params_hash))
    return result

def get_select(self, with_col_aliases=False):
    select = []
    klass_info = None
    annotations = {}
    assert not (self.query.select and self.query.default_cols)
    select_mask = self.query.get_select_mask()
    if self.query.default_cols:
        cols = self.get_default_columns(select_mask)
    else:
        cols = self.query.select
    selected = []
    select_fields = None
    if self.query.selected is None:
        selected = [*((alias, RawSQL(*args)) for alias, args in self.query.extra_select.items()), *((None, col) for col in cols), *self.query.annotation_select.items()]
        select_fields = list(range(len(self.query.extra_select), len(self.query.extra_select) + len(cols)))
    else:
        select_fields = []
        for index, (alias, expression) in enumerate(self.query.selected.items()):
            if isinstance(expression, str):
                expression = self.query.annotations[expression]
            elif isinstance(expression, int):
                select_fields.append(index)
                expression = cols[expression]
            if isinstance(expression, ColPairs):
                alias = None
            selected.append((alias, expression))
    if select_fields:
        klass_info = {'model': self.query.model, 'select_fields': select_fields}
    for select_idx, (alias, expression) in enumerate(selected):
        if alias:
            annotations[alias] = select_idx
        select.append((expression, alias))
    if self.query.select_related:
        related_klass_infos = self.get_related_selections(select, select_mask)
        klass_info['related_klass_infos'] = related_klass_infos
        self.get_select_from_parent(klass_info)
    ret = []
    col_idx = 1
    for col, alias in select:
        try:
            sql, params = self.compile(col)
        except EmptyResultSet:
            empty_result_set_value = getattr(col, 'empty_result_set_value', NotImplemented)
            if empty_result_set_value is NotImplemented:
                sql, params = ('0', ())
            else:
                sql, params = self.compile(Value(empty_result_set_value))
        except FullResultSet:
            sql, params = self.compile(Value(True))
        else:
            sql, params = col.select_format(self, sql, params)
        if alias is None and with_col_aliases:
            alias = f'col{col_idx}'
            col_idx += 1
        ret.append((col, (sql, params), alias))
    return (ret, klass_info, annotations)

def get_order_by(self):
    result = []
    seen = set()
    for expr, is_ref in self._order_by_pairs():
        resolved = expr.resolve_expression(self.query, allow_joins=True, reuse=None)
        if not is_ref and self.query.combinator and self.select:
            src = resolved.expression
            expr_src = expr.expression
            for sel_expr, _, col_alias in self.select:
                if src == sel_expr:
                    if self.query.has_select_fields and col_alias in self.query.annotation_select and (not (isinstance(expr_src, F) and col_alias == expr_src.name)):
                        continue
                    resolved.set_source_expressions([Ref(col_alias if col_alias else src.target.column, src)])
                    break
            else:
                order_by_idx = len(self.query.select) + 1
                col_alias = f'__orderbycol{order_by_idx}'
                for q in self.query.combined_queries:
                    if q.has_select_fields:
                        raise DatabaseError('ORDER BY term does not match any column in the result set.')
                    q.add_annotation(expr_src, col_alias)
                self.query.add_select_col(resolved, col_alias)
                resolved.set_source_expressions([Ref(col_alias, src)])
        sql, params = self.compile(resolved)
        without_ordering = self.ordering_parts.search(sql)[1]
        params_hash = make_hashable(params)
        if (without_ordering, params_hash) in seen:
            continue
        seen.add((without_ordering, params_hash))
        result.append((resolved, (sql, params, is_ref)))
    return result

def quote_name(self, name):
    if (quoted := self.quote_cache.get(name)) is not None:
        return quoted
    quoted = self.connection.ops.quote_name(name)
    self.quote_cache[name] = quoted
    return quoted

def as_sql(self, with_limits=True, with_col_aliases=False):
    refcounts_before = self.query.alias_refcount.copy()
    try:
        combinator = self.query.combinator
        extra_select, order_by, group_by = self.pre_sql_setup(with_col_aliases=with_col_aliases or bool(combinator))
        for_update_part = None
        with_limit_offset = with_limits and self.query.is_sliced
        combinator = self.query.combinator
        features = self.connection.features
        if combinator:
            if not getattr(features, 'supports_select_{}'.format(combinator)):
                raise NotSupportedError('{} is not supported on this database backend.'.format(combinator))
            result, params = self.get_combinator_sql(combinator, self.query.combinator_all)
        elif self.qualify:
            result, params = self.get_qualify_sql()
            order_by = None
        else:
            distinct_fields, distinct_params = self.get_distinct()
            from_, f_params = self.get_from_clause()
            try:
                where, w_params = self.compile(self.where) if self.where is not None else ('', [])
            except EmptyResultSet:
                if self.elide_empty:
                    raise
                where, w_params = ('0 = 1', [])
            except FullResultSet:
                where, w_params = ('', [])
            try:
                having, h_params = self.compile(self.having) if self.having is not None else ('', [])
            except FullResultSet:
                having, h_params = ('', [])
            result = ['SELECT']
            params = []
            if self.query.distinct:
                distinct_result, distinct_params = self.connection.ops.distinct_sql(distinct_fields, distinct_params)
                result += distinct_result
                params += distinct_params
            out_cols = []
            for _, (s_sql, s_params), alias in self.select + extra_select:
                if alias:
                    s_sql = '%s AS %s' % (s_sql, self.connection.ops.quote_name(alias))
                params.extend(s_params)
                out_cols.append(s_sql)
            result += [', '.join(out_cols)]
            if from_:
                result += ['FROM', *from_]
            elif self.connection.features.bare_select_suffix:
                result += [self.connection.features.bare_select_suffix]
            params.extend(f_params)
            if self.query.select_for_update and features.has_select_for_update:
                if self.connection.get_autocommit() and features.supports_transactions:
                    raise TransactionManagementError('select_for_update cannot be used outside of a transaction.')
                if with_limit_offset and (not features.supports_select_for_update_with_limit):
                    raise NotSupportedError('LIMIT/OFFSET is not supported with select_for_update on this database backend.')
                nowait = self.query.select_for_update_nowait
                skip_locked = self.query.select_for_update_skip_locked
                of = self.query.select_for_update_of
                no_key = self.query.select_for_no_key_update
                if nowait and (not features.has_select_for_update_nowait):
                    raise NotSupportedError('NOWAIT is not supported on this database backend.')
                elif skip_locked and (not features.has_select_for_update_skip_locked):
                    raise NotSupportedError('SKIP LOCKED is not supported on this database backend.')
                elif of and (not features.has_select_for_update_of):
                    raise NotSupportedError('FOR UPDATE OF is not supported on this database backend.')
                elif no_key and (not features.has_select_for_no_key_update):
                    raise NotSupportedError('FOR NO KEY UPDATE is not supported on this database backend.')
                for_update_part = self.connection.ops.for_update_sql(nowait=nowait, skip_locked=skip_locked, of=self.get_select_for_update_of_arguments(), no_key=no_key)
            if for_update_part and features.for_update_after_from:
                result.append(for_update_part)
            if where:
                result.append('WHERE %s' % where)
                params.extend(w_params)
            grouping = []
            for g_sql, g_params in group_by:
                grouping.append(g_sql)
                params.extend(g_params)
            if grouping:
                if distinct_fields:
                    raise NotImplementedError('annotate() + distinct(fields) is not implemented.')
                order_by = order_by or self.connection.ops.force_no_ordering()
                result.append('GROUP BY %s' % ', '.join(grouping))
                if self._meta_ordering:
                    order_by = None
            if having:
                if not grouping:
                    result.extend(self.connection.ops.force_group_by())
                result.append('HAVING %s' % having)
                params.extend(h_params)
        if self.query.explain_info:
            result.insert(0, self.connection.ops.explain_query_prefix(self.query.explain_info.format, **self.query.explain_info.options))
        if order_by:
            ordering = []
            for _, (o_sql, o_params, _) in order_by:
                ordering.append(o_sql)
                params.extend(o_params)
            order_by_sql = 'ORDER BY %s' % ', '.join(ordering)
            if combinator and features.requires_compound_order_by_subquery:
                result = ['SELECT * FROM (', *result, ')', order_by_sql]
            else:
                result.append(order_by_sql)
        if with_limit_offset:
            result.append(self.connection.ops.limit_offset_sql(self.query.low_mark, self.query.high_mark))
        if for_update_part and (not features.for_update_after_from):
            result.append(for_update_part)
        if self.query.subquery and extra_select:
            sub_selects = []
            sub_params = []
            for index, (select, _, alias) in enumerate(self.select, start=1):
                if alias:
                    sub_selects.append('%s.%s' % (self.connection.ops.quote_name('subquery'), self.connection.ops.quote_name(alias)))
                else:
                    select_clone = select.relabeled_clone({select.alias: 'subquery'})
                    subselect, subparams = select_clone.as_sql(self, self.connection)
                    sub_selects.append(subselect)
                    sub_params.extend(subparams)
            return ('SELECT %s FROM (%s) subquery' % (', '.join(sub_selects), ' '.join(result)), tuple(sub_params + params))
        return (' '.join(result), tuple(params))
    finally:
        self.query.reset_refcounts(refcounts_before)

def get_default_columns(self, select_mask, start_alias=None, opts=None, from_parent=None):
    result = []
    if opts is None:
        if (opts := self.query.get_meta()) is None:
            return result
    start_alias = start_alias or self.query.get_initial_alias()
    seen_models = {None: start_alias}
    select_mask_fields = set(composite.unnest(select_mask))
    for field in opts.concrete_fields:
        model = field.model._meta.concrete_model
        if model == opts.model:
            model = None
        if from_parent and model is not None and issubclass(from_parent._meta.concrete_model, model._meta.concrete_model):
            continue
        if select_mask and field not in select_mask_fields:
            continue
        alias = self.query.join_parent_model(opts, model, start_alias, seen_models)
        column = field.get_col(alias)
        result.append(column)
    return result

def get_distinct(self):
    result = []
    params = []
    opts = self.query.get_meta()
    for name in self.query.distinct_fields:
        parts = name.split(LOOKUP_SEP)
        _, targets, alias, joins, path, _, transform_function = self._setup_joins(parts, opts, None)
        targets, alias, _ = self.query.trim_joins(targets, joins, path)
        for target in targets:
            if name in self.query.annotation_select:
                result.append(self.connection.ops.quote_name(name))
            else:
                r, p = self.compile(transform_function(target, alias))
                result.append(r)
                params.append(p)
    return (result, params)

def get_from_clause(self):
    result = []
    params = []
    for alias, from_clause in tuple(self.query.alias_map.items()):
        if not self.query.alias_refcount[alias]:
            continue
        clause_sql, clause_params = self.compile(from_clause)
        result.append(clause_sql)
        params.extend(clause_params)
    for t in self.query.extra_tables:
        alias, _ = self.query.table_alias(t)
        if alias not in self.query.alias_map or self.query.alias_refcount[alias] == 1:
            result.append(', %s' % self.quote_name(alias))
    return (result, params)

def get_related_selections(self, select, select_mask, opts=None, root_alias=None, cur_depth=1, requested=None, restricted=None):

    def _get_field_choices():
        direct_choices = (f.name for f in opts.fields if f.is_relation)
        reverse_choices = (f.field.related_query_name() for f in opts.related_objects if f.field.unique)
        return chain(direct_choices, reverse_choices, self.query._filtered_relations)
    related_klass_infos = []
    if not restricted and cur_depth > self.query.max_depth:
        return related_klass_infos
    if not opts:
        opts = self.query.get_meta()
        root_alias = self.query.get_initial_alias()
    fields_found = set()
    if requested is None:
        restricted = isinstance(self.query.select_related, dict)
        if restricted:
            requested = self.query.select_related

    def get_related_klass_infos(klass_info, related_klass_infos):
        klass_info['related_klass_infos'] = related_klass_infos
    for f in opts.fields:
        fields_found.add(f.name)
        if restricted:
            next = requested.get(f.name, {})
            if not f.is_relation:
                if next or f.name in requested:
                    raise FieldError("Non-relational field given in select_related: '%s'. Choices are: %s" % (f.name, ', '.join(_get_field_choices()) or '(none)'))
        else:
            next = False
        if not select_related_descend(f, restricted, requested, select_mask):
            continue
        related_select_mask = select_mask.get(f) or {}
        klass_info = {'model': f.remote_field.model, 'field': f, 'reverse': False, 'local_setter': f.set_cached_value, 'remote_setter': f.remote_field.set_cached_value if f.unique else lambda x, y: None, 'from_parent': False}
        related_klass_infos.append(klass_info)
        select_fields = []
        _, _, _, joins, _, _ = self.query.setup_joins([f.name], opts, root_alias)
        alias = joins[-1]
        columns = self.get_default_columns(related_select_mask, start_alias=alias, opts=f.remote_field.model._meta)
        for col in columns:
            select_fields.append(len(select))
            select.append((col, None))
        klass_info['select_fields'] = select_fields
        next_klass_infos = self.get_related_selections(select, related_select_mask, f.remote_field.model._meta, alias, cur_depth + 1, next, restricted)
        get_related_klass_infos(klass_info, next_klass_infos)
    if restricted:
        related_fields = [(o, o.field, o.related_model) for o in opts.related_objects if o.field.unique and (not o.many_to_many)]
        for related_object, related_field, model in related_fields:
            if not select_related_descend(related_object, restricted, requested, select_mask):
                continue
            related_select_mask = select_mask.get(related_object) or {}
            related_field_name = related_field.related_query_name()
            fields_found.add(related_field_name)
            join_info = self.query.setup_joins([related_field_name], opts, root_alias)
            alias = join_info.joins[-1]
            from_parent = issubclass(model, opts.model) and model is not opts.model
            klass_info = {'model': model, 'field': related_field, 'reverse': True, 'local_setter': related_object.set_cached_value, 'remote_setter': related_field.set_cached_value, 'from_parent': from_parent}
            related_klass_infos.append(klass_info)
            select_fields = []
            columns = self.get_default_columns(related_select_mask, start_alias=alias, opts=model._meta, from_parent=opts.model)
            for col in columns:
                select_fields.append(len(select))
                select.append((col, None))
            klass_info['select_fields'] = select_fields
            next = requested.get(related_field_name, {})
            next_klass_infos = self.get_related_selections(select, related_select_mask, model._meta, alias, cur_depth + 1, next, restricted)
            get_related_klass_infos(klass_info, next_klass_infos)

        def local_setter(final_field, obj, from_obj):
            if from_obj:
                final_field.remote_field.set_cached_value(from_obj, obj)

        def local_setter_noop(obj, from_obj):
            pass

        def remote_setter(name, obj, from_obj):
            setattr(from_obj, name, obj)
        for name in list(requested):
            if cur_depth > 1:
                break
            if name in self.query._filtered_relations:
                fields_found.add(name)
                final_field, _, join_opts, joins, _, _ = self.query.setup_joins([name], opts, root_alias)
                model = join_opts.model
                alias = joins[-1]
                from_parent = issubclass(model, opts.model) and model is not opts.model
                klass_info = {'model': model, 'field': final_field, 'reverse': True, 'local_setter': partial(local_setter, final_field) if len(joins) <= 2 else local_setter_noop, 'remote_setter': partial(remote_setter, name), 'from_parent': from_parent}
                related_klass_infos.append(klass_info)
                select_fields = []
                field_select_mask = select_mask.get((name, final_field)) or {}
                columns = self.get_default_columns(field_select_mask, start_alias=alias, opts=model._meta, from_parent=opts.model)
                for col in columns:
                    select_fields.append(len(select))
                    select.append((col, None))
                klass_info['select_fields'] = select_fields
                next_requested = requested.get(name, {})
                next_klass_infos = self.get_related_selections(select, field_select_mask, opts=model._meta, root_alias=alias, cur_depth=cur_depth + 1, requested=next_requested, restricted=restricted)
                get_related_klass_infos(klass_info, next_klass_infos)
        fields_not_found = set(requested).difference(fields_found)
        if fields_not_found:
            invalid_fields = ("'%s'" % s for s in fields_not_found)
            raise FieldError('Invalid field name(s) given in select_related: %s. Choices are: %s' % (', '.join(invalid_fields), ', '.join(_get_field_choices()) or '(none)'))
    return related_klass_infos

def get_select_for_update_of_arguments(self):

    def _get_parent_klass_info(klass_info):
        concrete_model = klass_info['model']._meta.concrete_model
        for parent_model, parent_link in concrete_model._meta.parents.items():
            all_parents = parent_model._meta.all_parents
            yield {'model': parent_model, 'field': parent_link, 'reverse': False, 'select_fields': [select_index for select_index in klass_info['select_fields'] if self.select[select_index][0].target.model == parent_model or self.select[select_index][0].target.model in all_parents]}

    def _get_first_selected_col_from_model(klass_info):
        """
            Find the first selected column from a model. If it doesn't exist,
            don't lock a model.

            select_fields is filled recursively, so it also contains fields
            from the parent models.
            """
        concrete_model = klass_info['model']._meta.concrete_model
        for select_index in klass_info['select_fields']:
            if self.select[select_index][0].target.model == concrete_model:
                return self.select[select_index][0]

    def _get_field_choices():
        """Yield all allowed field paths in breadth-first search order."""
        queue = collections.deque([(None, self.klass_info)])
        while queue:
            parent_path, klass_info = queue.popleft()
            if parent_path is None:
                path = []
                yield 'self'
            else:
                field = klass_info['field']
                if klass_info['reverse']:
                    field = field.remote_field
                path = [*parent_path, field.name]
                yield LOOKUP_SEP.join(path)
            queue.extend(((path, klass_info) for klass_info in _get_parent_klass_info(klass_info)))
            queue.extend(((path, klass_info) for klass_info in klass_info.get('related_klass_infos', [])))
    if not self.klass_info:
        return []
    result = []
    invalid_names = []
    for name in self.query.select_for_update_of:
        klass_info = self.klass_info
        if name == 'self':
            col = _get_first_selected_col_from_model(klass_info)
        else:
            for part in name.split(LOOKUP_SEP):
                klass_infos = (*klass_info.get('related_klass_infos', []), *_get_parent_klass_info(klass_info))
                for related_klass_info in klass_infos:
                    field = related_klass_info['field']
                    if related_klass_info['reverse']:
                        field = field.remote_field
                    if field.name == part:
                        klass_info = related_klass_info
                        break
                else:
                    klass_info = None
                    break
            if klass_info is None:
                invalid_names.append(name)
                continue
            col = _get_first_selected_col_from_model(klass_info)
        if col is not None:
            if self.connection.features.select_for_update_of_column:
                result.append(self.compile(col)[0])
            else:
                result.append(self.quote_name(col.alias))
    if invalid_names:
        raise FieldError('Invalid field name(s) given in select_for_update(of=(...)): %s. Only relational fields followed in the query are allowed. Choices are: %s.' % (', '.join(invalid_names), ', '.join(_get_field_choices())))
    return result

def results_iter(self, results=None, tuple_expected=False, chunked_fetch=False, chunk_size=GET_ITERATOR_CHUNK_SIZE):
    if results is None:
        results = self.execute_sql(MULTI, chunked_fetch=chunked_fetch, chunk_size=chunk_size)
    fields = [s[0] for s in self.select[0:self.col_count]]
    converters = self.get_converters(fields)
    rows = chain.from_iterable(results)
    if converters:
        rows = self.apply_converters(rows, converters)
    if self.has_composite_fields(fields):
        rows = self.composite_fields_to_tuples(rows, fields)
    if tuple_expected:
        rows = map(tuple, rows)
    return rows

def execute_sql(self, result_type=MULTI, chunked_fetch=False, chunk_size=GET_ITERATOR_CHUNK_SIZE):
    result_type = result_type or NO_RESULTS
    try:
        sql, params = self.as_sql()
        if not sql:
            raise EmptyResultSet
    except EmptyResultSet:
        if result_type == MULTI:
            return iter([])
        else:
            return
    if chunked_fetch:
        cursor = self.connection.chunked_cursor()
    else:
        cursor = self.connection.cursor()
    try:
        cursor.execute(sql, params)
    except Exception as e:
        try:
            cursor.close()
        except DatabaseError:
            raise e from None
        raise
    if result_type == ROW_COUNT:
        try:
            return cursor.rowcount
        finally:
            cursor.close()
    if result_type == CURSOR:
        return cursor
    if result_type == SINGLE:
        try:
            val = cursor.fetchone()
            if val:
                return val[0:self.col_count]
            return val
        finally:
            cursor.close()
    if result_type == NO_RESULTS:
        cursor.close()
        return
    result = cursor_iter(cursor, self.connection.features.empty_fetchmany_value, self.col_count if self.has_extra_select else None, chunk_size)
    if not chunked_fetch or not self.connection.features.can_use_chunked_reads:
        return list(result)
    return result

def field_as_sql(self, field, get_placeholder_sql, val):
    if field is None:
        sql, params = (val, [])
    elif get_placeholder_sql is not None:
        sql, params = get_placeholder_sql(val, self, self.connection)
    elif hasattr(val, 'as_sql'):
        sql, params = self.compile(val)
    else:
        sql, params = ('%s', [val])
    params = self.connection.ops.modify_insert_params(sql, params)
    return (sql, params)

def prepare_value(self, field, value):
    if hasattr(value, 'resolve_expression'):
        value = value.resolve_expression(self.query, allow_joins=False, for_save=True)
        if value.contains_column_references:
            raise ValueError('Failed to insert expression "%s" on %s. F() expressions can only be used to update, not to insert.' % (value, field))
        if value.contains_aggregate:
            raise FieldError('Aggregate functions are not allowed in this query (%s=%r).' % (field.name, value))
        if value.contains_over_clause:
            raise FieldError('Window expressions are not allowed in this query (%s=%r).' % (field.name, value))
    return field.get_db_prep_save(value, connection=self.connection)

def pre_save_val(self, field, obj):
    if self.query.raw:
        return getattr(obj, field.attname)
    return field.pre_save(obj, add=True)

def assemble_as_sql(self, fields, value_rows):
    if not value_rows:
        return ([], [])
    get_placeholder_sqls = [getattr(field, 'get_placeholder_sql', None) for field in fields]
    rows_of_fields_as_sql = ((self.field_as_sql(field, get_placeholder_sql, value) for field, get_placeholder_sql, value in zip(fields, get_placeholder_sqls, row)) for row in value_rows)
    sql_and_param_pair_rows = (zip(*row) for row in rows_of_fields_as_sql)
    placeholder_rows, param_rows = zip(*sql_and_param_pair_rows)
    param_rows = [[p for ps in row for p in ps] for row in param_rows]
    return (placeholder_rows, param_rows)

def as_sql(self):
    if self.single_alias and (self.connection.features.delete_can_self_reference_subquery or not self.contains_self_reference_subquery):
        return self._as_sql(self.query)
    innerq = self.query.clone()
    innerq.__class__ = Query
    innerq.clear_select_clause()
    pk = self.query.model._meta.pk
    innerq.select = [pk.get_col(self.query.get_initial_alias())]
    outerq = Query(self.query.model)
    if not self.connection.features.update_can_self_select:
        sql, params = innerq.get_compiler(connection=self.connection).as_sql()
        innerq = RawSQL('SELECT * FROM (%s) subquery' % sql, params)
    outerq.add_filter('pk__in', innerq)
    return self._as_sql(outerq)

def as_sql(self):
    self.pre_sql_setup()
    if not self.query.values:
        return ('', ())
    qn = self.quote_name
    values, update_params = ([], [])
    for field, model, val in self.query.values:
        if hasattr(val, 'resolve_expression'):
            val = val.resolve_expression(self.query, allow_joins=False, for_save=True)
            if val.contains_aggregate:
                raise FieldError('Aggregate functions are not allowed in this query (%s=%r).' % (field.name, val))
            if val.contains_over_clause:
                raise FieldError('Window expressions are not allowed in this query (%s=%r).' % (field.name, val))
            if isinstance(val, ColPairs):
                raise FieldError("Composite primary keys expressions are not allowed in this query (%s=F('pk'))." % field.name)
        elif hasattr(val, 'prepare_database_save'):
            if field.remote_field:
                val = val.prepare_database_save(field)
            else:
                raise TypeError('Tried to update field %s with a model instance, %r. Use a value compatible with %s.' % (field, val, field.__class__.__name__))
        val = field.get_db_prep_save(val, connection=self.connection)
        quoted_name = qn(field.column)
        if (get_placeholder_sql := getattr(field, 'get_placeholder_sql', None)) is not None:
            sql, params = get_placeholder_sql(val, self, self.connection)
            values.append(f'{quoted_name} = {sql}')
            update_params.extend(params)
        elif hasattr(val, 'as_sql'):
            sql, params = self.compile(val)
            values.append(f'{quoted_name} = {sql}')
            update_params.extend(params)
        else:
            values.append(f'{quoted_name} = %s')
            update_params.append(val)
    table = self.query.base_table
    result = ['UPDATE %s SET' % qn(table), ', '.join(values)]
    try:
        where, params = self.compile(self.query.where)
    except FullResultSet:
        params = []
    else:
        result.append('WHERE %s' % where)
    if self.returning_fields:
        r_sql, self.returning_params = self.connection.ops.returning_columns(self.returning_fields)
        if r_sql:
            result.append(r_sql)
            params.extend(self.returning_params)
    return (' '.join(result), tuple(update_params + params))

def get_order_dir(field, default='ASC'):
    dirn = ORDER_DIR[default]
    if field[0] == '-':
        return (field[1:], dirn[1])
    return (field, dirn[0])

def __str__(self):
    sql, params = self.sql_with_params()
    return sql % params

def get_meta(self):
    if self.model:
        return self.model._meta

def chain(self, klass=None):
    obj = self.clone()
    if klass and obj.__class__ != klass:
        obj.__class__ = klass
    if not obj.filter_is_sticky:
        obj.used_aliases = set()
    obj.filter_is_sticky = False
    if hasattr(obj, '_setup_query'):
        obj._setup_query()
    return obj

def get_aggregation(self, using, aggregate_exprs):
    if not aggregate_exprs:
        return {}
    refs_subquery = False
    refs_window = False
    replacements = {}
    annotation_select_mask = self.annotation_select_mask
    for alias, aggregate_expr in aggregate_exprs.items():
        self.check_alias(alias)
        aggregate = aggregate_expr.resolve_expression(self, allow_joins=True, reuse=None, summarize=True)
        if not aggregate.contains_aggregate:
            raise TypeError('%s is not an aggregate expression' % alias)
        self.append_annotation_mask([alias])
        aggregate_refs = aggregate.get_refs()
        refs_subquery |= any((getattr(self.annotations[ref], 'contains_subquery', False) for ref in aggregate_refs))
        refs_window |= any((getattr(self.annotations[ref], 'contains_over_clause', True) for ref in aggregate_refs))
        aggregate = aggregate.replace_expressions(replacements)
        self.annotations[alias] = aggregate
        replacements[Ref(alias, aggregate)] = aggregate
    aggregates = {alias: self.annotations.pop(alias) for alias in aggregate_exprs}
    self.set_annotation_mask(annotation_select_mask)
    _, having, qualify = self.where.split_having_qualify()
    has_existing_aggregation = any((getattr(annotation, 'contains_aggregate', True) for annotation in self.annotations.values())) or having
    set_returning_annotations = {alias for alias, annotation in self.annotation_select.items() if getattr(annotation, 'set_returning', False)}
    if isinstance(self.group_by, tuple) or self.is_sliced or has_existing_aggregation or refs_subquery or refs_window or qualify or self.distinct or self.combinator or set_returning_annotations:
        from django.db.models.sql.subqueries import AggregateQuery
        inner_query = self.clone()
        inner_query.subquery = True
        outer_query = AggregateQuery(self.model, inner_query)
        inner_query.select_for_update = False
        inner_query.select_related = False
        inner_query.set_annotation_mask(self.annotation_select)
        if inner_query.orderby_issubset_groupby:
            inner_query.clear_ordering(force=False)
        if not inner_query.distinct:
            if inner_query.default_cols and has_existing_aggregation:
                inner_query.group_by = (self.model._meta.pk.get_col(inner_query.get_initial_alias()),)
            inner_query.default_cols = False
            if not qualify and (not self.combinator):
                annotation_mask = set()
                if isinstance(self.group_by, tuple):
                    for expr in self.group_by:
                        annotation_mask |= expr.get_refs()
                for aggregate in aggregates.values():
                    annotation_mask |= aggregate.get_refs()
                for annotation_alias, annotation in self.annotation_select.items():
                    if annotation.get_group_by_cols():
                        annotation_mask.add(annotation_alias)
                inner_query.set_annotation_mask(annotation_mask)
                annotation_mask |= set_returning_annotations
        col_refs = {}
        for alias, aggregate in aggregates.items():
            replacements = {}
            for col in self._gen_cols([aggregate], resolve_refs=False):
                if not (col_ref := col_refs.get(col)):
                    index = len(col_refs) + 1
                    col_alias = f'__col{index}'
                    col_ref = Ref(col_alias, col)
                    col_refs[col] = col_ref
                    inner_query.add_annotation(col, col_alias)
                replacements[col] = col_ref
            outer_query.annotations[alias] = aggregate.replace_expressions(replacements)
        if inner_query.select == () and (not inner_query.default_cols) and (not inner_query.annotation_select_mask):
            inner_query.select = (self.model._meta.pk.get_col(inner_query.get_initial_alias()),)
    else:
        outer_query = self
        self.select = ()
        self.selected = None
        self.default_cols = False
        self.extra = {}
        if self.annotations:
            replacements = {Ref(alias, annotation): annotation for alias, annotation in self.annotations.items()}
            self.annotations = {alias: aggregate.replace_expressions(replacements) for alias, aggregate in aggregates.items()}
        else:
            self.annotations = aggregates
        self.set_annotation_mask(aggregates)
    empty_set_result = [expression.empty_result_set_value for expression in outer_query.annotation_select.values()]
    elide_empty = not any((result is NotImplemented for result in empty_set_result))
    outer_query.clear_ordering(force=True)
    outer_query.clear_limits()
    outer_query.select_for_update = False
    outer_query.select_related = False
    compiler = outer_query.get_compiler(using, elide_empty=elide_empty)
    result = compiler.execute_sql(SINGLE)
    if result is None:
        result = empty_set_result
    else:
        cols = outer_query.annotation_select.values()
        converters = compiler.get_converters(cols)
        rows = compiler.apply_converters((result,), converters)
        if compiler.has_composite_fields(cols):
            rows = compiler.composite_fields_to_tuples(rows, cols)
        result = next(rows)
    return dict(zip(outer_query.annotation_select, result))

def get_count(self, using):
    obj = self.clone()
    return obj.get_aggregation(using, {'__count': Count('*')})['__count']

def combine(self, rhs, connector):
    if self.model != rhs.model:
        raise TypeError('Cannot combine queries on two different base models.')
    if self.is_sliced:
        raise TypeError('Cannot combine queries once a slice has been taken.')
    if self.distinct != rhs.distinct:
        raise TypeError('Cannot combine a unique query with a non-unique query.')
    if self.distinct_fields != rhs.distinct_fields:
        raise TypeError('Cannot combine queries with different distinct fields.')
    initial_alias = self.get_initial_alias()
    rhs = rhs.clone()
    rhs.bump_prefix(self, exclude={initial_alias})
    change_map = {}
    conjunction = connector == AND
    reuse = set() if conjunction else set(self.alias_map)
    joinpromoter = JoinPromoter(connector, 2, False)
    joinpromoter.add_votes((j for j in self.alias_map if self.alias_map[j].join_type == INNER))
    rhs_votes = set()
    rhs_tables = list(rhs.alias_map)[1:]
    for alias in rhs_tables:
        join = rhs.alias_map[alias]
        join = join.relabeled_clone(change_map)
        new_alias = self.join(join, reuse=reuse)
        if join.join_type == INNER:
            rhs_votes.add(new_alias)
        reuse.discard(new_alias)
        if alias != new_alias:
            change_map[alias] = new_alias
        if not rhs.alias_refcount[alias]:
            self.unref_alias(new_alias)
    joinpromoter.add_votes(rhs_votes)
    joinpromoter.update_join_types(self)
    self.subq_aliases |= rhs.subq_aliases
    w = rhs.where.clone()
    w.relabel_aliases(change_map)
    self.where.add(w, connector)
    if rhs.select:
        self.set_select([col.relabeled_clone(change_map) for col in rhs.select])
    else:
        self.select = ()
    if connector == OR:
        if self.extra and rhs.extra:
            raise ValueError("When merging querysets using 'or', you cannot have extra(select=...) on both sides.")
    self.extra.update(rhs.extra)
    extra_select_mask = set()
    if self.extra_select_mask is not None:
        extra_select_mask.update(self.extra_select_mask)
    if rhs.extra_select_mask is not None:
        extra_select_mask.update(rhs.extra_select_mask)
    if extra_select_mask:
        self.set_extra_mask(extra_select_mask)
    self.extra_tables += rhs.extra_tables
    self.order_by = rhs.order_by or self.order_by
    self.extra_order_by = rhs.extra_order_by or self.extra_order_by

def get_select_mask(self):
    field_names, defer = self.deferred_loading
    if not field_names:
        return {}
    mask = {}
    for field_name in field_names:
        part_mask = mask
        for part in field_name.split(LOOKUP_SEP):
            part_mask = part_mask.setdefault(part, {})
    opts = self.get_meta()
    if defer:
        return self._get_defer_select_mask(opts, mask)
    return self._get_only_select_mask(opts, mask)

def table_alias(self, table_name, create=False, filtered_relation=None):
    alias_list = self.table_map.get(table_name)
    if not create and alias_list:
        alias = alias_list[0]
        self.alias_refcount[alias] += 1
        return (alias, False)
    if alias_list:
        alias = '%s%d' % (self.alias_prefix, len(self.alias_map) + 1)
        alias_list.append(alias)
    else:
        alias = filtered_relation.alias if filtered_relation is not None else table_name
        self.table_map[table_name] = [alias]
    self.alias_refcount[alias] = 1
    return (alias, True)

def promote_joins(self, aliases):
    aliases = list(aliases)
    while aliases:
        alias = aliases.pop(0)
        if self.alias_map[alias].join_type is None:
            continue
        assert self.alias_map[alias].join_type is not None
        parent_alias = self.alias_map[alias].parent_alias
        parent_louter = parent_alias and self.alias_map[parent_alias].join_type == LOUTER
        already_louter = self.alias_map[alias].join_type == LOUTER
        if (self.alias_map[alias].nullable or parent_louter) and (not already_louter):
            self.alias_map[alias] = self.alias_map[alias].promote()
            aliases.extend((join for join in self.alias_map if self.alias_map[join].parent_alias == alias and join not in aliases))

def demote_joins(self, aliases):
    aliases = list(aliases)
    while aliases:
        alias = aliases.pop(0)
        if self.alias_map[alias].join_type == LOUTER:
            self.alias_map[alias] = self.alias_map[alias].demote()
            parent_alias = self.alias_map[alias].parent_alias
            if self.alias_map[parent_alias].join_type == INNER:
                aliases.append(parent_alias)

def reset_refcounts(self, to_counts):
    for alias, cur_refcount in self.alias_refcount.copy().items():
        unref_amount = cur_refcount - to_counts.get(alias, 0)
        self.unref_alias(alias, unref_amount)

def change_aliases(self, change_map):
    if not change_map:
        return self
    assert set(change_map).isdisjoint(change_map.values())
    self.where.relabel_aliases(change_map)
    if isinstance(self.group_by, tuple):
        self.group_by = tuple([col.relabeled_clone(change_map) for col in self.group_by])
    self.select = tuple([col.relabeled_clone(change_map) for col in self.select])
    self.annotations = self.annotations and {key: col.relabeled_clone(change_map) for key, col in self.annotations.items()}
    for old_alias, new_alias in change_map.items():
        if old_alias not in self.alias_map:
            continue
        alias_data = self.alias_map[old_alias].relabeled_clone(change_map)
        self.alias_map[new_alias] = alias_data
        self.alias_refcount[new_alias] = self.alias_refcount[old_alias]
        del self.alias_refcount[old_alias]
        del self.alias_map[old_alias]
        table_aliases = self.table_map[alias_data.table_name]
        for pos, alias in enumerate(table_aliases):
            if alias == old_alias:
                table_aliases[pos] = new_alias
                break
    self.external_aliases = {change_map.get(alias, alias): aliased or alias in change_map for alias, aliased in self.external_aliases.items()}
    for combined_query in self.combined_queries:
        external_change_map = {alias: aliased for alias, aliased in change_map.items() if alias in combined_query.external_aliases}
        combined_query.change_aliases(external_change_map)

def bump_prefix(self, other_query, exclude=None):

    def prefix_gen():
        """
            Generate a sequence of characters in alphabetical order:
                -> 'A', 'B', 'C', ...

            When the alphabet is finished, the sequence will continue with the
            Cartesian product:
                -> 'AA', 'AB', 'AC', ...
            """
        alphabet = ascii_uppercase
        prefix = chr(ord(self.alias_prefix) + 1)
        yield prefix
        for n in count(1):
            seq = alphabet[alphabet.index(prefix):] if prefix else alphabet
            for s in product(seq, repeat=n):
                yield ''.join(s)
            prefix = None
    if self.alias_prefix != other_query.alias_prefix:
        return
    local_recursion_limit = sys.getrecursionlimit() // 16
    for pos, prefix in enumerate(prefix_gen()):
        if prefix not in self.subq_aliases:
            self.alias_prefix = prefix
            break
        if pos > local_recursion_limit:
            raise RecursionError('Maximum recursion depth exceeded: too many subqueries.')
    self.subq_aliases = self.subq_aliases.union([self.alias_prefix])
    other_query.subq_aliases = other_query.subq_aliases.union(self.subq_aliases)
    if exclude is None:
        exclude = {}
    self.change_aliases({alias: '%s%d' % (self.alias_prefix, pos) for pos, alias in enumerate(self.alias_map) if alias not in exclude})

def get_initial_alias(self):
    if self.alias_map:
        alias = self.base_table
        self.ref_alias(alias)
    elif self.model:
        alias = self.join(self.base_table_class(self.get_meta().db_table, None))
    else:
        alias = None
    return alias

def join(self, join, reuse=None):
    reuse_aliases = [a for a, j in self.alias_map.items() if (reuse is None or a in reuse) and j == join]
    if reuse_aliases:
        if join.table_alias in reuse_aliases:
            reuse_alias = join.table_alias
        else:
            reuse_alias = reuse_aliases[-1]
        self.ref_alias(reuse_alias)
        return reuse_alias
    alias, _ = self.table_alias(join.table_name, create=True, filtered_relation=join.filtered_relation)
    if join.join_type:
        if self.alias_map[join.parent_alias].join_type == LOUTER or join.nullable:
            join_type = LOUTER
        else:
            join_type = INNER
        join.join_type = join_type
    join.table_alias = alias
    self.alias_map[alias] = join
    if (filtered_relation := join.filtered_relation):
        resolve_reuse = reuse
        if resolve_reuse is not None:
            resolve_reuse = set(reuse) | {alias}
        joins_len = len(self.alias_map)
        join.filtered_relation = filtered_relation.resolve_expression(self, reuse=resolve_reuse)
        if joins_len < len(self.alias_map):
            self.alias_map[alias] = self.alias_map.pop(alias)
    return alias

def join_parent_model(self, opts, model, alias, seen):
    if model in seen:
        return seen[model]
    chain = opts.get_base_chain(model)
    if not chain:
        return alias
    curr_opts = opts
    for int_model in chain:
        if int_model in seen:
            curr_opts = int_model._meta
            alias = seen[int_model]
            continue
        if not curr_opts.parents[int_model]:
            curr_opts = int_model._meta
            continue
        link_field = curr_opts.get_ancestor_link(int_model)
        join_info = self.setup_joins([link_field.name], curr_opts, alias)
        curr_opts = int_model._meta
        alias = seen[int_model] = join_info.joins[-1]
    return alias or seen[None]

def add_annotation(self, annotation, alias, select=True):
    self.check_alias(alias)
    annotation = annotation.resolve_expression(self, allow_joins=True, reuse=None)
    if select:
        self.append_annotation_mask([alias])
    else:
        self.set_annotation_mask(set(self.annotation_select).difference({alias}))
    self.annotations[alias] = annotation
    if select and self.selected:
        self.selected[alias] = alias

def solve_lookup_type(self, lookup, summarize=False):
    lookup_splitted = lookup.split(LOOKUP_SEP)
    if self.annotations:
        annotation, expression_lookups = refs_expression(lookup_splitted, self.annotations)
        if annotation:
            expression = self.annotations[annotation]
            if summarize:
                expression = Ref(annotation, expression)
            return (expression_lookups, (), expression)
    _, field, _, lookup_parts = self.names_to_path(lookup_splitted, self.get_meta())
    field_parts = lookup_splitted[0:len(lookup_splitted) - len(lookup_parts)]
    if len(lookup_parts) > 1 and (not field_parts):
        raise FieldError('Invalid lookup "%s" for model %s".' % (lookup, self.get_meta().model.__name__))
    return (lookup_parts, field_parts, False)

def check_filterable(self, expression):
    if hasattr(expression, 'resolve_expression') and (not getattr(expression, 'filterable', True)):
        raise NotSupportedError(expression.__class__.__name__ + ' is disallowed in the filter clause.')
    if hasattr(expression, 'get_source_expressions'):
        for expr in expression.get_source_expressions():
            self.check_filterable(expr)

def build_lookup(self, lookups, lhs, rhs):
    *transforms, lookup_name = lookups or ['exact']
    for name in transforms:
        lhs = self.try_transform(lhs, name, lookups)
    lookup_class = lhs.get_lookup(lookup_name)
    if not lookup_class:
        lhs = self.try_transform(lhs, lookup_name)
        lookup_name = 'exact'
        lookup_class = lhs.get_lookup(lookup_name)
        if not lookup_class:
            return
    lookup = lookup_class(lhs, rhs)
    if lookup.rhs is None and (not lookup.can_use_none_as_rhs):
        if lookup_name not in ('exact', 'iexact'):
            raise ValueError('Cannot use None as a query value')
        return lhs.get_lookup('isnull')(lhs, True)
    if lookup_name in ('exact', 'iexact') and lookup.rhs == '' and connections[DEFAULT_DB_ALIAS].features.interprets_empty_strings_as_nulls:
        return lhs.get_lookup('isnull')(lhs, True)
    return lookup

def try_transform(self, lhs, name, lookups=None):
    transform_class = lhs.get_transform(name)
    if transform_class:
        return transform_class(lhs)
    else:
        output_field = lhs.output_field.__class__
        suggested_lookups = difflib.get_close_matches(name, lhs.output_field.get_lookups())
        if suggested_lookups:
            suggestion = ', perhaps you meant %s?' % ' or '.join(suggested_lookups)
        else:
            suggestion = '.'
        if lookups is not None:
            name_index = lookups.index(name)
            unsupported_lookup = LOOKUP_SEP.join(lookups[name_index:])
        else:
            unsupported_lookup = name
        raise FieldError("Unsupported lookup '%s' for %s or join on the field not permitted%s" % (unsupported_lookup, output_field.__name__, suggestion))

def build_filter(self, filter_expr, branch_negated=False, current_negated=False, can_reuse=None, allow_joins=True, split_subq=True, check_filterable=True, summarize=False, update_join_types=True):
    if isinstance(filter_expr, dict):
        raise FieldError('Cannot parse keyword query as dict')
    if isinstance(filter_expr, Q):
        return self._add_q(filter_expr, branch_negated=branch_negated, current_negated=current_negated, used_aliases=can_reuse, allow_joins=allow_joins, split_subq=split_subq, check_filterable=check_filterable, summarize=summarize, update_join_types=update_join_types)
    if hasattr(filter_expr, 'resolve_expression'):
        if not getattr(filter_expr, 'conditional', False):
            raise TypeError('Cannot filter against a non-conditional expression.')
        condition = filter_expr.resolve_expression(self, allow_joins=allow_joins, reuse=can_reuse, summarize=summarize)
        if not isinstance(condition, Lookup):
            condition = self.build_lookup(['exact'], condition, True)
        return (WhereNode([condition], connector=AND), [])
    arg, value = filter_expr
    if not arg:
        raise FieldError('Cannot parse keyword query %r' % arg)
    lookups, parts, reffed_expression = self.solve_lookup_type(arg, summarize)
    if check_filterable:
        self.check_filterable(reffed_expression)
    if not allow_joins and len(parts) > 1:
        raise FieldError('Joined field references are not permitted in this query')
    pre_joins = self.alias_refcount.copy()
    value = self.resolve_lookup_value(value, can_reuse, allow_joins, summarize)
    used_joins = {k for k, v in self.alias_refcount.items() if v > pre_joins.get(k, 0)}
    if check_filterable:
        self.check_filterable(value)
    if reffed_expression:
        condition = self.build_lookup(lookups, reffed_expression, value)
        return (WhereNode([condition], connector=AND), [])
    opts = self.get_meta()
    alias = self.get_initial_alias()
    allow_many = not branch_negated or not split_subq
    try:
        join_info = self.setup_joins(parts, opts, alias, can_reuse=can_reuse, allow_many=allow_many)
        if isinstance(value, Iterator):
            value = list(value)
        self.check_related_objects(join_info.final_field, value, join_info.opts)
        self._lookup_joins = join_info.joins
    except MultiJoin as e:
        return self.split_exclude(filter_expr, can_reuse, e.names_with_path)
    used_joins.update(join_info.joins)
    targets, alias, join_list = self.trim_joins(join_info.targets, join_info.joins, join_info.path)
    if can_reuse is not None:
        can_reuse.update(join_list)
    if join_info.final_field.is_relation:
        if len(targets) == 1:
            col = self._get_col(targets[0], join_info.final_field, alias)
        else:
            col = ColPairs(alias, targets, join_info.targets, join_info.final_field)
    else:
        col = self._get_col(targets[0], join_info.final_field, alias)
    condition = self.build_lookup(lookups, col, value)
    lookup_type = condition.lookup_name
    clause = WhereNode([condition], connector=AND)
    require_outer = lookup_type == 'isnull' and condition.rhs is True and (not current_negated)
    if current_negated and (lookup_type != 'isnull' or condition.rhs is False) and (condition.rhs is not None):
        require_outer = True
        if lookup_type != 'isnull':
            if self.is_nullable(targets[0]) or self.alias_map[join_list[-1]].join_type == LOUTER:
                lookup_class = targets[0].get_lookup('isnull')
                col = self._get_col(targets[0], join_info.targets[0], alias)
                if lookup_type == 'in' and isinstance(condition.rhs, Iterable) and (not isinstance(condition.rhs, (str, bytes))) and any((v is None for v in condition.rhs)):
                    clause.add(lookup_class(col, True), OR)
                else:
                    clause.add(lookup_class(col, False), AND)
            if isinstance(value, Col) and self.is_nullable(value.target):
                lookup_class = value.target.get_lookup('isnull')
                clause.add(lookup_class(value, False), AND)
    return (clause, used_joins if not require_outer else ())

def names_to_path(self, names, opts, allow_many=True, fail_on_missing=False):
    path, names_with_path = ([], [])
    for pos, name in enumerate(names):
        cur_names_with_path = (name, [])
        if name == 'pk' and opts is not None:
            name = opts.pk.name
        field = None
        filtered_relation = None
        try:
            if opts is None:
                raise FieldDoesNotExist
            field = opts.get_field(name)
        except FieldDoesNotExist:
            if name in self.annotation_select:
                field = self.annotation_select[name].output_field
            elif name in self._filtered_relations and pos == 0:
                filtered_relation = self._filtered_relations[name]
                if LOOKUP_SEP in filtered_relation.relation_name:
                    parts = filtered_relation.relation_name.split(LOOKUP_SEP)
                    filtered_relation_path, field, _, _ = self.names_to_path(parts, opts, allow_many, fail_on_missing)
                    path.extend(filtered_relation_path[:-1])
                else:
                    field = opts.get_field(filtered_relation.relation_name)
        if field is not None:
            if field.is_relation and (not field.related_model):
                raise FieldError('Field %r does not generate an automatic reverse relation and therefore cannot be used for reverse querying. If it is a GenericForeignKey, consider adding a GenericRelation.' % name)
            try:
                model = field.model._meta.concrete_model
            except AttributeError:
                model = None
        else:
            pos -= 1
            if pos == -1 or fail_on_missing:
                available = sorted([*get_field_names_from_opts(opts), *self.annotations, *self._filtered_relations])
                raise FieldError("Cannot resolve keyword '%s' into field. Choices are: %s" % (name, ', '.join(available)))
            break
        if opts is not None and model is not opts.model:
            path_to_parent = opts.get_path_to_parent(model)
            if path_to_parent:
                path.extend(path_to_parent)
                cur_names_with_path[1].extend(path_to_parent)
                opts = path_to_parent[-1].to_opts
        if hasattr(field, 'path_infos'):
            if filtered_relation:
                pathinfos = field.get_path_info(filtered_relation)
            else:
                pathinfos = field.path_infos
            if not allow_many:
                for inner_pos, p in enumerate(pathinfos):
                    if p.m2m:
                        cur_names_with_path[1].extend(pathinfos[0:inner_pos + 1])
                        names_with_path.append(cur_names_with_path)
                        raise MultiJoin(pos + 1, names_with_path)
            last = pathinfos[-1]
            path.extend(pathinfos)
            final_field = last.join_field
            opts = last.to_opts
            targets = last.target_fields
            cur_names_with_path[1].extend(pathinfos)
            names_with_path.append(cur_names_with_path)
        else:
            final_field = field
            targets = (field,)
            if fail_on_missing and pos + 1 != len(names):
                raise FieldError("Cannot resolve keyword %r into field. Join on '%s' not permitted." % (names[pos + 1], name))
            break
    return (path, final_field, targets, names[pos + 1:])

def setup_joins(self, names, opts, alias, can_reuse=None, allow_many=True):
    joins = [alias]

    def final_transformer(field, alias):
        if not self.alias_cols:
            alias = None
        return field.get_col(alias)
    last_field_exception = None
    for pivot in range(len(names), 0, -1):
        try:
            path, final_field, targets, rest = self.names_to_path(names[:pivot], opts, allow_many, fail_on_missing=True)
        except FieldError as exc:
            if pivot == 1:
                raise
            else:
                last_field_exception = exc
        else:
            transforms = names[pivot:]
            break
    for name in transforms:

        def transform(field, alias, *, name, previous):
            try:
                wrapped = previous(field, alias)
                return self.try_transform(wrapped, name)
            except FieldError:
                if isinstance(final_field, Field) and last_field_exception:
                    raise last_field_exception
                else:
                    raise
        final_transformer = functools.partial(transform, name=name, previous=final_transformer)
        final_transformer.has_transforms = True
    for join in path:
        if join.filtered_relation:
            filtered_relation = join.filtered_relation.clone()
            table_alias = filtered_relation.alias
        else:
            filtered_relation = None
            table_alias = None
        opts = join.to_opts
        if join.direct:
            nullable = self.is_nullable(join.join_field)
        else:
            nullable = True
        connection = self.join_class(opts.db_table, alias, table_alias, INNER, join.join_field, nullable, filtered_relation=filtered_relation)
        reuse = can_reuse if join.m2m else None
        alias = self.join(connection, reuse=reuse)
        joins.append(alias)
        if join.filtered_relation and can_reuse is not None:
            can_reuse.add(alias)
    return JoinInfo(final_field, targets, opts, joins, path, final_transformer)

def trim_joins(self, targets, joins, path):
    joins = joins[:]
    for pos, info in enumerate(reversed(path)):
        if len(joins) == 1 or not info.direct:
            break
        if info.filtered_relation:
            break
        join_targets = {t.column for t in info.join_field.foreign_related_fields}
        cur_targets = {t.column for t in targets}
        if not cur_targets.issubset(join_targets):
            break
        targets_dict = {r[1].column: r[0] for r in info.join_field.related_fields if r[1].column in cur_targets}
        targets = tuple((targets_dict[t.column] for t in targets))
        self.unref_alias(joins.pop())
    return (targets, joins[-1], joins)

def set_limits(self, low=None, high=None):
    if high is not None:
        if self.high_mark is not None:
            self.high_mark = min(self.high_mark, self.low_mark + high)
        else:
            self.high_mark = self.low_mark + high
    if low is not None:
        if self.high_mark is not None:
            self.low_mark = min(self.high_mark, self.low_mark + low)
        else:
            self.low_mark = self.low_mark + low
    if self.low_mark == self.high_mark:
        self.set_empty()

def add_ordering(self, *ordering):
    errors = []
    for item in ordering:
        if isinstance(item, str):
            if item == '?':
                continue
            item = item.removeprefix('-')
            if item in self.annotations:
                continue
            if self.extra and item in self.extra:
                continue
            self.names_to_path(item.split(LOOKUP_SEP), self.model._meta)
        elif not hasattr(item, 'resolve_expression'):
            errors.append(item)
        if getattr(item, 'contains_aggregate', False):
            raise FieldError('Using an aggregate in order_by() without also including it in annotate() is not allowed: %s' % item)
    if errors:
        raise FieldError('Invalid order_by arguments: %s' % errors)
    if ordering:
        self.order_by += ordering
    else:
        self.default_ordering = False

def clear_ordering(self, force=False, clear_default=True):
    if not force and (self.is_sliced or self.distinct_fields or self.select_for_update):
        return
    self.order_by = ()
    self.extra_order_by = ()
    if clear_default:
        self.default_ordering = False
    for query in self.combined_queries:
        query.clear_ordering(force=False, clear_default=clear_default)

def add_immediate_loading(self, field_names):
    existing, defer = self.deferred_loading
    field_names = set(field_names)
    if 'pk' in field_names:
        field_names.remove('pk')
        field_names.add(self.get_meta().pk.name)
    if defer:
        self.deferred_loading = (field_names.difference(existing), False)
    else:
        self.deferred_loading = (frozenset(field_names), False)

@property
def annotation_select(self):
    if self._annotation_select_cache is not None:
        return self._annotation_select_cache
    elif not self.annotations:
        return {}
    elif self.annotation_select_mask is not None:
        self._annotation_select_cache = {k: v for k, v in self.annotations.items() if k in self.annotation_select_mask}
        return self._annotation_select_cache
    else:
        return self.annotations

def trim_start(self, names_with_path):
    all_paths = []
    for _, paths in names_with_path:
        all_paths.extend(paths)
    contains_louter = False
    lookup_tables = [t for t in self.alias_map if t in self._lookup_joins or t == self.base_table]
    for trimmed_paths, path in enumerate(all_paths):
        if path.m2m:
            break
        if self.alias_map[lookup_tables[trimmed_paths + 1]].join_type == LOUTER:
            contains_louter = True
        alias = lookup_tables[trimmed_paths]
        self.unref_alias(alias)
    join_field = path.join_field.field
    paths_in_prefix = trimmed_paths
    trimmed_prefix = []
    for name, path in names_with_path:
        if paths_in_prefix - len(path) < 0:
            break
        trimmed_prefix.append(name)
        paths_in_prefix -= len(path)
    trimmed_prefix.append(join_field.foreign_related_fields[0].name)
    trimmed_prefix = LOOKUP_SEP.join(trimmed_prefix)
    first_join = self.alias_map[lookup_tables[trimmed_paths + 1]]
    if first_join.join_type != LOUTER and (not first_join.filtered_relation):
        select_fields = [r[0] for r in join_field.related_fields]
        select_alias = lookup_tables[trimmed_paths + 1]
        self.unref_alias(lookup_tables[trimmed_paths])
        extra_restriction = join_field.get_extra_restriction(None, lookup_tables[trimmed_paths + 1])
        if extra_restriction:
            self.where.add(extra_restriction, AND)
    else:
        select_fields = [r[1] for r in join_field.related_fields]
        select_alias = lookup_tables[trimmed_paths]
    for table in self.alias_map:
        if self.alias_refcount[table] > 0:
            self.alias_map[table] = self.base_table_class(self.alias_map[table].table_name, table)
            break
    self.set_select([f.get_col(select_alias) for f in select_fields])
    return (trimmed_prefix, contains_louter)

def update_join_types(self, query):
    to_promote = set()
    to_demote = set()
    for table, votes in self.votes.items():
        if self.effective_connector == OR and votes < self.num_children:
            to_promote.add(table)
        if self.effective_connector == AND or (self.effective_connector == OR and votes == self.num_children):
            to_demote.add(table)
    query.promote_joins(to_promote)
    query.demote_joins(to_demote)
    return to_demote

def add_update_values(self, values):
    values_seq = []
    for name, val in values.items():
        field = self.get_meta().get_field(name)
        model = field.model._meta.concrete_model
        if field.name == 'pk' and model._meta.is_composite_pk:
            raise FieldError('Composite primary key fields must be updated individually.')
        if not field.concrete:
            raise FieldError('Cannot update model field %r (only concrete fields are permitted).' % field)
        if model is not self.get_meta().concrete_model:
            self.add_related_update(model, field, val)
            continue
        values_seq.append((field, model, val))
    return self.add_update_fields(values_seq)

def get_related_updates(self):
    if not self.related_updates:
        return []
    result = []
    for model, values in self.related_updates.items():
        query = UpdateQuery(model)
        query.values = values
        if self.related_ids is not None:
            query.add_filter('pk__in', self.related_ids[model])
        result.append(query)
    return result

def split_having_qualify(self, negated=False, must_group_by=False):
    if not self.contains_aggregate and (not self.contains_over_clause):
        return (self, None, None)
    in_negated = negated ^ self.negated
    must_remain_connected = in_negated and self.connector == AND or (not in_negated and self.connector == OR) or self.connector == XOR
    if must_remain_connected and self.contains_aggregate and (not self.contains_over_clause):
        return (None, self, None)
    where_parts = []
    having_parts = []
    qualify_parts = []
    for c in self.children:
        if hasattr(c, 'split_having_qualify'):
            where_part, having_part, qualify_part = c.split_having_qualify(in_negated, must_group_by)
            if where_part is not None:
                where_parts.append(where_part)
            if having_part is not None:
                having_parts.append(having_part)
            if qualify_part is not None:
                qualify_parts.append(qualify_part)
        elif c.contains_over_clause:
            qualify_parts.append(c)
        elif c.contains_aggregate:
            having_parts.append(c)
        else:
            where_parts.append(c)
    if must_remain_connected and qualify_parts:
        if not where_parts or (where_parts and (not must_group_by)):
            return (None, None, self)
        elif where_parts:
            raise NotImplementedError('Heterogeneous disjunctive predicates against window functions are not implemented when performing conditional aggregation.')
    where_node = self.create(where_parts, self.connector, self.negated) if where_parts else None
    having_node = self.create(having_parts, self.connector, self.negated) if having_parts else None
    qualify_node = self.create(qualify_parts, self.connector, self.negated) if qualify_parts else None
    return (where_node, having_node, qualify_node)

def as_sql(self, compiler, connection):
    result = []
    result_params = []
    if self.connector == AND:
        full_needed, empty_needed = (len(self.children), 1)
    else:
        full_needed, empty_needed = (1, len(self.children))
    if self.connector == XOR and (not connection.features.supports_logical_xor):
        lhs = self.__class__(self.children, OR)
        rhs_sum = reduce(operator.add, (Case(When(c, then=1), default=0) for c in self.children))
        if len(self.children) > 2:
            rhs_sum = Mod(rhs_sum, 2)
        rhs = Exact(1, rhs_sum)
        return self.__class__([lhs, rhs], AND, self.negated).as_sql(compiler, connection)
    for child in self.children:
        try:
            sql, params = compiler.compile(child)
        except EmptyResultSet:
            empty_needed -= 1
        except FullResultSet:
            full_needed -= 1
        else:
            if sql:
                result.append(sql)
                result_params.extend(params)
            else:
                full_needed -= 1
        if empty_needed == 0:
            if self.negated:
                raise FullResultSet
            else:
                raise EmptyResultSet
        if full_needed == 0:
            if self.negated:
                raise EmptyResultSet
            else:
                raise FullResultSet
    conn = ' %s ' % self.connector
    sql_string = conn.join(result)
    if not sql_string:
        raise FullResultSet
    if self.negated:
        sql_string = 'NOT (%s)' % sql_string
    elif len(result) > 1 or self.resolved:
        sql_string = '(%s)' % sql_string
    return (sql_string, result_params)

def relabel_aliases(self, change_map):
    if not change_map:
        return self
    for pos, child in enumerate(self.children):
        if hasattr(child, 'relabel_aliases'):
            child.relabel_aliases(change_map)
        elif hasattr(child, 'relabeled_clone'):
            self.children[pos] = child.relabeled_clone(change_map)

