@property
def initial_forms(self):
    return self.forms[:self.initial_form_count()]

@property
def extra_forms(self):
    return self.forms[self.initial_form_count():]

@property
def cleaned_data(self):
    if not self.is_valid():
        raise AttributeError("'%s' object has no attribute 'cleaned_data'" % self.__class__.__name__)
    return [form.cleaned_data for form in self.forms]

@property
def deleted_forms(self):
    if not self.is_valid() or not self.can_delete:
        return []
    if not hasattr(self, '_deleted_form_indexes'):
        self._deleted_form_indexes = []
        for i, form in enumerate(self.forms):
            if i >= self.initial_form_count() and (not form.has_changed()):
                continue
            if self._should_delete_form(form):
                self._deleted_form_indexes.append(i)
    return [self.forms[i] for i in self._deleted_form_indexes]

@property
def ordered_forms(self):
    if not self.is_valid() or not self.can_order:
        raise AttributeError("'%s' object has no attribute 'ordered_forms'" % self.__class__.__name__)
    if not hasattr(self, '_ordering'):
        self._ordering = []
        for i, form in enumerate(self.forms):
            if i >= self.initial_form_count() and (not form.has_changed()):
                continue
            if self.can_delete and self._should_delete_form(form):
                continue
            self._ordering.append((i, form.cleaned_data[ORDERING_FIELD_NAME]))

        def compare_ordering_key(k):
            if k[1] is None:
                return (1, 0)
            return (0, k[1])
        self._ordering.sort(key=compare_ordering_key)
    return [self.forms[i[0]] for i in self._ordering]

def non_form_errors(self):
    if self._non_form_errors is None:
        self.full_clean()
    return self._non_form_errors

@property
def errors(self):
    if self._errors is None:
        self.full_clean()
    return self._errors

def is_valid(self):
    if not self.is_bound:
        return False
    self.errors
    forms_valid = all([form.is_valid() for form in self.forms if not (self.can_delete and self._should_delete_form(form))])
    return forms_valid and (not self.non_form_errors())

def add_fields(self, form, index):
    initial_form_count = self.initial_form_count()
    if self.can_order:
        if index is not None and index < initial_form_count:
            form.fields[ORDERING_FIELD_NAME] = IntegerField(label=_('Order'), initial=index + 1, required=False, widget=self.get_ordering_widget())
        else:
            form.fields[ORDERING_FIELD_NAME] = IntegerField(label=_('Order'), required=False, widget=self.get_ordering_widget())
    if self.can_delete and (self.can_delete_extra or (index is not None and index < initial_form_count)):
        form.fields[DELETION_FIELD_NAME] = BooleanField(label=_('Delete'), required=False, widget=self.get_deletion_widget())

def is_multipart(self):
    if self.forms:
        return self.forms[0].is_multipart()
    else:
        return self.empty_form.is_multipart()

def construct_instance(form, instance, fields=None, exclude=None):
    from django.db import models
    opts = instance._meta
    cleaned_data = form.cleaned_data
    file_field_list = []
    for f in opts.fields:
        if not f.editable or isinstance(f, models.AutoField) or f.name not in cleaned_data:
            continue
        if fields is not None and f.name not in fields:
            continue
        if exclude and f.name in exclude:
            continue
        if f.has_default() and form[f.name].field.widget.value_omitted_from_data(form.data, form.files, form.add_prefix(f.name)) and (cleaned_data.get(f.name) in form[f.name].field.empty_values):
            continue
        if isinstance(f, models.FileField):
            file_field_list.append(f)
        else:
            f.save_form_data(instance, cleaned_data[f.name])
    for f in file_field_list:
        f.save_form_data(instance, cleaned_data[f.name])
    return instance

def model_to_dict(instance, fields=None, exclude=None):
    opts = instance._meta
    data = {}
    for f in chain(opts.concrete_fields, opts.private_fields, opts.many_to_many):
        if not getattr(f, 'editable', False):
            continue
        if fields is not None and f.name not in fields:
            continue
        if exclude and f.name in exclude:
            continue
        data[f.name] = f.value_from_object(instance)
    return data

def apply_limit_choices_to_to_formfield(formfield):
    from django.db.models import Exists, OuterRef, Q
    if hasattr(formfield, 'queryset') and hasattr(formfield, 'get_limit_choices_to'):
        limit_choices_to = formfield.get_limit_choices_to()
        if limit_choices_to:
            complex_filter = limit_choices_to
            if not isinstance(complex_filter, Q):
                complex_filter = Q(**limit_choices_to)
            complex_filter &= Q(pk=OuterRef('pk'))
            formfield.queryset = formfield.queryset.filter(Exists(formfield.queryset.model._base_manager.filter(complex_filter)))

def fields_for_model(model, fields=None, exclude=None, widgets=None, formfield_callback=None, localized_fields=None, labels=None, help_texts=None, error_messages=None, field_classes=None, *, apply_limit_choices_to=True, form_declared_fields=None):
    form_declared_fields = form_declared_fields or {}
    field_dict = {}
    ignored = []
    opts = model._meta
    from django.db.models import Field as ModelField
    sortable_private_fields = [f for f in opts.private_fields if isinstance(f, ModelField)]
    for f in sorted(chain(opts.concrete_fields, sortable_private_fields, opts.many_to_many)):
        if not getattr(f, 'editable', False):
            if fields is not None and f.name in fields and (exclude is None or f.name not in exclude):
                raise FieldError("'%s' cannot be specified for %s model form as it is a non-editable field" % (f.name, model.__name__))
            continue
        if fields is not None and f.name not in fields:
            continue
        if exclude and f.name in exclude:
            continue
        if f.name in form_declared_fields:
            field_dict[f.name] = form_declared_fields[f.name]
            continue
        kwargs = {}
        if widgets and f.name in widgets:
            kwargs['widget'] = widgets[f.name]
        if localized_fields == ALL_FIELDS or (localized_fields and f.name in localized_fields):
            kwargs['localize'] = True
        if labels and f.name in labels:
            kwargs['label'] = labels[f.name]
        if help_texts and f.name in help_texts:
            kwargs['help_text'] = help_texts[f.name]
        if error_messages and f.name in error_messages:
            kwargs['error_messages'] = error_messages[f.name]
        if field_classes and f.name in field_classes:
            kwargs['form_class'] = field_classes[f.name]
        if formfield_callback is None:
            formfield = f.formfield(**kwargs)
        elif not callable(formfield_callback):
            raise TypeError('formfield_callback must be a function or callable')
        else:
            formfield = formfield_callback(f, **kwargs)
        if formfield:
            if apply_limit_choices_to:
                apply_limit_choices_to_to_formfield(formfield)
            field_dict[f.name] = formfield
        else:
            ignored.append(f.name)
    if fields:
        field_dict = {f: field_dict.get(f) for f in fields if (not exclude or f not in exclude) and f not in ignored}
    return field_dict

def modelform_factory(model, form=ModelForm, fields=None, exclude=None, formfield_callback=None, widgets=None, localized_fields=None, labels=None, help_texts=None, error_messages=None, field_classes=None):
    attrs = {'model': model}
    if fields is not None:
        attrs['fields'] = fields
    if exclude is not None:
        attrs['exclude'] = exclude
    if widgets is not None:
        attrs['widgets'] = widgets
    if localized_fields is not None:
        attrs['localized_fields'] = localized_fields
    if labels is not None:
        attrs['labels'] = labels
    if help_texts is not None:
        attrs['help_texts'] = help_texts
    if error_messages is not None:
        attrs['error_messages'] = error_messages
    if field_classes is not None:
        attrs['field_classes'] = field_classes
    bases = (form.Meta,) if hasattr(form, 'Meta') else ()
    Meta = type('Meta', bases, attrs)
    if formfield_callback:
        Meta.formfield_callback = staticmethod(formfield_callback)
    class_name = model.__name__ + 'Form'
    form_class_attrs = {'Meta': Meta}
    if getattr(Meta, 'fields', None) is None and getattr(Meta, 'exclude', None) is None:
        raise ImproperlyConfigured("Calling modelform_factory without defining 'fields' or 'exclude' explicitly is prohibited.")
    return type(form)(class_name, (form,), form_class_attrs)

def _get_foreign_key(parent_model, model, fk_name=None, can_fail=False):
    from django.db.models import ForeignKey
    opts = model._meta
    if fk_name:
        fks_to_parent = [f for f in opts.fields if f.name == fk_name]
        if len(fks_to_parent) == 1:
            fk = fks_to_parent[0]
            all_parents = (*parent_model._meta.all_parents, parent_model)
            if not isinstance(fk, ForeignKey) or (fk.remote_field.model._meta.proxy and fk.remote_field.model._meta.proxy_for_model not in all_parents) or (not fk.remote_field.model._meta.proxy and fk.remote_field.model != parent_model and (fk.remote_field.model not in all_parents)):
                raise ValueError("fk_name '%s' is not a ForeignKey to '%s'." % (fk_name, parent_model._meta.label))
        elif not fks_to_parent:
            raise ValueError("'%s' has no field named '%s'." % (model._meta.label, fk_name))
    else:
        all_parents = (*parent_model._meta.all_parents, parent_model)
        fks_to_parent = [f for f in opts.fields if isinstance(f, ForeignKey) and (f.remote_field.model == parent_model or f.remote_field.model in all_parents or (f.remote_field.model._meta.proxy and f.remote_field.model._meta.proxy_for_model in all_parents))]
        if len(fks_to_parent) == 1:
            fk = fks_to_parent[0]
        elif not fks_to_parent:
            if can_fail:
                return
            raise ValueError("'%s' has no ForeignKey to '%s'." % (model._meta.label, parent_model._meta.label))
        else:
            raise ValueError("'%s' has more than one ForeignKey to '%s'. You must specify a 'fk_name' attribute." % (model._meta.label, parent_model._meta.label))
    return fk

def save(self, commit=True):
    if self.errors:
        raise ValueError("The %s could not be %s because the data didn't validate." % (self.instance._meta.object_name, 'created' if self.instance._state.adding else 'changed'))
    if commit:
        self.instance.save()
        self._save_m2m()
    else:
        self.save_m2m = self._save_m2m
    return self.instance

def initial_form_count(self):
    if not self.is_bound:
        return len(self.get_queryset())
    return super().initial_form_count()

def _get_to_python(self, field):
    while field.remote_field is not None:
        field = field.remote_field.get_related_field()
    return field.to_python

def save(self, commit=True):
    if not commit:
        self.saved_forms = []

        def save_m2m():
            for form in self.saved_forms:
                form.save_m2m()
        self.save_m2m = save_m2m
    if self.edit_only:
        return self.save_existing_objects(commit)
    else:
        return self.save_existing_objects(commit) + self.save_new_objects(commit)

def get_limit_choices_to(self):
    if callable(self.limit_choices_to):
        return self.limit_choices_to()
    return self.limit_choices_to

def _check_values(self, value):
    key = self.to_field_name or 'pk'
    try:
        value = frozenset(value)
    except TypeError:
        raise ValidationError(self.error_messages['invalid_list'], code='invalid_list')
    for pk in value:
        self.validate_no_null_characters(pk)
        try:
            self.queryset.filter(**{key: pk})
        except (ValueError, TypeError, ValidationError):
            raise ValidationError(self.error_messages['invalid_pk_value'], code='invalid_pk_value', params={'pk': pk})
    qs = self.queryset.filter(**{'%s__in' % key: value})
    pks = {str(getattr(o, key)) for o in qs}
    for val in value:
        if str(val) not in pks:
            raise ValidationError(self.error_messages['invalid_choice'], code='invalid_choice', params={'value': val})
    return qs

def pretty_name(name):
    if not name:
        return ''
    return name.replace('_', ' ').capitalize()

def flatatt(attrs):
    key_value_attrs = []
    boolean_attrs = []
    for attr, value in attrs.items():
        if isinstance(value, bool):
            if value:
                boolean_attrs.append((attr,))
        elif value is not None:
            key_value_attrs.append((attr, value))
    return format_html_join('', ' {}="{}"', sorted(key_value_attrs)) + format_html_join('', ' {}', sorted(boolean_attrs))

def from_current_timezone(value):
    if settings.USE_TZ and value is not None and timezone.is_naive(value):
        current_timezone = timezone.get_current_timezone()
        try:
            if timezone._datetime_ambiguous_or_imaginary(value, current_timezone):
                raise ValueError('Ambiguous or non-existent time.')
            return timezone.make_aware(value, current_timezone)
        except Exception as exc:
            raise ValidationError(_('%(datetime)s couldn’t be interpreted in time zone %(current_timezone)s; it may be ambiguous or it may not exist.'), code='ambiguous_timezone', params={'datetime': value, 'current_timezone': current_timezone}) from exc
    return value

def to_current_timezone(value):
    if settings.USE_TZ and value is not None and timezone.is_aware(value):
        return timezone.make_naive(value)
    return value

def absolute_path(self, path):
    if path.startswith(('http://', 'https://', '/')):
        return path
    return static(path)

def __getitem__(self, name):
    if name in MEDIA_TYPES:
        return Media(**{str(name): getattr(self, '_' + name)})
    raise KeyError('Unknown media type "%s"' % name)

@staticmethod
def merge(*lists):
    ts = TopologicalSorter()
    for head, *tail in filter(None, lists):
        ts.add(head)
        for item in tail:
            if head != item:
                ts.add(item, head)
            head = item
    try:
        return list(ts.static_order())
    except CycleError:
        warnings.warn('Detected duplicate Media files in an opposite order: {}'.format(', '.join((repr(list_) for list_ in lists))), MediaOrderConflictWarning)
        return list(dict.fromkeys(chain.from_iterable(filter(None, lists))))

def format_value(self, value):
    from django.db.models.expressions import DatabaseDefault
    if value == '' or value is None or isinstance(value, DatabaseDefault):
        return None
    if self.is_localized:
        return formats.localize_input(value)
    return str(value)

def value_from_datadict(self, data, files, name):
    getter = files.get
    if self.allow_multiple_selected:
        try:
            getter = files.getlist
        except AttributeError:
            pass
    return getter(name)

def format_value(self, value):
    if self.is_initial(value):
        return value

def format_value(self, value):
    if value is True or value is False or value is None or (value == ''):
        return
    return str(value)

def optgroups(self, name, value, attrs=None):
    groups = []
    has_selected = False
    for index, (option_value, option_label) in enumerate(self.choices):
        if option_value is None:
            option_value = ''
        subgroup = []
        if isinstance(option_label, (list, tuple)):
            group_name = option_value
            subindex = 0
            choices = option_label
        else:
            group_name = None
            subindex = None
            choices = [(option_value, option_label)]
        groups.append((group_name, subgroup, index))
        for subvalue, sublabel in choices:
            selected = (not has_selected or self.allow_multiple_selected) and str(subvalue) in value
            has_selected |= selected
            subgroup.append(self.create_option(name, subvalue, sublabel, selected, index, subindex=subindex, attrs=attrs))
            if subindex is not None:
                subindex += 1
    return groups

def id_for_label(self, id_, index='0'):
    if id_ and self.add_id_index:
        id_ = '%s_%s' % (id_, index)
    return id_

def format_value(self, value):
    if value is None and self.allow_multiple_selected:
        return []
    if not isinstance(value, (tuple, list)):
        value = [value]
    return [str(v) if v is not None else '' for v in value]

@staticmethod
def _choice_has_empty_value(choice):
    value, _ = choice
    return value is None or value == ''

def format_value(self, value):
    year, month, day = (None, None, None)
    if isinstance(value, (datetime.date, datetime.datetime)):
        year, month, day = (value.year, value.month, value.day)
    elif isinstance(value, str):
        match = self.date_re.match(value)
        if match:
            year, month, day = [int(val) or '' for val in match.groups()]
        else:
            input_format = get_format('DATE_INPUT_FORMATS')[0]
            try:
                d = datetime.datetime.strptime(value, input_format)
            except ValueError:
                pass
            else:
                year, month, day = (d.year, d.month, d.day)
    return {'year': year, 'month': month, 'day': day}

def parse_cookie(cookie):
    cookiedict = {}
    for chunk in cookie.split(';'):
        if '=' in chunk:
            key, val = chunk.split('=', 1)
        else:
            key, val = ('', chunk)
        key, val = (key.strip(), val.strip())
        if key or val:
            cookiedict[key] = cookies._unquote(val)
    return cookiedict

def parse_boundary_stream(stream, max_header_size):
    headers_chunk_size = 1024
    while True:
        if headers_chunk_size > max_header_size:
            raise MultiPartParserError('Request max total header size exceeded.')
        chunk = stream.read(headers_chunk_size)
        header_end = chunk.find(b'\r\n\r\n')
        if header_end != -1:
            break
        stream.unget(chunk)
        if len(chunk) < headers_chunk_size:
            return (RAW, {}, stream)
        headers_chunk_size *= 2
    header = chunk[:header_end]
    stream.unget(chunk[header_end + 4:])
    TYPE = RAW
    outdict = {}
    for line in header.split(b'\r\n'):
        try:
            header_name, value_and_params = line.decode().split(':', 1)
            name = header_name.lower().rstrip(' ')
            value, params = parse_header_parameters(value_and_params.lstrip(' '))
            params = {k: v.encode() for k, v in params.items()}
        except (ValueError, LookupError):
            continue
        if name == 'content-disposition':
            TYPE = FIELD
            if params.get('filename'):
                TYPE = FILE
        outdict[name] = (value, params)
    if TYPE == RAW:
        stream.unget(chunk)
    return (TYPE, outdict, stream)

def __init__(self, META, input_data, upload_handlers, encoding=None):
    content_type = META.get('CONTENT_TYPE', '')
    if not content_type.startswith('multipart/'):
        raise MultiPartParserError('Invalid Content-Type: %s' % content_type)
    try:
        content_type.encode('ascii')
    except UnicodeEncodeError:
        raise MultiPartParserError('Invalid non-ASCII Content-Type in multipart: %s' % force_str(content_type))
    _, opts = parse_header_parameters(content_type)
    boundary = opts.get('boundary')
    if not boundary or not self.boundary_re.fullmatch(boundary):
        raise MultiPartParserError('Invalid boundary in multipart: %s' % force_str(boundary))
    try:
        content_length = int(META.get('CONTENT_LENGTH', 0))
    except (ValueError, TypeError):
        content_length = 0
    if content_length < 0:
        raise MultiPartParserError('Invalid content length: %r' % content_length)
    self._boundary = boundary.encode('ascii')
    self._input_data = input_data
    possible_sizes = [x.chunk_size for x in upload_handlers if x.chunk_size]
    self._chunk_size = min([2 ** 31 - 4, *possible_sizes])
    self._meta = META
    self._encoding = encoding or settings.DEFAULT_CHARSET
    self._content_length = content_length
    self._upload_handlers = upload_handlers

def _parse(self):
    from django.http import QueryDict
    encoding = self._encoding
    handlers = self._upload_handlers
    if self._content_length == 0:
        return (QueryDict(encoding=self._encoding), MultiValueDict())
    for handler in handlers:
        result = handler.handle_raw_input(self._input_data, self._meta, self._content_length, self._boundary, encoding)
        if result is not None:
            return (result[0], result[1])
    self._post = QueryDict(mutable=True)
    self._files = MultiValueDict()
    stream = LazyStream(ChunkIter(self._input_data, self._chunk_size))
    old_field_name = None
    counters = [0] * len(handlers)
    num_bytes_read = 0
    num_post_keys = 0
    num_files = 0
    read_size = None
    uploaded_file = True
    try:
        for item_type, meta_data, field_stream in Parser(stream, self._boundary):
            if old_field_name:
                self.handle_file_complete(old_field_name, counters)
                old_field_name = None
                uploaded_file = True
            if item_type in FIELD_TYPES and settings.DATA_UPLOAD_MAX_NUMBER_FIELDS is not None:
                num_post_keys += 1
                if settings.DATA_UPLOAD_MAX_NUMBER_FIELDS + 2 < num_post_keys:
                    raise TooManyFieldsSent('The number of GET/POST parameters exceeded settings.DATA_UPLOAD_MAX_NUMBER_FIELDS.')
            try:
                disposition = meta_data['content-disposition'][1]
                field_name = disposition['name'].strip()
            except (KeyError, IndexError, AttributeError):
                continue
            transfer_encoding = meta_data.get('content-transfer-encoding')
            if transfer_encoding is not None:
                transfer_encoding = transfer_encoding[0].strip()
            field_name = force_str(field_name, encoding, errors='replace')
            if item_type == FIELD:
                if settings.DATA_UPLOAD_MAX_MEMORY_SIZE is not None:
                    read_size = settings.DATA_UPLOAD_MAX_MEMORY_SIZE - num_bytes_read
                if transfer_encoding == 'base64':
                    raw_data = field_stream.read(size=read_size)
                    num_bytes_read += len(raw_data)
                    try:
                        data = base64.b64decode(raw_data, validate=True)
                    except binascii.Error:
                        data = raw_data
                else:
                    data = field_stream.read(size=read_size)
                    num_bytes_read += len(data)
                num_bytes_read += len(field_name) + 2
                if settings.DATA_UPLOAD_MAX_MEMORY_SIZE is not None and num_bytes_read > settings.DATA_UPLOAD_MAX_MEMORY_SIZE:
                    raise RequestDataTooBig('Request body exceeded settings.DATA_UPLOAD_MAX_MEMORY_SIZE.')
                self._post.appendlist(field_name, force_str(data, encoding, errors='replace'))
            elif item_type == FILE:
                num_files += 1
                if settings.DATA_UPLOAD_MAX_NUMBER_FILES is not None and num_files > settings.DATA_UPLOAD_MAX_NUMBER_FILES:
                    raise TooManyFilesSent('The number of files exceeded settings.DATA_UPLOAD_MAX_NUMBER_FILES.')
                file_name = disposition.get('filename')
                if file_name:
                    file_name = force_str(file_name, encoding, errors='replace')
                    file_name = self.sanitize_file_name(file_name)
                if not file_name:
                    continue
                content_type, content_type_extra = meta_data.get('content-type', ('', {}))
                content_type = content_type.strip()
                charset = content_type_extra.get('charset')
                try:
                    content_length = int(meta_data.get('content-length')[0])
                except (IndexError, TypeError, ValueError):
                    content_length = None
                counters = [0] * len(handlers)
                uploaded_file = False
                try:
                    for handler in handlers:
                        try:
                            handler.new_file(field_name, file_name, content_type, content_length, charset, content_type_extra)
                        except StopFutureHandlers:
                            break
                    for chunk in field_stream:
                        if transfer_encoding == 'base64':
                            stripped_parts = [b''.join(chunk.split())]
                            stripped_length = len(stripped_parts[0])
                            while stripped_length % 4 != 0:
                                over_chunk = field_stream.read(self._chunk_size)
                                if not over_chunk:
                                    break
                                over_stripped = b''.join(over_chunk.split())
                                stripped_parts.append(over_stripped)
                                stripped_length += len(over_stripped)
                            stripped_chunk = b''.join(stripped_parts)
                            try:
                                chunk = base64.b64decode(stripped_chunk, validate=True)
                            except Exception as exc:
                                raise MultiPartParserError('Could not decode base64 data.') from exc
                        for i, handler in enumerate(handlers):
                            chunk_length = len(chunk)
                            chunk = handler.receive_data_chunk(chunk, counters[i])
                            counters[i] += chunk_length
                            if chunk is None:
                                break
                except SkipFile:
                    self._close_files()
                    exhaust(field_stream)
                else:
                    old_field_name = field_name
            else:
                exhaust(field_stream)
    except StopUpload as e:
        self._close_files()
        if not e.connection_reset:
            exhaust(self._input_data)
    else:
        if not uploaded_file:
            for handler in handlers:
                handler.upload_interrupted()
        exhaust(self._input_data)
    any((handler.upload_complete() for handler in handlers))
    self._post._mutable = False
    return (self._post, self._files)

def __next__(self):
    if self._leftover:
        output = self._leftover
        self._leftover = b''
    else:
        output = next(self._producer)
        self._unget_history = []
    self.position += len(output)
    return output

def unget(self, bytes):
    if not bytes:
        return
    self._update_unget_history(len(bytes))
    self.position -= len(bytes)
    self._leftover = bytes + self._leftover

def _find_boundary(self, data):
    index = data.find(self._boundary)
    if index < 0:
        return None
    else:
        end = index
        next = index + len(self._boundary)
        last = max(0, end - 1)
        if data[last:last + 1] == b'\n':
            end -= 1
        last = max(0, end - 1)
        if data[last:last + 1] == b'\r':
            end -= 1
        return (end, next)

def bytes_to_text(s, encoding):
    if isinstance(s, bytes):
