def _convert_to_charset(self, value, charset, mime_encode=False):
    try:
        if isinstance(value, str):
            value.encode(charset)
        elif isinstance(value, bytes):
            value = value.decode(charset)
        else:
            value = str(value)
            value.encode(charset)
        if '\n' in value or '\r' in value:
            raise BadHeaderError(f"Header values can't contain newlines (got {value!r})")
    except UnicodeError as e:
        if isinstance(value, bytes) and (b'\n' in value or b'\r' in value) or (isinstance(value, str) and ('\n' in value or '\r' in value)):
            raise BadHeaderError(f"Header values can't contain newlines (got {value!r})") from e
        if mime_encode:
            value = Header(value, 'utf-8', maxlinelen=sys.maxsize).encode()
        else:
            e.reason += ', HTTP response headers must be in %s format' % charset
            raise
    return value

def set_cookie(self, key, value='', max_age=None, expires=None, path='/', domain=None, secure=False, httponly=False, samesite=None):
    self.cookies[key] = value
    if expires is not None:
        if isinstance(expires, datetime.datetime):
            if timezone.is_naive(expires):
                expires = timezone.make_aware(expires, datetime.UTC)
            delta = expires - datetime.datetime.now(tz=datetime.UTC)
            delta += datetime.timedelta(seconds=1)
            expires = None
            if max_age is not None:
                raise ValueError("'expires' and 'max_age' can't be used together.")
            max_age = max(0, delta.days * 86400 + delta.seconds)
        else:
            self.cookies[key]['expires'] = expires
    else:
        self.cookies[key]['expires'] = ''
    if max_age is not None:
        if isinstance(max_age, datetime.timedelta):
            max_age = max_age.total_seconds()
        self.cookies[key]['max-age'] = int(max_age)
        if not expires:
            self.cookies[key]['expires'] = http_date(time.time() + max_age)
    if path is not None:
        self.cookies[key]['path'] = path
    if domain is not None:
        self.cookies[key]['domain'] = domain
    if secure:
        self.cookies[key]['secure'] = True
    if httponly:
        self.cookies[key]['httponly'] = True
    if samesite:
        if samesite.lower() not in ('lax', 'none', 'strict'):
            raise ValueError('samesite must be "lax", "none", or "strict".')
        self.cookies[key]['samesite'] = samesite

def make_bytes(self, value):
    if isinstance(value, (bytes, memoryview)):
        return bytes(value)
    if isinstance(value, str):
        return bytes(value.encode(self.charset))
    return str(value).encode(self.charset)

def set_headers(self, filelike):
    filename = getattr(filelike, 'name', '')
    filename = filename if isinstance(filename, str) else ''
    seekable = hasattr(filelike, 'seek') and (not hasattr(filelike, 'seekable') or filelike.seekable())
    if hasattr(filelike, 'tell'):
        if seekable:
            initial_position = filelike.tell()
            filelike.seek(0, io.SEEK_END)
            self.headers['Content-Length'] = filelike.tell() - initial_position
            filelike.seek(initial_position)
        elif hasattr(filelike, 'getbuffer'):
            self.headers['Content-Length'] = filelike.getbuffer().nbytes - filelike.tell()
        elif os.path.exists(filename):
            self.headers['Content-Length'] = os.path.getsize(filename) - filelike.tell()
    elif seekable:
        self.headers['Content-Length'] = sum(iter(lambda: len(filelike.read(self.block_size)), 0))
        filelike.seek(-int(self.headers['Content-Length']), io.SEEK_END)
    filename = os.path.basename(self.filename or filename)
    if self._no_explicit_content_type:
        if filename:
            content_type, encoding = mimetypes.guess_type(filename)
            content_type = {'br': 'application/x-brotli', 'bzip2': 'application/x-bzip', 'compress': 'application/x-compress', 'gzip': 'application/gzip', 'xz': 'application/x-xz'}.get(encoding, content_type)
            self.headers['Content-Type'] = content_type or 'application/octet-stream'
        else:
            self.headers['Content-Type'] = 'application/octet-stream'
    if (content_disposition := content_disposition_header(self.as_attachment, filename)):
        self.headers['Content-Disposition'] = content_disposition

def process_request(self, request):
    user_agent = request.META.get('HTTP_USER_AGENT')
    if user_agent is not None:
        for user_agent_regex in settings.DISALLOWED_USER_AGENTS:
            if user_agent_regex.search(user_agent):
                raise PermissionDenied('Forbidden user agent')
    host = request.get_host()
    if settings.PREPEND_WWW and host and (not host.startswith('www.')):
        if self.should_redirect_with_slash(request):
            path = self.get_full_path_with_slash(request)
        else:
            path = request.get_full_path()
        return self.response_redirect_class(f'{request.scheme}://www.{host}{path}')

def should_redirect_with_slash(self, request):
    if settings.APPEND_SLASH and (not request.path_info.endswith('/')):
        urlconf = getattr(request, 'urlconf', None)
        if not is_valid_path(request.path_info, urlconf):
            match = is_valid_path('%s/' % request.path_info, urlconf)
            if match:
                view = match.func
                return getattr(view, 'should_append_slash', True)
    return False

def get_full_path_with_slash(self, request):
    new_path = request.get_full_path(force_append_slash=True)
    new_path = escape_leading_slashes(new_path)
    if settings.DEBUG and request.method in ('DELETE', 'POST', 'PUT', 'PATCH'):
        raise RuntimeError("You called this URL via %(method)s, but the URL doesn't end in a slash and you have APPEND_SLASH set. Django can't redirect to the slash URL while maintaining %(method)s data. Change your form to point to %(url)s (note the trailing slash), or set APPEND_SLASH=False in your Django settings." % {'method': request.method, 'url': request.get_host() + new_path})
    return new_path

def process_response(self, request, response):
    if response.status_code == 404 and self.should_redirect_with_slash(request):
        response = self.response_redirect_class(self.get_full_path_with_slash(request))
    if not response.streaming and (not response.has_header('Content-Length')):
        response.headers['Content-Length'] = str(len(response.content))
    return response

def is_ignorable_request(self, request, uri, domain, referer):
    if not referer:
        return True
    if settings.APPEND_SLASH and uri.endswith('/') and (referer == uri[:-1]):
        return True
    if not self.is_internal_request(domain, referer) and '?' in referer:
        return True
    parsed_referer = urlsplit(referer)
    if parsed_referer.netloc in ['', domain] and parsed_referer.path == uri:
        return True
    return any((pattern.search(uri) for pattern in settings.IGNORABLE_404_URLS))

def _unmask_cipher_token(token):
    mask = token[:CSRF_SECRET_LENGTH]
    token = token[CSRF_SECRET_LENGTH:]
    chars = CSRF_ALLOWED_CHARS
    pairs = zip((chars.index(x) for x in token), (chars.index(x) for x in mask))
    return ''.join((chars[x - y] for x, y in pairs))

