def token_kwargs(bits, parser, support_legacy=False):
    if not bits:
        return {}
    match = kwarg_re.match(bits[0])
    kwarg_format = match and match[1]
    if not kwarg_format:
        if not support_legacy:
            return {}
        if len(bits) < 3 or bits[1] != 'as':
            return {}
    kwargs = {}
    while bits:
        if kwarg_format:
            match = kwarg_re.match(bits[0])
            if not match or not match[1]:
                return kwargs
            key, value = match.groups()
            del bits[:1]
        else:
            if len(bits) < 3 or bits[1] != 'as':
                return kwargs
            key, value = (bits[2], bits[0])
            del bits[:3]
        kwargs[key] = parser.compile_filter(value)
        if bits and (not kwarg_format):
            if bits[0] != 'and':
                return kwargs
            del bits[:1]
    return kwargs

def tokenize(self):
    in_tag = False
    lineno = 1
    result = []
    for token_string in tag_re.split(self.template_string):
        if token_string:
            result.append(self.create_token(token_string, None, lineno, in_tag))
            lineno += token_string.count('\n')
        in_tag = not in_tag
    return result

def create_token(self, token_string, position, lineno, in_tag):
    if in_tag:
        token_start = token_string[0:2]
        if token_start == BLOCK_TAG_START:
            content = token_string[2:-2].strip()
            if self.verbatim:
                if content != self.verbatim:
                    return Token(TokenType.TEXT, token_string, position, lineno)
                self.verbatim = False
            elif content[:9] in ('verbatim', 'verbatim '):
                self.verbatim = 'end%s' % content
            return Token(TokenType.BLOCK, content, position, lineno)
        if not self.verbatim:
            content = token_string[2:-2].strip()
            if token_start == VARIABLE_TAG_START:
                return Token(TokenType.VAR, content, position, lineno)
            assert token_start == COMMENT_TAG_START
            return Token(TokenType.COMMENT, content, position, lineno)
    return Token(TokenType.TEXT, token_string, position, lineno)

def parse(self, parse_until=None):
    if parse_until is None:
        parse_until = []
    nodelist = NodeList()
    while self.tokens:
        token = self.next_token()
        token_type = token.token_type.value
        if token_type == 0:
            self.extend_nodelist(nodelist, TextNode(token.contents), token)
        elif token_type == 1:
            if not token.contents:
                raise self.error(token, 'Empty variable tag on line %d' % token.lineno)
            try:
                filter_expression = self.compile_filter(token.contents)
            except TemplateSyntaxError as e:
                raise self.error(token, e)
            var_node = VariableNode(filter_expression)
            if '..' in str(filter_expression.var):
                warnings.warn(f"Support for double-dot lookups '..' which maps to a lookup of the empty string is deprecated.\n  Template: {self.origin.name}\n  Line: {token.lineno}", RemovedInDjango70Warning, skip_file_prefixes=django_file_prefixes())
            self.extend_nodelist(nodelist, var_node, token)
        elif token_type == 2:
            try:
                command = token.contents.split()[0]
            except IndexError:
                raise self.error(token, 'Empty block tag on line %d' % token.lineno)
            if command in parse_until:
                self.prepend_token(token)
                return nodelist
            self.command_stack.append((command, token))
            try:
                compile_func = self.tags[command]
            except KeyError:
                self.invalid_block_tag(token, command, parse_until)
            try:
                compiled_result = compile_func(self, token)
            except Exception as e:
                raise self.error(token, e)
            self.extend_nodelist(nodelist, compiled_result, token)
            self.command_stack.pop()
    if parse_until:
        self.unclosed_block_tag(parse_until)
    return nodelist

def error(self, token, e):
    if not isinstance(e, Exception):
        e = TemplateSyntaxError(e)
    if not hasattr(e, 'token'):
        e.token = token
    return e

def resolve(self, context):
    if self.lookups is not None:
        value = self._resolve_lookup(context)
    else:
        value = self.literal
    if self.translate:
        is_safe = isinstance(value, SafeData)
        msgid = value.replace('%', '%%')
        msgid = mark_safe(msgid) if is_safe else msgid
        if self.message_context:
            return pgettext_lazy(self.message_context, msgid)
        else:
            return gettext_lazy(msgid)
    return value

def _resolve_lookup(self, context):
    current = context
    try:
        for bit in self.lookups:
            try:
                if not hasattr(type(current), '__getitem__'):
                    raise TypeError
                current = current[bit]
            except (TypeError, AttributeError, KeyError, ValueError, IndexError):
                try:
                    if isinstance(current, BaseContext) and getattr(type(current), bit):
                        raise AttributeError
                    current = getattr(current, bit)
                except (TypeError, AttributeError):
                    if not isinstance(current, BaseContext) and bit in dir(current):
                        raise
                    try:
                        current = current[int(bit)]
                    except (IndexError, ValueError, KeyError, TypeError):
                        raise VariableDoesNotExist('Failed lookup for key [%s] in %r', (bit, current))
            if callable(current):
                if getattr(current, 'do_not_call_in_templates', False):
                    pass
                elif getattr(current, 'alters_data', False):
                    current = context.template.engine.string_if_invalid
                else:
                    try:
                        current = current()
                    except TypeError:
                        try:
                            current_signature = signature(current)
                        except ValueError:
                            current = context.template.engine.string_if_invalid
                        else:
                            try:
                                current_signature.bind()
                            except TypeError:
                                current = context.template.engine.string_if_invalid
                            else:
                                raise
    except Exception as e:
        template_name = getattr(context, 'template_name', None) or 'unknown'
        logger.debug("Exception while resolving variable '%s' in template '%s'.", bit, template_name, exc_info=True)
        if getattr(e, 'silent_variable_failure', False):
            current = context.template.engine.string_if_invalid
        else:
            raise
    return current

def get_nodes_by_type(self, nodetype):
    nodes = []
    if isinstance(self, nodetype):
        nodes.append(self)
    for attr in self.child_nodelists:
        nodelist = getattr(self, attr, None)
        if nodelist:
            nodes.extend(nodelist.get_nodes_by_type(nodetype))
    return nodes

def get_nodes_by_type(self, nodetype):
    nodes = []
    for node in self:
        nodes.extend(node.get_nodes_by_type(nodetype))
    return nodes

def make_context(context, request=None, **kwargs):
    if context is not None and (not isinstance(context, dict)):
        raise TypeError('context must be a dict rather than %s.' % context.__class__.__name__)
    if request is None:
        context = Context(context, **kwargs)
    else:
        original_context = context
        context = RequestContext(request, **kwargs)
        if original_context:
            context.push(original_context)
    return context

def __getitem__(self, key):
    for d in reversed(self.dicts):
        if key in d:
            return d[key]
    raise KeyError(key)

def flatten(self):
    flat = {}
    for d in self.dicts:
        flat.update(d)
