def copy_exception(exc, backend=None):
    backend = backend or exc.backend
    new = exc.__class__(*exc.args, tried=exc.tried, backend=backend, chain=exc.chain)
    if hasattr(exc, 'template_debug'):
        new.template_debug = exc.template_debug
    return new

def get_exception_info(exception):
    context_lines = 10
    lineno = exception.lineno
    source = exception.source
    if source is None:
        exception_file = Path(exception.filename)
        if exception_file.exists():
            source = exception_file.read_text()
    if source is not None:
        lines = list(enumerate(source.strip().split('\n'), start=1))
        during = lines[lineno - 1][1]
        total = len(lines)
        top = max(0, lineno - context_lines - 1)
        bottom = min(total, lineno + context_lines)
    else:
        during = ''
        lines = []
        total = top = bottom = 0
    return {'name': exception.filename, 'message': exception.message, 'source_lines': lines[top:bottom], 'line': lineno, 'before': '', 'during': during, 'after': '', 'total': total, 'top': top, 'bottom': bottom}

def get_template(self, template_name, skip=None):
    tried = []
    for origin in self.get_template_sources(template_name):
        if skip is not None and origin in skip:
            tried.append((origin, 'Skipped to avoid recursion'))
            continue
        try:
            contents = self.get_contents(origin)
        except TemplateDoesNotExist:
            tried.append((origin, 'Source does not exist'))
            continue
        else:
            return Template(contents, origin, origin.template_name, self.engine)
    raise TemplateDoesNotExist(template_name, tried=tried)

def cache_key(self, template_name, skip=None):
    skip_prefix = ''
    if skip:
        matching = [origin.name for origin in skip if origin.template_name == template_name]
        if matching:
            skip_prefix = self.generate_hash(matching)
    return '-'.join((s for s in (str(template_name), skip_prefix) if s))

def get_template_sources(self, template_name):
    for template_dir in self.get_dirs():
        try:
            name = safe_join(template_dir, template_name)
        except SuspiciousFileOperation:
            continue
        yield Origin(name=name, template_name=template_name, loader=self)

