@classmethod
def handle_token(cls, parser, token, name):
    tokens = token.contents.split()
    if len(tokens) > 1 and tokens[1] != 'as':
        raise template.TemplateSyntaxError("First argument in '%s' must be 'as'" % tokens[0])
    if len(tokens) > 1:
        varname = tokens[2]
    else:
        varname = None
    return cls(varname, name)

@classmethod
def handle_token(cls, parser, token):
    bits = token.split_contents()
    if len(bits) < 2:
        raise template.TemplateSyntaxError("'%s' takes at least one argument (path to file)" % bits[0])
    path = parser.compile_filter(bits[1])
    if len(bits) >= 2 and bits[-2] == 'as':
        varname = bits[3]
    else:
        varname = None
    return cls(varname, path)

@register.filter
def localtime(value):
    return do_timezone(value, timezone.get_current_timezone())

@register.filter
def utc(value):
    return do_timezone(value, UTC)

@register.filter('timezone')
def do_timezone(value, arg):
    if not isinstance(value, datetime):
        return ''
    try:
        if timezone.is_naive(value):
            default_timezone = timezone.get_default_timezone()
            value = timezone.make_aware(value, default_timezone)
    except Exception:
        return ''
    if isinstance(arg, tzinfo):
        tz = arg
    elif isinstance(arg, str):
        try:
            tz = zoneinfo.ZoneInfo(arg)
        except zoneinfo.ZoneInfoNotFoundError:
            return ''
    else:
        return ''
    result = timezone.localtime(value, tz)
    result = datetimeobject(result.year, result.month, result.day, result.hour, result.minute, result.second, result.microsecond, result.tzinfo)
    result.convert_to_local_time = False
    return result

def set_script_prefix(prefix):
