def is_valid_path(path, urlconf=None):
    try:
        return resolve(path, urlconf)
    except Resolver404:
        return False

def translate_url(url, lang_code):
    parsed = urlsplit(url)
    try:
        match = resolve(unquote(parsed.path))
    except Resolver404:
        pass
    else:
        to_be_reversed = '%s:%s' % (match.namespace, match.url_name) if match.namespace else match.url_name
        with override(lang_code):
            try:
                url = reverse(to_be_reversed, args=match.args, kwargs=match.kwargs)
            except NoReverseMatch:
                pass
            else:
                url = urlunsplit((parsed.scheme, parsed.netloc, url, parsed.query, parsed.fragment))
    return url

@functools.lru_cache
def _route_to_regex(route, is_endpoint):
    parts = ['^']
    all_converters = get_converters()
    converters = {}
    previous_end = 0
    for match_ in _PATH_PARAMETER_COMPONENT_RE.finditer(route):
        if not whitespace_set.isdisjoint(match_[0]):
            raise ImproperlyConfigured(f'URL route {route!r} cannot contain whitespace in angle brackets <…>.')
        raw_converter, parameter = match_.groups(default='str')
        if not parameter.isidentifier():
            raise ImproperlyConfigured(f"URL route {route!r} uses parameter name {parameter!r} which isn't a valid Python identifier.")
        try:
            converter = all_converters[raw_converter]
        except KeyError as e:
            raise ImproperlyConfigured(f'URL route {route!r} uses invalid converter {raw_converter!r}.') from e
        converters[parameter] = converter
        start, end = match_.span()
        parts.append(re.escape(route[previous_end:start]))
        previous_end = end
        parts.append(f'(?P<{parameter}>{converter.regex})')
    parts.append(re.escape(route[previous_end:]))
    if is_endpoint:
        parts.append('\\Z')
    return (''.join(parts), converters)

def __get__(self, instance, cls=None):
    if instance is None:
        return self
    pattern = instance._regex
    if isinstance(pattern, str):
        instance.__dict__['regex'] = self._compile(pattern)
        return instance.__dict__['regex']
    language_code = get_language()
    if language_code not in instance._regex_dict:
        instance._regex_dict[language_code] = self._compile(str(pattern))
    return instance._regex_dict[language_code]

def __get__(self, instance, cls=None):
    if instance is None:
        return self
    if isinstance(instance._route, str):
        instance.__dict__['regex'] = re.compile(instance._regex)
        return instance.__dict__['regex']
    language_code = get_language()
    if language_code not in instance._regex_dict:
        instance._regex_dict[language_code] = re.compile(_route_to_regex(str(instance._route), instance._is_endpoint)[0])
    return instance._regex_dict[language_code]

@functools.cache
def get_callable(lookup_view):
    if callable(lookup_view):
        return lookup_view
    if not isinstance(lookup_view, str):
        raise ViewDoesNotExist("'%s' is not a callable or a dot-notation path" % lookup_view)
    mod_name, func_name = get_mod_func(lookup_view)
    if not func_name:
        raise ImportError("Could not import '%s'. The path must be fully qualified." % lookup_view)
    try:
        mod = import_module(mod_name)
    except ImportError:
        parentmod, submod = get_mod_func(mod_name)
        if submod and (not module_has_submodule(import_module(parentmod), submod)):
            raise ViewDoesNotExist("Could not import '%s'. Parent module %s does not exist." % (lookup_view, mod_name))
        else:
            raise
    else:
        try:
            view_func = getattr(mod, func_name)
        except AttributeError:
            raise ViewDoesNotExist("Could not import '%s'. View does not exist in module %s." % (lookup_view, mod_name))
        else:
            if not callable(view_func):
                raise ViewDoesNotExist("Could not import '%s.%s'. View is not callable." % (mod_name, func_name))
            return view_func

def replace_named_groups(pattern):
    group_pattern_and_name = [(pattern[start:end], match[1]) for start, end, match in _find_groups(pattern, _NAMED_GROUP_MATCHER)]
    for group_pattern, group_name in group_pattern_and_name:
        pattern = pattern.replace(group_pattern, group_name)
    return pattern

def replace_unnamed_groups(pattern):
    final_pattern, prev_end = ('', None)
    for start, end, _ignored in _find_groups(pattern, _UNNAMED_GROUP_MATCHER):
        if prev_end:
            final_pattern += pattern[prev_end:start]
        final_pattern += pattern[:start] + '<var>'
        prev_end = end
    return final_pattern + pattern[prev_end:]

def extract_views_from_urlpatterns(urlpatterns, base='', namespace=None):
    views = []
    for p in urlpatterns:
        if hasattr(p, 'url_patterns'):
            try:
                patterns = p.url_patterns
            except ImportError:
                continue
            views.extend(extract_views_from_urlpatterns(patterns, base + str(p.pattern), (namespace or []) + (p.namespace and [p.namespace] or [])))
        elif hasattr(p, 'callback'):
            try:
                views.append((p.callback, base + str(p.pattern), namespace, p.name))
            except ViewDoesNotExist:
                continue
        else:
            raise TypeError(_('%s does not appear to be a urlpattern object') % p)
    return views

def extract(path, to_path):
    with Archive(path) as archive:
        archive.extract(to_path)

def has_leading_dir(self, paths):
    common_prefix = None
    for path in paths:
        prefix, rest = self.split_leading_dir(path)
        if not prefix:
            return False
        elif common_prefix is None:
            common_prefix = prefix
        elif prefix != common_prefix:
            return False
    return True

def async_unsafe(message):

    def decorator(func):

        @wraps(func)
        def inner(*args, **kwargs):
            try:
                get_running_loop()
            except RuntimeError:
                pass
            else:
                if not os.environ.get('DJANGO_ALLOW_ASYNC_UNSAFE'):
                    raise SynchronousOnlyOperation(message)
            return func(*args, **kwargs)
        return inner
    if callable(message):
        func = message
        message = 'You cannot call this from an async context - use a thread or sync_to_async.'
        return decorator(func)
    else:
        return decorator
